https://github.com/code-423n4/2022-11-paraspace/blob/c6820a279c64a299a783955749fdc977de8f0449/paraspace-core/contracts/misc/ParaSpaceFallbackOracle.sol#L78


# Vulnerability details

## Impact

Fallback oracle is using spot price in Uniswap liquidity pool, which is very vulnerable to flashloan price manipulation. Hacker can use flashloan to distort the price and overborrow or perform malicious liqudiation.

## Proof of Concept

In the current implementation of the paraspace oracle, if the paraspace oracle has issue, the fallback oracle is used for ERC20 token.

```solidity
/// @inheritdoc IPriceOracleGetter
function getAssetPrice(address asset)
	public
	view
	override
	returns (uint256)
{
	if (asset == BASE_CURRENCY) {
		return BASE_CURRENCY_UNIT;
	}

	uint256 price = 0;
	IEACAggregatorProxy source = IEACAggregatorProxy(assetsSources[asset]);
	if (address(source) != address(0)) {
		price = uint256(source.latestAnswer());
	}
	if (price == 0 && address(_fallbackOracle) != address(0)) {
		price = _fallbackOracle.getAssetPrice(asset);
	}

	require(price != 0, Errors.ORACLE_PRICE_NOT_READY);
	return price;
}
```


which calls:

```solidity
price = _fallbackOracle.getAssetPrice(asset);
```

whch use the spot price from Uniswap V2.

```solidity
	address pairAddress = IUniswapV2Factory(UNISWAP_FACTORY).getPair(
		WETH,
		asset
	);
	require(pairAddress != address(0x00), "pair not found");
	IUniswapV2Pair pair = IUniswapV2Pair(pairAddress);
	(uint256 left, uint256 right, ) = pair.getReserves();
	(uint256 tokenReserves, uint256 ethReserves) = (asset < WETH)
		? (left, right)
		: (right, left);
	uint8 decimals = ERC20(asset).decimals();
	//returns price in 18 decimals
	return
		IUniswapV2Router01(UNISWAP_ROUTER).getAmountOut(
			10**decimals,
			tokenReserves,
			ethReserves
		);
```

and

```solidity
function getEthUsdPrice() public view returns (uint256) {
	address pairAddress = IUniswapV2Factory(UNISWAP_FACTORY).getPair(
		USDC,
		WETH
	);
	require(pairAddress != address(0x00), "pair not found");
	IUniswapV2Pair pair = IUniswapV2Pair(pairAddress);
	(uint256 left, uint256 right, ) = pair.getReserves();
	(uint256 usdcReserves, uint256 ethReserves) = (USDC < WETH)
		? (left, right)
		: (right, left);
	uint8 ethDecimals = ERC20(WETH).decimals();
	//uint8 usdcDecimals = ERC20(USDC).decimals();
	//returns price in 6 decimals
	return
		IUniswapV2Router01(UNISWAP_ROUTER).getAmountOut(
			10**ethDecimals,
			ethReserves,
			usdcReserves
		);
}
```

Using flashloan to distort and manipulate the price is very damaging technique.

Consider the POC below.

1. the User uses 10000 amount of tokenA as collateral, each token A worth 1 USD according to the paraspace oracle. the user borrow 3 ETH, the price of ETH is 1200 USD.

2. the paraspace oracle went down, the fallback price oracle is used, the user use borrows flashloan to distort the price of the tokenA in Uniswap pool from 1 USD to 10000 USD.

3. the user's collateral position worth 1000 token X 10000 USD, and borrow 1000 ETH.

4. User repay the flashloan using the overborrowed amount and recover the price of the tokenA in Uniswap liqudity pool to 1 USD, leaving bad debt and insolvent position in Paraspace.

## Tools Used

Manual Review

## Recommended Mitigation Steps

We recommend the project does not use the spot price in Uniswap V2, if the paraspace is down, it is safe to just revert the transaction.

# Lines of code

https://github.com/code-423n4/2022-11-paraspace/blob/c6820a279c64a299a783955749fdc977de8f0449/paraspace-core/contracts/misc/NFTFloorOracle.sol#L234-L248


# Vulnerability details

## Impact
function `getPrice()` returns the most recent price on chain but code don't check that asset is whitelisted and price is not equal to zero so in those cases it returns wrong value or revert with wrong error.

## Proof of Concept
This is the `getPrice()` code in NFTFloorOracle:
```
    /// @param _asset The nft contract
    /// @return price The most recent price on chain
    function getPrice(address _asset)
        external
        view
        override
        returns (uint256 price)
    {
        uint256 updatedAt = assetPriceMap[_asset].updatedAt;
        require(
            (block.number - updatedAt) <= config.expirationPeriod,
            "NFTOracle: asset price expired"
        );
        return assetPriceMap[_asset].twap;
    }
```
As you can see there is no `onlyWhenAssetExisted(_asset)` modifier or there is no check that `assetPriceMap[_asset].twap` is not zero.

## Tools Used
VIM

## Recommended Mitigation Steps
add proper modifier and check for the value of `assetPriceMap[_asset].twap`

# Lines of code

https://github.com/code-423n4/2022-11-paraspace/blob/main/paraspace-core/contracts/misc/ParaSpaceOracle.sol#L115-L136


# Vulnerability details

## Impact
ParaSpaceOracle.getAssetPrice doesn't check if price is fresh. As result stale price can be used which can lead to protocol loses if price has changed.

## Proof of Concept
https://github.com/code-423n4/2022-11-paraspace/blob/main/paraspace-core/contracts/misc/ParaSpaceOracle.sol#L115-L136
```solidity
    function getAssetPrice(address asset)
        public
        view
        override
        returns (uint256)
    {
        if (asset == BASE_CURRENCY) {
            return BASE_CURRENCY_UNIT;
        }


        uint256 price = 0;
        IEACAggregatorProxy source = IEACAggregatorProxy(assetsSources[asset]);
        if (address(source) != address(0)) {
            price = uint256(source.latestAnswer());
        }
        if (price == 0 && address(_fallbackOracle) != address(0)) {
            price = _fallbackOracle.getAssetPrice(asset);
        }


        require(price != 0, Errors.ORACLE_PRICE_NOT_READY);
        return price;
    }
```

If IEACAggregatorProxy exists for asset then it's price is fetched using source.latestAnswer() function. After the price is fetched there is only check that price is not 0. But there is no check if the price is fresh.
It's possible that price will be not 0, but it will be stale. And this can lead to protocol loses if the real price has changed meanwhile the aggregator was not working.

## Tools Used
VsCode
## Recommended Mitigation Steps
IEACAggregatorProxy also has latestTimestamp() function. Result of this function should be checked with some stake period to detect if the price is fresh enough.

# Lines of code

https://github.com/code-423n4/2022-11-paraspace/blob/3e4e2e4e1322482dcdc6d342f8799cd44a3e42f5/paraspace-core/contracts/misc/NFTFloorOracle.sol#L236-L248
https://github.com/code-423n4/2022-11-paraspace/blob/3e4e2e4e1322482dcdc6d342f8799cd44a3e42f5/paraspace-core/contracts/misc/NFTFloorOracle.sol#L195-L216


# Vulnerability details

If an asset is whitelisted in the contract but any oracle has returned a floor price yet, then the call to `getPrice()` would return a price 0.

This opens a time window when an attacker could take advantage of the assets with price 0.

Calls to `getPrice()` should revert in case that the oracle has no price records yet to avoid any unexpected behaviour until at least one price is registered in the contract.


POC: Foundry test
```solidity
    // SPDX-License-Identifier: UNLICENSED
    pragma solidity 0.8.10;

    import "forge-std/Vm.sol";
    import "forge-std/Test.sol";
    import "forge-std/console.sol";

    import {NFTFloorOracle} from "../../../src/paraspace/misc/NFTFloorOracle.sol";

    contract NFTFloorOracleTest is Test {
        NFTFloorOracle private target;

        address[] private feeders;
        address[] private invalidFeeders;

        address[] private assets;
        address[] private invalidAssets;

        address private admin;

        address private attacker;

        function setUp() public {
            admin = makeAddr("admin");

            feeders.push(makeAddr("feeder1"));
            feeders.push(makeAddr("feeder2"));
            feeders.push(makeAddr("feeder3"));
            feeders.push(makeAddr("feeder4"));

            invalidFeeders.push(makeAddr("invalidFeeder1"));

            assets.push(makeAddr("asset1"));
            assets.push(makeAddr("asset2"));

            invalidAssets.push(makeAddr("invalidAsset1"));

            target = new NFTFloorOracle();
            target.initialize(admin, feeders, assets);
        }

        function test() public {
            address asset = assets[0];

            uint256 assetPrice = target.getPrice(asset);
            assertEq(assetPrice, 0, "Returned price is 0 for asset");
        }
    }
```

Solution: Add a validation in the `getPrice()` function

```solidity
    /// @param _asset The nft contract
    /// @return price The most recent price on chain
    function getPrice(address _asset) external view override returns (uint256 price) {
        uint256 updatedAt = assetPriceMap[_asset].updatedAt;
        require(updatedAt > 0, "NFTOracle: asset without price"); // ADD THIS LINE
        require((block.number - updatedAt) <= config.expirationPeriod, "NFTOracle: asset price expired");
        return assetPriceMap[_asset].twap;
    }
```

