uint256 diff = timestamp - lastTimestamp;
        lastTimestamp = block.timestamp;
        if (diff >= WINDOW_SIZE) {
            lastPrice = price;
            valid = true;
        } else {
            lastPrice = (lastPrice * (WINDOW_SIZE - diff)) / WINDOW_SIZE + (price * diff) / WINDOW_SIZE;
            valid = true;
        }

}

