+        // start auction1 for nft-10
+        auction1 = controller.startLiquidationAuction(address(attacker), IPaprController.Collateral({id: 10, addr: nft}), getTwapOracle());
+
+        // price dropped to 20u
+        oraclePrice = 20e6;
+        vm.warp(block.timestamp + controller.liquidationAuctionMinSpacing());
+        // auction1 price is still higher, nobody would like to purchage it
+        assertTrue(controller.auctionCurrentPrice(auction1) > oraclePrice);
+        // start auction2 for nft-11
