+    function getLowerOracle() internal returns (ReservoirOracleUnderwriter.OracleInfo memory) {
+        priceKind = ReservoirOracleUnderwriter.PriceKind.LOWER;
+        return _getOracleInfoForCollateral(nft, underlying);
+    }
+
+    function getTwapOracle() internal returns (ReservoirOracleUnderwriter.OracleInfo memory) {
+        priceKind = ReservoirOracleUnderwriter.PriceKind.TWAP;
+        return _getOracleInfoForCollateral(nft, underlying);
+    }
+}
