            address(oracle_),
            arbiter,
            borrower,
            ttl
        );
        assertEq(uint(line_.init()), uint(LineLib.STATUS.ACTIVE));

        uint256 amount = 10 ether;

        // lender agrees to lend up to 10 ether of the mock rebasing token to borrower
        vm.prank(borrower);
        line_.addCredit(dRate, fRate, amount, address(mockRebasingToken), lender);

        vm.prank(lender);
        bytes32 id = line_.addCredit(dRate, fRate, amount, address(mockRebasingToken), lender);

        // After the addCredit function is called by both borrower and lender and before borrower calls the borrow function,
        //   the mock rebasing token's rebasing event occurs, which decreases its total supply.
        mockRebasingToken.rebase(-10000000000);

        // Calling the borrow function by borrower reverts at this moment
        //   because the line of credit contract's balance of the mock rebasing token has become insufficient after such rebasing event has happened.
        vm.prank(borrower);
        vm.expectRevert(stdError.arithmeticError);
        line_.borrow(id, amount);
    }
```

## Tools Used
VSCode

## Recommended Mitigation Steps
A blocklist can be used to block the usage of rebasing tokens, which is similar to what have been done in some other protocols. If blocking rebasing tokens, the documentation needs to be updated so users are aware of this.

# Lines of code

https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/oracle/Oracle.sol#L22-L32


# Vulnerability details

## Impact

`latestRoundData()` is used when trying to get `currentPrice`, but there is no check if the return value indicates stale data and round completeness. There are no checks on roundID might result in stale prices. The oracle wrapper calls out to a chainlink oracle receiving the `latestRoundData()`. 

If there is a problem with chainlink starting a new round and finding consensus on the new value for the oracle (e.g. chainlink nodes abandon the oracle, chain congestion, vulnerability/attacks on the chainlink system) consumers of this contract may continue using outdated stale data (if oracles are unable to submit no new round is started).

This could lead to stale prices and can lead to wrong `currentPrice` return value.

Reference to the Chainlink documentation:
https://docs.chain.link/docs/data-feeds/feed-registry/feed-registry-functions/  
https://etherscan.io/address/0x47Fb2585D2C56Fe188D0E6ec628a38b74fCeeeDf#contracts

## Proof of Concept

```solidity
// Line-of-Credit/contracts/modules/oracle/Oracle.sol
    function getLatestAnswer(address token) external returns (int) {
        (
            /* uint80 roundID */, 
            int price,
            /* uint80 startedAt */,
            /* uint80 timeStamp */,
            /* uint80 answeredInRound */
        ) = registry.latestRoundData(token, Denominations.USD);

        return price;
    }
```

Stale prices could make the `currentPrice` inaccurate and affect the moving average price. According to Chainlink's documentation, this function does not error if no answer has been reached but returns 0, causing an incorrect price feed to the PriceOracle. The external Chainlink oracle, which provides index price information to the system, introduces risk inherent to any dependency on third-party data sources. For example, the oracle could fall behind or otherwise fail to be maintained, resulting in outdated data being fed to the index price calculations of the AMM. Oracle reliance has historically resulted in crippled on-chain systems, and complications that lead to these outcomes can arise from things as simple as network congestion.

Although there is a timestamp check, Round ID is not checked in the function. That can also cause stale price.


## Tools Used
Manual analysis.

## Recommended Mitigation Steps

Validate data feed on both Round ID and timestamp:

```solidity
    function getLatestAnswer(address token) external returns (int) {
        (
            uint80 roundID, 
            int price,
            /* uint80 startedAt */,
            uint256 timeStamp,
            uint80 answeredInRound
        ) = registry.latestRoundData(token, Denominations.USD);

        if (price == 0) revert();
        if (timeStamp < block.timestamp - stalePriceDelay ||
        answeredInRound < roundID)
            revert Price_BadFeed(address(_ohmEthPriceFeed));
        return price;
    }
```

# Lines of code

https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/oracle/Oracle.sol#L22-L29


# Vulnerability details

Chainlink's `latestRoundData()` is used but there is no check if the return value indicates stale data. This could lead to stale prices according to the Chainlink documentation: [https://docs.chain.link/docs/historical-price-data/#historical-rounds](https://docs.chain.link/docs/historical-price-data/#historical-rounds)

## Impact

The protocol uses Chainlink's `latestRoundData()` to source for the price of every underlying token (Credit, Revenue, Collateral). If the price reading is correct or there is a flash crash happening, liquidation cannot be quick enough if borrower reaches the liquidation threshold whereby collateral value is less than minimum collateral value. This will irreparably affect the lenders position because they might not be able to recoup their capital sum fast enough.

## Proof of Concept

    function getLatestAnswer(address token) external returns (int) {
        (
            /* uint80 roundID */, 
            int price,
            /* uint80 startedAt */,
            /* uint80 timeStamp */,
            /* uint80 answeredInRound */
        ) = registry.latestRoundData(token, Denominations.USD);

answeredinRound, roundId, timeStamp is not used which will affect the actual price of each underlying token. Should something like the FTX crash occur and the borrower has put FTT as collateral, then ChainLink will be too slow in reading the data and Arbiter cannot call liquidation immediately.

## Tools Used

Manual Review

## Recommended Mitigation Steps

require(answeredInRound >= roundId, "Price stale");
require(block.timestamp - timeStamp< PRICE_ORACLE_STALE_THRESHOLD, "Price round incomplete");`

# Lines of code

https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/credit/SpigotedLine.sol#L111


# Vulnerability details

## Impact
Function `SpigotedLine.claimAndRepay()` is callable by both borrower and lender. Callers will provide `zeroExTradeData` to help calling trade function in 0x. 

Since it's repay function, borrower has no incentive to act malicious but lender has. Lender can call with trade with no slippage protection, creating front-run opportunity, also lower the revenue from spigot.

## Proof of Concept
Lender can call `claimAndRepay()` with arbitrary trade data
```solidity
function claimAndRepay(address claimToken, bytes calldata zeroExTradeData)
    external
    whileBorrowing
    nonReentrant
    returns (uint256)
{
    bytes32 id = ids[0];
    Credit memory credit = _accrue(credits[id], id);

    if (msg.sender != borrower && msg.sender != credit.lender) {
        revert CallerAccessDenied();
    }

    uint256 newTokens = claimToken == credit.token ?
      spigot.claimEscrow(claimToken) :  // same asset. dont trade
      _claimAndTrade(                   // trade revenue token for debt obligation
          claimToken,
          credit.token,
          zeroExTradeData // @audit lender can call with no slippage protection
      );

    uint256 repaid = newTokens + unusedTokens[credit.token];
    uint256 debt = credit.interestAccrued + credit.principal;

    // cap payment to debt value
    if (repaid > debt) repaid = debt;
    // update unused amount based on usage
    if (repaid > newTokens) {
        // using bought + unused to repay line
        unusedTokens[credit.token] -= repaid - newTokens;
    } else {
        // high revenue and bought more than we need
        unusedTokens[credit.token] += newTokens - repaid;
    }

    credits[id] = _repay(credit, id, repaid);

    emit RevenuePayment(claimToken, repaid);

    return newTokens;
}
```

And there is no slippage protection for the trade
https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/utils/SpigotedLineLib.sol#L85
```solidity
uint256 claimed = ISpigot(spigot).claimEscrow(claimToken);

trade(
    claimed + unused,
    claimToken,
    swapTarget,
    zeroExTradeData
);

// underflow revert ensures we have more tokens than we started with
uint256 tokensBought = LineLib.getBalance(targetToken) - oldTargetTokens;

if(tokensBought == 0) { revert TradeFailed(); } // ensure tokens bought
```


## Tools Used
Manual Review

## Recommended Mitigation Steps
Adding an Oracle to calculate the slippage is overcomplicated but still a solution. Or consider only allowing lender to claim but not trade revenue from spigot.

# Lines of code

https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/credit/LineOfCredit.sol#L203
https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/credit/LineOfCredit.sol#L179


# Vulnerability details

## Impact
Function `LineOfCredit.accrueInterest()` loops through `ids` list and calculate accrue interest for each credit line. However, if number of credit lines is too large, this unbounded loop will make the whole function fail because of out of gas. 
Similarly in `_updateOutstandingDebt()` function

## Proof of Concept
Function `accrueInterest()` loops through the whole `ids` list
https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/credit/LineOfCredit.sol#L200-L210
```solidity
function accrueInterest() external override returns(bool) {
    uint256 len = ids.length;
    bytes32 id;
    for (uint256 i; i < len; ++i) { // @audit can be out of gas
      id = ids[i];
      Credit memory credit = credits[id];
      credits[id] = _accrue(credit, id);
    }

    return true;
}
```

There is no check when `ids` list is appended
```solidity
function _createCredit(
    address lender,
    address token,
    uint256 amount
)
    internal
    returns (bytes32 id)
{
    id = CreditLib.computeId(address(this), lender, token);
    // MUST not double add the credit line. otherwise we can not _close()
    if(credits[id].lender != address(0)) { revert PositionExists(); }

    credits[id] = CreditLib.create(id, amount, lender, token, address(oracle));

    ids.push(id); // add lender to end of repayment queue

    unchecked { ++count; }

    return id;
}
```

## Tools Used
Manual Review

## Recommended Mitigation Steps
Consider adding a check in `_createCredit()`. For example, maximum number of credit line is 1000. It will not create issue like spamming and blocking other lenders since each `createCredit(...)` is mutual consent.

# Lines of code

https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/utils/EscrowLib.sol#L192-L207


# Vulnerability details

## Impact

According to the currently liquidation mechanism, the line contract will call `liquidate()`, and the collateral will be transferred. Later relies on the liquidator to manually sell the collateral, and come back to repay the loan. However, when the collateral amount is subtracted, the account is worse in collateral ratio, and potentially be depleted on all the collaterals. The borrower could incur big loss due to small shortfall.


## Proof of Concept

The current `liquidate()` function only grab the collateral, but not reduce the debt.
```solidity
// Line-of-Credit/contracts/utils/EscrowLib.sol
    function liquidate(
        EscrowState storage self,
        uint256 amount,
        address token,
        address to
    ) external returns (bool) {
        require(amount > 0);
        if(msg.sender != self.line) { revert CallerAccessDenied(); }
        if(self.deposited[token].amount < amount) { revert InvalidCollateral(); }

        self.deposited[token].amount -= amount;

        LineLib.sendOutTokenOrETH(token, to, amount);

        return true;
    }
```

The `isLiquidatable` status is given by Collateral Ratio:
```solidity
// Line-of-Credit/contracts/utils/EscrowLib.sol
    function isLiquidatable(EscrowState storage self, address oracle, uint256 minimumCollateralRatio) external returns(bool) {
      return _getLatestCollateralRatio(self, oracle) < minimumCollateralRatio;
    }
```

If the collateral is removed, the Collateral Ratio can only be lower. Then further liquidation can happen until empty the collateral.


## Tools Used
Manual analysis.

## Recommended Mitigation Steps

In the short term, when a borrower is liquidated, set up some records like lock status, so that the liquidation won't proceed anymore in some certain status.
In the long term, handle repayment and transfer of collateral at the same time.

# Lines of code

https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/utils/EscrowLib.sol#L131-L138
https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/utils/CreditLib.sol#L138-L146


# Vulnerability details

## Impact

In `enableCollateral()` and `create()`, if the decimal of the asset is not available, the default value of 18 is assigned. However this optimistical approach could introduce risk. Since it is unknown how the asset contract is implemented. The real decimal could possibly not 18. As a result, when calculating the asset value, wrong decimal could be used:
- if over evaluating the collateral, the protocol could issue under-collateralized loan and loss fund. 
- if under evaluating the collateral, the borrow function won't work as expected.


## Proof of Concept



```solidity
// Line-of-Credit/contracts/utils/EscrowLib.sol
    function enableCollateral(EscrowState storage self, address oracle, address token) external returns (bool) {
        // ...
        (bool successDecimals, bytes memory decimalBytes) = deposit
            .asset
            .call(abi.encodeWithSignature("decimals()"));
        if (decimalBytes.length > 0 && successDecimals) {
            deposit.assetDecimals = abi.decode(decimalBytes, (uint8));
        } else {
            deposit.assetDecimals = 18;
        }
        // ...
    }

// Line-of-Credit/contracts/utils/CreditLib.sol
  function create()
      external 
      returns(ILineOfCredit.Credit memory credit)
  {
      // ...    
      uint8 decimals;
      if(token == Denominations.ETH) {
          decimals = 18;
      } else {
          (bool passed, bytes memory result) = token.call(
              abi.encodeWithSignature("decimals()")
          );
          decimals = !passed ? 18 : abi.decode(result, (uint8));
      }
      // ...
  }
```


## Tools Used
Manual analysis.

## Recommended Mitigation Steps

Just revert if not able to retrieve the decimal.

# Lines of code

https://github.com/debtdao/Line-of-Credit/blob/master/contracts/modules/oracle/Oracle.sol#L22-L32


# Vulnerability details

## Impact
If price is stale, the wrong value of assets can be used and worst case leading to unwanted liquidations.

## Proof of Concept
The oracle feed doesn't validate staleness and round completeness:

`oracle/Oracle.sol`:
```javascript
    function getLatestAnswer(address token) external returns (int) {
        (
            /* uint80 roundID */, 
            int price,
            /* uint80 startedAt */,
            /* uint80 timeStamp */, // small note that type for timeStamp is wrong
            /* uint80 answeredInRound */
        ) = registry.latestRoundData(token, Denominations.USD);

        return price;
    }
```

## Tools Used
vscode

## Recommended Mitigation Steps
Validate staleness:
```javascript
    function getLatestAnswer(address token) external returns (int) {
        (
            uint80 roundID ,
            int price,
            /* uint80 startedAt */,
            uint256 timeStamp,
            uint80 answeredInRound
        ) = registry.latestRoundData(token, Denominations.USD);

        require(answeredInRound >= roundID, "Stale price");
        require(timeStamp > 0, "Round not complete");

        return price;
    }
```

# Lines of code

https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/credit/LineOfCredit.sol#L254
https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/credit/LineOfCredit.sol#L270


# Vulnerability details

## Impact
`setRate()` and `increaseCredit()` have a `mutualConsentById` modifier to check the mutual consent between the lender and borrower.

Once the borrower signed the consent first, the lender can apply the consent after closing the current credit and opening the same credit.

Then there might be an unexpected loss or impact that the borrower doesn't want.

## Proof of Concept
This is the test to show the scenario.

```solidity
    function testApplyOldConsent() public {
        // React with other lenders
        address lender1 = address(200); // honest lender
        supportedToken1.mint(lender1, 1 ether);
        vm.startPrank(lender1);
        supportedToken1.approve(address(line), MAX_INT);
        vm.stopPrank();
        vm.prank(borrower);
        line.addCredit(dRate, fRate, 1 ether, address(supportedToken1), lender1);
        vm.stopPrank();
        vm.prank(lender1);
        line.addCredit(dRate, fRate, 1 ether, address(supportedToken1), lender1);
        vm.stopPrank();

        uint initialBalance = supportedToken1.balanceOf(address(borrower));
        emit log_named_decimal_uint("Initial Borrower Balance", initialBalance, 18);

        // Create a credit of 1 ether with the malicious lender
        vm.prank(borrower);
        line.addCredit(dRate, fRate, 1 ether, address(supportedToken1), lender);
        vm.stopPrank();
        vm.prank(lender);
        bytes32 creditId1 = line.addCredit(dRate, fRate, 1 ether, address(supportedToken1), lender);
        vm.stopPrank();

        emit log_named_uint("creditId1", uint(creditId1));
        emit log_named_uint("First dRate", uint(dRate));
        emit log_named_uint("First fRate", uint(fRate));

        // Borrow 1 ether from the malicious lender
        vm.prank(borrower);
        line.borrow(creditId1, 1 ether);
        vm.stopPrank();

        emit log_named_decimal_uint("First Borrowed amount", supportedToken1.balanceOf(address(borrower)) - initialBalance, 18);

        // Borrower has agreed to increase the dRate & fRate because the borrowed amount is not big, but the lender didn't call setRates() on his end after the borrower's consent
        vm.prank(borrower);
        line.setRates(creditId1, dRate * 10, fRate * 10);
        vm.stopPrank();

        // Borrower repaid and closed the credit
        vm.prank(borrower);
        line.depositAndClose();
        vm.stopPrank();

        // The malicious lender said the borrower to lend tokens without any interest rate
        vm.prank(borrower);
        line.addCredit(0, 0, 100 ether, address(supportedToken1), lender);
        vm.stopPrank();
        vm.prank(lender);
        bytes32 creditId2 = line.addCredit(0, 0, 100 ether, address(supportedToken1), lender);
        vm.stopPrank();

        (uint128 _dRate, uint128 _fRate, ) = line.interestRate().rates(creditId2);

        emit log_named_uint("creditId2", uint(creditId2));
        emit log_named_uint("Second dRate", uint(_dRate));
        emit log_named_uint("Second fRate", uint(_fRate));

        // Borrowed all amount as the interest rate is 0
        vm.prank(borrower);
        line.borrow(creditId1, 100 ether);
        vm.stopPrank();

        emit log_named_decimal_uint("Second Borrowed amount", supportedToken1.balanceOf(address(borrower)) - initialBalance, 18);

        // The lender increased the dRate & fRate using the past consent because creditId1 == creditId2
        vm.prank(lender);
        line.setRates(creditId2, dRate * 10, fRate * 10);
        vm.stopPrank();

        (_dRate, _fRate, ) = line.interestRate().rates(creditId2);
        emit log_named_uint("Final dRate", uint(_dRate));
        emit log_named_uint("Final fRate", uint(_fRate));
    }
```

This is the result of the test.

```solidity
Running 1 test for contracts/tests/LineOfCredit.t.sol:LineTest
[PASS] testApplyOldConsent() (gas: 722350)
Logs:
  Initial Borrower Balance: 100.000000000000000000
  creditId1: 46561515594145399622473420085312788390268491352863149030766718414074458967366
  First dRate: 100
  First fRate: 1
  First Borrowed amount: 1.000000000000000000
  creditId2: 46561515594145399622473420085312788390268491352863149030766718414074458967366
  Second dRate: 0
  Second fRate: 0
  Second Borrowed amount: 100.000000000000000000
  Final dRate: 1000
  Final fRate: 10
```

Currently, credit id is computed using [lender and token](https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/modules/credit/LineOfCredit.sol#L435-L454) so that the id of the new credit will be same as the old one if they use the same token.

```solidity
    function _createCredit(
        address lender,
        address token,
        uint256 amount
    )
        internal
        returns (bytes32 id)
    {
        id = CreditLib.computeId(address(this), lender, token);
        // MUST not double add the credit line. otherwise we can not _close()
        if(credits[id].lender != address(0)) { revert PositionExists(); }

        credits[id] = CreditLib.create(id, amount, lender, token, address(oracle));

        ids.push(id); // add lender to end of repayment queue

        unchecked { ++count; }

        return id;
    }
```

So after closing the old credit, a lender can propose a large amount of credit with low rates and increase the rate after the creation using the unused old consent.

As a result, there will be an unexpected loss with the high rates.

## Tools Used
Manual Review, Foundry

## Recommended Mitigation Steps
Currently, users can't cancel their consent once they signed using [_mutualConsent()](https://github.com/debtdao/Line-of-Credit/blob/e8aa08b44f6132a5ed901f8daa231700c5afeb3a/contracts/utils/MutualConsent.sol#L38-L60).

We should add a `cancelConsent()` to remove the consent if the original signer wants like below.

```solidity
    mapping(byte32 => address) consentsSigner; //++++++++++++++++

    // The original signer can cancel the consent anytime
    function cancelConsent(byte32 consentHash) { //++++++++++++++++
        if(consentsSigner[consentHash] == msg.sender) {
            delete mutualConsents[consentHash]; 
            delete consentsSigner[consentHash];
        }
    }

    function _mutualConsent(address _signerOne, address _signerTwo) internal returns(bool) {
        if(msg.sender != _signerOne && msg.sender != _signerTwo) { revert Unauthorized(); }

        address nonCaller = _getNonCaller(_signerOne, _signerTwo);

        // The consent hash is defined by the hash of the transaction call data and sender of msg,
        // which uniquely identifies the function, arguments, and sender.
        bytes32 expectedHash = keccak256(abi.encodePacked(msg.data, nonCaller));

        if (!mutualConsents[expectedHash]) {
            bytes32 newHash = keccak256(abi.encodePacked(msg.data, msg.sender));

            mutualConsents[newHash] = true;
            consentsSigner[newHash] = msg.sender; //++++++++++++++++++++++

            emit MutualConsentRegistered(newHash);

            return false;
        }

        delete mutualConsents[expectedHash]; 
        delete consentsSigner[expectedHash]; //+++++++++++++++++++++++++++

        return true;
    }
```

