             int price,
             /* uint80 startedAt */,
-            /* uint80 timeStamp */,
+            uint80 timeStamp,
             /* uint80 answeredInRound */
         ) = registry.latestRoundData(token, Denominations.USD);

+        require(block.timestamp <= timeStamp + PRICE_MAX_AGE, "Stale feed detected");
+
         return price;
     }
