        if(fixedPrices[token] > 0) return fixedPrices[token];
        if(feeds[token].feed != IChainlinkFeed(address(0))) {
            // get price from feed
            (uint80 roundId, int256 basePrice, , uint256 updatedAt, uint80 answeredInRound) = feeds[token].feed.latestRoundData(); //+++++++++++++++++++++++++++++++++++++
            require(answeredInRound >= roundId, "Price stale"); //++++++++++++++++++++++++++
            require(basePrice > 0, "Invalid feed price"); //+++++++++++++++++++++++++++

            uint price = uint256(basePrice);

