# Vulnerability details

## Impact
The current implementation doesn't limit the number of simultaneously running sales from the same ````edition````. This causes a earlier sale may be blocked by a later one, and all sold funds will be locked in the contract.

## Proof of Concept
The following test case shows one of these scenarios
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "forge-std/Test.sol";
import {EscherTest} from "./utils/EscherTest.sol";
import {FixedPriceFactory, FixedPrice} from "src/minters/FixedPriceFactory.sol";

contract FixedPriceBaseTest is EscherTest {
    FixedPrice.Sale public fixedSale;
    FixedPriceFactory public fixedSales;

    function setUp() public virtual override {
        super.setUp();
        fixedSales = new FixedPriceFactory();
        fixedSale = FixedPrice.Sale({
            currentId: uint48(0),
            finalId: uint48(10),
            edition: address(edition),
            price: uint96(uint256(1 ether)),
            saleReceiver: payable(address(69)),
            startTime: uint96(block.timestamp)
        });
    }
}


contract BlockedSaleTest is FixedPriceBaseTest {
    FixedPrice public implementation;

    mapping(uint256 => address) ownersOf;

    function setUp() public override {
        super.setUp();
        implementation = FixedPrice(fixedSales.implementation());
    }

    function test_BlockedSale() public {
        FixedPrice sale1 = FixedPrice(fixedSales.createFixedSale(fixedSale));
        edition.grantRole(edition.MINTER_ROLE(), address(sale1));

        // part of NFTs sold
        sale1.buy{value: 5 ether}(5);
        assertEq(address(sale1).balance, 5 ether);

        // the artist doesn't wait the previous sale finished, and open a new sale
        fixedSale.currentId += 5;
        fixedSale.finalId += 5;
        FixedPrice sale2 = FixedPrice(fixedSales.createFixedSale(fixedSale));
        edition.grantRole(edition.MINTER_ROLE(), address(sale2));

        // any of NFTs in new sale sold
        sale2.buy{value: 1 ether}(1);
        assertEq(address(sale2).balance, 1 ether);

        // the 1st sale now blocked and can be closed
        vm.expectRevert("ERC721: token already minted");
        sale1.buy{value: 1 ether}(1);
    }
}


```

Test case result
```
Running 1 test for test/BlockedSale.t.sol:BlockedSaleTest
[PASS] test_BlockedSale() (gas: 637162)
Test result: ok. 1 passed; 0 failed; finished in 3.01ms
```

## Tools Used
Foundry

## Recommended Mitigation Steps
Limit only one active sale for one ````edition```` contract.

