+++ b/src/minters/FixedPrice.sol
@@ -81,6 +81,13 @@ contract FixedPrice is Initializable, OwnableUpgradeable, ISale {
         emit Start(_sale);
     }

+    function setFinalId(uint48 finalId) external onlyOwner {
+        Sale memory cache = sale;
+        require(finalId > cache.currentId, "TOO SMALL");
+        require(finalId < cache.finalId, "TOO BIG");
+        sale.finalId = finalId;
+    }
+
     /// @notice cancel a fixed price sale
     /// @notice the price of the sale
     function getPrice() public view returns (uint256) {
