# Vulnerability details

## Impact
If an NFT creator creates a sale with an incorrect price 0, any buyer can purchase all the NFTs with 0 ether. And the worse, the sale cannot be cancelled as long as it has started.

## Proof of Concept

Put the following test case under the folder `test/` and run the test: `forge test`. A user can buy all `1000000` NFTs with `0 ether`:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "forge-std/Test.sol";
import {EscherTest} from "./utils/EscherTest.sol";
import {FixedPriceFactory, FixedPrice} from "src/minters/FixedPriceFactory.sol";

contract FixedPriceZeroBaseTest is EscherTest {
    FixedPrice.Sale public fixedSale;
    FixedPriceFactory public fixedSales;

    function setUp() public virtual override {
        super.setUp();
        fixedSales = new FixedPriceFactory();
        fixedSale = FixedPrice.Sale({
            currentId: uint48(0),
            finalId: uint48(1000000),
            edition: address(edition),
            price: uint96(uint256(0 ether)),
            saleReceiver: payable(address(69)),
            startTime: uint96(block.timestamp)
        });
    }
}

contract FixedPriceZeroTest is FixedPriceZeroBaseTest {
    FixedPrice public sale;

    function setUp() public override {
        super.setUp();
    }

    function test_PriceZero_Buy() public {
        // make the fixed price sale
        sale = FixedPrice(fixedSales.createFixedSale(fixedSale));
        // authorize the fixed price sale to mint tokens
        edition.grantRole(edition.MINTER_ROLE(), address(sale));
        // lets buy all NFTs with 0 ETH
        sale.buy{value: 0 ether}(1000000);
        assertEq(address(sale).balance, 0 ether);
        assertEq(edition.balanceOf(address(this)), 1000000);
    }
}
```


## Tools Used
Manual audit.

## Recommended Mitigation Steps
verifying the sale price before creating the sale. e.g. `require(sale.price != 0);`

