# Vulnerability details

## Summary
__Impact: High
Likelyhood: Low
Overall: Medium__
Rebasing tokens like AMPL (every 24 hours, the supply of the token is adjusted with the aim of keeping its price close to $1) use an algorithmic token minting and burning to mantain their value. The system creates and mint corresponding hERC20 token, which ration is 1:1, when the token is being minted, but rebasing tokens (the undelying asset) could change it's circulation tokens and break the 1:1 ration.
## Impact
Why this could result in larger impact? Because when a user deposit his tokens on branch A and mint corresponding h tokens a deposit struct for those values (lets say 100 AMPL and 100 hAMPL). The deposit is transfert and locked in the branch port. Some time passes and now the balance of the port for those 100 AMPL is reduced to 92, but the deposit amount in the struct is still 100. When a user want to withdraw their token he should call `redeemDeposit` passing the __depositNonce__, which points to the original deposit amount(100), but the current port balance is 92(after the rebasing). This could result in reverted transaction when a user want to withdraw their deposit. 
There could also be problem with smaller impact, if the balance of the rebasing token has been increased. (from 100 -> 115), which would result in value lost for the user.
## Proof of Concept 
To execute PoC test:
(ERC20 is forked from https://github.com/reBASEcapital/REBASE)
- import following MockedRebaseERC20 token inside `test/ulysses-omnichain/mocks/`
```solidity
pragma solidity 0.8.19;
import {IERC20} from "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import {SignedMath} from "openzeppelin-contracts/contracts/utils/math/SignedMath.sol";

contract MockRebaseERC20 is IERC20 {
    using SignedMath for int256;

    event LogRebase(uint256 indexed epoch, uint256 totalSupply);
    event LogRebasePaused(bool paused);
    event LogTokenPaused(bool paused);
    event LogMonetaryPolicyUpdated(address monetaryPolicy);

    address public monetaryPolicy;

    modifier onlyMonetaryPolicy() {
        require(msg.sender == monetaryPolicy);
        _;
    }

    error NotEnoughtFunds();
    bool public rebasePaused;
    bool public tokenPaused;

    modifier whenRebaseNotPaused() {
        require(!rebasePaused);
        _;
    }

    modifier whenTokenNotPaused() {
        require(!tokenPaused);
        _;
    }

    modifier validRecipient(address to) {
        require(to != address(0x0));
        require(to != address(this));
        _;
    }

    uint256 private constant DECIMALS = 9;
    uint256 private constant MAX_UINT256 = ~uint256(0);
    uint256 private constant INITIAL_FRAGMENTS_SUPPLY = 3.025 * 10**6 * 10**DECIMALS;
    uint256 private constant TOTAL_GONS = MAX_UINT256 - (MAX_UINT256 % INITIAL_FRAGMENTS_SUPPLY);

    uint256 private constant MAX_SUPPLY = ~uint128(0);  // (2^128) - 1

    uint256 private _totalSupply;
    uint256 private _gonsPerFragment;
    mapping(address => uint256) private _gonBalances;
    mapping(address => mapping(address => uint256)) allowances;

    mapping (address => mapping (address => uint256)) private _allowedFragments;

    string public name;
    string public symbol;
    uint8 public decimals;

    constructor(string memory _name, string memory _symbol, uint8 _decimals){
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
        _totalSupply = INITIAL_FRAGMENTS_SUPPLY;
        _gonBalances[msg.sender] = TOTAL_GONS;
        _gonsPerFragment = TOTAL_GONS / _totalSupply;
    }


    function setMonetaryPolicy(address monetaryPolicy_)
        external
    {
        monetaryPolicy = monetaryPolicy_;
        emit LogMonetaryPolicyUpdated(monetaryPolicy_);
    }

    function setRebasePaused(bool paused)
        external
    {
        rebasePaused = paused;
        emit LogRebasePaused(paused);
    }

    /**
     * @dev Pauses or unpauses execution of ERC-20 transactions.
     * @param paused Pauses ERC-20 transactions if this is true.
     */
    function setTokenPaused(bool paused)
        external
    {
        tokenPaused = paused;
        emit LogTokenPaused(paused);
    }
    function allowance(address owner, address spender) external view returns (uint256){
        return allowances[owner][spender];
    }

    function totalSupply() override public view returns (uint256) {
        return _totalSupply;
    }

    /**
     * @dev Notifies Fragments contract about a new rebase cycle.
     * @param supplyDelta The number of new fragment tokens to add into circulation via expansion.
     * @return The total number of fragments after the supply adjustment.
     */
    function rebase(uint256 epoch, int256 supplyDelta)
        external
        returns (uint256)
    {
        if (supplyDelta == 0) {
            emit LogRebase(epoch, _totalSupply);
            return _totalSupply;
        }

        if (supplyDelta < 0) {
            _totalSupply = _totalSupply - uint256(supplyDelta.abs());
        } else {
            _totalSupply = _totalSupply + uint256(supplyDelta);
        }

        if (_totalSupply > MAX_SUPPLY) {
            _totalSupply = MAX_SUPPLY;
        }

        _gonsPerFragment = TOTAL_GONS / _totalSupply;

        emit LogRebase(epoch, _totalSupply);
        return _totalSupply;
    }

    /**
     * @param who The address to query.
     * @return The balance of the specified address.
     */
    function balanceOf(address who) override
        public
        view
        returns (uint256)
    {
        return _gonBalances[who] / _gonsPerFragment;
    }

    function transfer(address to, uint256 value)
        public
        validRecipient(to)
        whenTokenNotPaused
        returns (bool)
    {
        if(value > balanceOf(msg.sender)){
            revert NotEnoughtFunds();
        }
        uint256 gonValue = value * _gonsPerFragment;
        _gonBalances[msg.sender] = _gonBalances[msg.sender] - gonValue;
        _gonBalances[to] = _gonBalances[to] + gonValue;
        emit Transfer(msg.sender, to, value);
        return true;
    }


    function transferFrom(address from, address to, uint256 value)
        public
        validRecipient(to)
        whenTokenNotPaused
        returns (bool)
    {
        _allowedFragments[from][msg.sender] = _allowedFragments[from][msg.sender] - value;

        uint256 gonValue = value * _gonsPerFragment;
        _gonBalances[from] = _gonBalances[from] - gonValue;
        _gonBalances[to] = _gonBalances[to]+ gonValue;
        emit Transfer(from, to, value);

        return true;
    }

    function approve(address spender, uint256 value)
        public
        whenTokenNotPaused
        returns (bool)
    {
        _allowedFragments[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }
}
```
