        vm.startPrank(address(bAgent));
        vm.expectRevert();
        //this was initially bAgent.requiresEndpointt(lzEndpointAddress, abi.encodePacked(bAgent, rootBridgeAgentAddress));
        bAgent.requiresEndpointt(lzEndpointAddress, abi.encodePacked(rootBridgeAgentAddress, bAgent));
    }
```


