+       amounts.push(_amount1);
+
+       deposits.push(_deposit0);
+       deposits.push(_deposit1);
+
+
+       //@audit-info => Prepare deposit info
+       DepositMultipleInput memory depositInput =
+           DepositMultipleInput({hTokens: hTokens, tokens: tokens, amounts: amounts, deposits: deposits});
+
+   
+       // Approve spend by router
+       MockERC20(hTokens[0]).approve(address(avaxMulticallRouter), amounts[0] - deposits[0]);
+       MockERC20(tokens[0]).approve(address(avaxMulticallRouter), deposits[0]);
+       MockERC20(hTokens[1]).approve(address(avaxMulticallRouter), amounts[1] - deposits[1]);
+       MockERC20(tokens[1]).approve(address(avaxMulticallRouter), deposits[1]);
+       
