# Denial of Service

https://github.com/code-423n4/2023-09-maia/blob/f5ba4de628836b2a29f9b5fff59499690008c463/src/MulticallRootRouter.sol#L401C3-L477C6

This code seems to be executing a withdrawal operation for a given token and amount within a loop. A DoS attack can occur when an attacker provides inputs that cause the loop to run indefinitely or for an excessive number of iterations, consuming excessive gas and potentially making the contract unusable.

To mitigate this risk, you can implement gas limits and ensure that the loop does not run for an unbounded number of iterations. Here's a modified version of the code with gas limits and error handling:


    function executeSignedDepositMultiple(    

    bytes calldata encodedData,
    DepositMultipleParams calldata,
    address userAccount,
    uint16

    ) external payable override requiresExecutor lock {

    bytes1 funcId = encodedData[0];

    if (funcId == 0x01) {
        Call[] memory calls = abi.decode(_decode(encodedData[1:]), (Call[]));
        IVirtualAccount(userAccount).call(calls);
    } else if (funcId == 0x02) {
        (
            Call[] memory calls,
            OutputParams memory outputParams,
            uint16 dstChainId,
            GasParams memory gasParams
        ) = abi.decode(_decode(encodedData[1:]), (Call[], OutputParams, uint16, GasParams));

        IVirtualAccount(userAccount).call(calls);

        IVirtualAccount(userAccount).withdrawERC20(outputParams.outputToken, outputParams.amountOut);

        _approveAndCallOut(
            IVirtualAccount(userAccount).userAddress(),
            outputParams.recipient,
            outputParams.outputToken,
            outputParams.amountOut,
            outputParams.depositOut,
            dstChainId,
            gasParams
        );
    } else if (funcId == 0x03) {
        (
            Call[] memory calls,
            OutputMultipleParams memory outputParams,
            uint16 dstChainId,
            GasParams memory gasParams
        ) = abi.decode(_decode(encodedData[1:]), (Call[], OutputMultipleParams, uint16, GasParams));

        IVirtualAccount(userAccount).call(calls);

        uint256 numTokens = outputParams.outputTokens.length;

        for (uint256 i = 0; i < numTokens; i++) {
            // Ensure the loop does not run for an excessive number of iterations
            require(i < gasParams.maxTokensToWithdraw, "Exceeded maxTokensToWithdraw limit");
            IVirtualAccount(userAccount).withdrawERC20(outputParams.outputTokens[i], outputParams.amountsOut[i]);
        }

        _approveMultipleAndCallOut(
            IVirtualAccount(userAccount).userAddress(),
            outputParams.recipient,
            outputParams.outputTokens,
            outputParams.amountsOut,
            outputParams.depositsOut,
            dstChainId,
            gasParams
        );
    } else {
        revert UnrecognizedFunctionId();
    }}

In this modified code:
1.We have added a maxTokensToWithdraw limit from the gasParams struct, which prevents the loop from running for an excessive number of iterations. You should set an appropriate value for this limit based on your contract's requirements.
2.We check if the loop index i is within the maxTokensToWithdraw limit, and if it exceeds this limit, the function will revert with an error message.
By adding these checks and limits, you can reduce the risk of a DoS attack due to excessive gas consumption in the loop. Ensure that you choose an appropriate value for maxTokensToWithdraw to balance security and functionality according to your contract's needs.




