// Import the OpenZeppelin ERC20 library
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

// This function is called by the Uniswap V3 pool after a mint operation
// It transfers the required amounts of token0 and token1 from the caller to the pool
// It also validates the caller and the pool features using the CallbackLib
function uniswapV3MintCallback(
    uint256 amount0Owed,
    uint256 amount1Owed,
    bytes calldata data
) external {
