pragma solidity ^0.8.0;

import {Test, console} from "forge-std/Test.sol";
import {ERC1155} from "@tokens/ERC1155Minimal.sol";
import {ERC1155TokenReceiver} from "solmate/tokens/ERC1155.sol";
import "contracts/multicall/Multicall.sol";

contract MulticallMockToken is ERC1155, Multicall {
    function mint(uint256 id, uint256 amount) public {
        _mint(msg.sender, id, amount);
    }

    function mint(address account, uint256 id, uint256 amount) public {
        _mint(account, id, amount);
    }

    function afterTokenTransfer(address from, address to, uint256[] memory ids, uint256[] memory amounts)
        internal
        virtual
        override
    {}

    function afterTokenTransfer(address from, address to, uint256 id, uint256 amount) internal virtual override {}
}

contract Attacker is ERC1155TokenReceiver {
    function onERC1155Received(address, address, uint256 id, uint256 amt, bytes memory)
        public
        virtual
        override
        returns (bytes4)
    {
        revert("malicious revert");
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(address, address, uint256[] memory, uint256[] memory, bytes memory)
        public
        virtual
        override
        returns (bytes4)
    {
        return this.onERC1155BatchReceived.selector;
    }
}

contract t0x1cMulticall is Test, ERC1155TokenReceiver {
    MulticallMockToken token;
    address[] recipients;
    uint256 amount;

    Attacker attacker;

    function setUp() public {
        token = new MulticallMockToken();
        recipients = new address[](3);
        attacker = new Attacker();

        recipients[0] = address(0xa11ce);
        recipients[1] = address(attacker);
        recipients[2] = address(0xb0b);

        amount = 100;
        token.mint(1, amount);
        token.mint(2, amount);
        token.mint(3, amount);
    }

    function test_t0x1c_multicall() public {
        bytes[] memory calls = new bytes[](recipients.length);
        for (uint256 i = 0; i < recipients.length; i++) {
            calls[i] = abi.encodeWithSignature(
                "safeTransferFrom(address,address,uint256,uint256,bytes)",
                address(this),
                recipients[i],
                i + 1,
                amount,
                ""
            );
        }

        token.multicall(calls);
    }

    function onERC1155Received(address, address, uint256, uint256, bytes memory)
        public
        virtual
        override
        returns (bytes4)
    {
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(address, address, uint256[] memory, uint256[] memory, bytes memory)
        public
        virtual
        override
        returns (bytes4)
    {
        return this.onERC1155BatchReceived.selector;
    }
}
