          await stETHVault.connect(accounts[3]).withdraw(accounts[3].address, await stETHVault.depositedAsset(accounts[3].address))
        } catch(err){
          console.log("user3 was not able to withdraw due to a lack of funds")
          //uncommnet this console.log to see stack trace
          //console.log(err)
        }
}

// We recommend this pattern to be able to use async/await everywhere
// and properly handle errors.
main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

