# Vulnerability details

## Impact
- `LybraEUSDVaultBase.liquidation` does not take into account overall collateral ratio

## Proof of Concept
The comment above function `LybraEUSDVaultBase.liquidation` states that ` When overallCollateralRatio is above 150%, Keeper liquidates borrowers whose collateral ratio is below badCollateralRatio, using EUSD provided by Liquidation Provider.` but this overall collateral ratio condition is never checked. This allows the user to call `liquidation` even when overall collateral ratio < 150%.

Below is POC for the above example, I use foundry to run tests, create
a folder named test and save this to a file named Test.t.sol, then run it using command:
`forge test --match-path test/Test.t.sol -vvvv`

To simulate a situation when overall collateral ratio drops below 150%, I create contract `CustomLybraStETHDepositVault` which is a copy of `LybraStETHDepositVault`, except for function `getAssetPrice`:
```solidity
    function getAssetPrice() public override returns (uint256) {
        if (block.timestamp < 1690678800){
            return _etherPrice();
        } else {
            return _etherPrice() / 2;
        }

    }
```
In this function, when the time is < `1690678800` (this is timestamp of 30/7/2023), return the normal price, and if it passes that time, return only half the price (The test also uses `mockChainlink` as oracle, this contract always return price = `1600 * 1e18`). So after 30/7/2023, the price is `800 * 1e18` and it will decrease the collateral ratio.

```solidity
pragma solidity ^0.8.17;

import {Test, console2} from "forge-std/Test.sol";
import {Iconfigurator} from "contracts/lybra/interfaces/Iconfigurator.sol";
import {Configurator} from "contracts/lybra/configuration/LybraConfigurator.sol";
import {GovernanceTimelock} from "contracts/lybra/governance/GovernanceTimeLock.sol";
import {mockCurve} from "contracts/mocks/mockCurve.sol";
import {EUSD} from "contracts/lybra/token/EUSD.sol";
import {stETHMock} from "contracts/mocks/stETHMock.sol";
import {mockChainlink} from "contracts/mocks/chainLinkMock.sol";
import {LybraStETHDepositVault} from "contracts/lybra/pools/LybraStETHVault.sol";
import {esLBRBoost} from "contracts/lybra/miner/esLBRBoost.sol";
import {mockLBRPriceOracle} from "contracts/mocks/mockLBRPriceOracle.sol";
import {EUSDMiningIncentives} from "contracts/lybra/miner/EUSDMiningIncentives.sol";
import {LybraEUSDVaultBase} from "contracts/lybra/pools/base/LybraEUSDVaultBase.sol";


interface Ilido {
    function submit(address _referral) external payable returns (uint256 StETH);
}

// contract CustomLybraStETHDepositVault is the exact copy of LybraStETHDepositVault
// except for function getAssetPrice
contract CustomLybraStETHDepositVault is LybraEUSDVaultBase {
    // Currently, the official rebase time for Lido is between 12PM to 13PM UTC.
    uint256 public lidoRebaseTime = 12 hours;

    // stETH = 0xae7ab96520DE3A18E5e111B5EaAb095312D7fE84
    // oracle = 0x4c517D4e2C851CA76d7eC94B805269Df0f2201De
    constructor(address _config, address _stETH, address _oracle) LybraEUSDVaultBase(_stETH, _oracle, _config) {
    }

    /**
     * @notice Sets the rebase time for Lido based on the actual situation.
     * This function can only be called by an address with the ADMIN role.
     */
    function setLidoRebaseTime(uint256 _time) external {
        require(configurator.hasRole(keccak256("ADMIN"), msg.sender), "not authorized");
        lidoRebaseTime = _time;
    }

    /**
     * @notice Allows users to deposit ETH to mint eUSD.
     * ETH is directly deposited into Lido and converted to stETH.
     * @param mintAmount The amount of eUSD to mint.
     * Requirements:
     * The deposited amount of ETH must be greater than or equal to 1 ETH.
     */
    function depositEtherToMint(uint256 mintAmount) external payable override {
        require(msg.value >= 1 ether, "DNL");
        //convert to steth
        uint256 sharesAmount = Ilido(address(collateralAsset)).submit{value: msg.value}(address(configurator));
        require(sharesAmount > 0, "ZERO_DEPOSIT");

        totalDepositedAsset += msg.value;
        depositedAsset[msg.sender] += msg.value;
        depositedTime[msg.sender] = block.timestamp;

        if (mintAmount > 0) {
            _mintEUSD(msg.sender, msg.sender, mintAmount, getAssetPrice());
        }

        emit DepositEther(msg.sender, address(collateralAsset), msg.value, msg.value, block.timestamp);
    }

    /**
     * @notice When stETH balance increases through LSD or other reasons, the excess income is sold for EUSD, allocated to EUSD holders through rebase mechanism.
     * Emits a `LSDValueCaptured` event.
     *
     * *Requirements:
     * - stETH balance in the contract cannot be less than totalDepositedAsset after exchange.
     * @dev Income is used to cover accumulated Service Fee first.
     */
    function excessIncomeDistribution(uint256 stETHAmount) external override {
        uint256 excessAmount = collateralAsset.balanceOf(address(this)) - totalDepositedAsset;
        require(excessAmount > 0 && stETHAmount > 0, "Only LSD excess income can be exchanged");
        uint256 realAmount = stETHAmount > excessAmount ? excessAmount : stETHAmount;
        uint256 payAmount = (((realAmount * getAssetPrice()) / 1e18) * getDutchAuctionDiscountPrice()) / 10000;

        uint256 income = feeStored + _newFee();
        if (payAmount > income) {
            bool success = EUSD.transferFrom(msg.sender, address(configurator), income);
            require(success, "TF");

            try configurator.distributeRewards() {} catch {}

            uint256 sharesAmount = EUSD.getSharesByMintedEUSD(payAmount - income);
            if (sharesAmount == 0) {
                //EUSD totalSupply is 0: assume that shares correspond to EUSD 1-to-1
                sharesAmount = (payAmount - income);
            }
            //Income is distributed to LBR staker.
            EUSD.burnShares(msg.sender, sharesAmount);
            feeStored = 0;
            emit FeeDistribution(address(configurator), income, block.timestamp);
        } else {
            bool success = EUSD.transferFrom(msg.sender, address(configurator), payAmount);
            require(success, "TF");
            try configurator.distributeRewards() {} catch {}
            feeStored = income - payAmount;
            emit FeeDistribution(address(configurator), payAmount, block.timestamp);
        }

        lastReportTime = block.timestamp;
        collateralAsset.transfer(msg.sender, realAmount);
        emit LSDValueCaptured(realAmount, payAmount, getDutchAuctionDiscountPrice(), block.timestamp);
    }

    /**
     * @notice Reduces the discount for the issuance of additional tokens based on the rebase time using the Dutch auction method.
     * The specific rule is that the discount rate increases by 1% every 30 minutes after the rebase occurs.
     */
    function getDutchAuctionDiscountPrice() public view returns (uint256) {
        uint256 time = (block.timestamp - lidoRebaseTime) % 1 days;
        if (time < 30 minutes) return 10000;
        return 10000 - (time / 30 minutes - 1) * 100;
    }

    function getAssetPrice() public override returns (uint256) {
        if (block.timestamp < 1690678800){
            return _etherPrice();
        } else {
            return _etherPrice() / 2;
        }

    }
}

contract TestLybraEUSDVaultBase is Test {

    address admin = address(0x1111);
    address user1 = address(0x1);
    address user2 = address(0x2);
    address pool = address(0x3);

    stETHMock stETH;
    mockChainlink  oracle;
    Configurator configurator;
    GovernanceTimelock governanceTimeLock;
    mockCurve curve;
    EUSD eUSD;
    CustomLybraStETHDepositVault stETHVault;
    esLBRBoost boost;
    mockLBRPriceOracle lbrOracle;
    EUSDMiningIncentives eUSDMiningIncentives;


    function setUp() public {
        // deploy curve
        curve = new mockCurve();
        // deploy governance time lock
        address[] memory proposers = new address[](1);
        proposers[0] = admin;

        address[] memory executors = new address[](1);
        executors[0] = admin;

        governanceTimeLock = new GovernanceTimelock(1, proposers, executors, admin);
        configurator = new Configurator(address(governanceTimeLock), address(curve));

        // Deploy mock stETH
        stETH = new stETHMock();

        // deploy mock chainlink
        oracle = new mockChainlink();




        // Deploy eUSD and set in configurator
        eUSD = new EUSD(address(configurator));
        configurator.initToken(address(eUSD), address(0));


        // Deploy boost and mining incentive
        boost = new esLBRBoost();
        lbrOracle = new mockLBRPriceOracle();
        eUSDMiningIncentives = new EUSDMiningIncentives(address(configurator), address(boost), address(oracle), address(lbrOracle));
        configurator.setEUSDMiningIncentives(address(eUSDMiningIncentives));

        // Deploy vault
        stETHVault = new CustomLybraStETHDepositVault(address(configurator), address(stETH), address(oracle));
        configurator.setMintVaultMaxSupply(address(stETHVault), 100_000 * 1e18);
        configurator.setMintVault(address(stETHVault), true);

    }

    function testSetup() public {
        assertEq(stETHVault.badCollateralRatio(), 150 * 1e18);
    }

    function testOverallCollateralRatioNotCheckLiquidation() public {
        assertEq(stETHVault.poolTotalEUSDCirculation(), 0);
        assertEq(stETHVault.totalDepositedAsset(),0);
        // price = 1600 * 1e18
        stETH.approve(address(stETHVault), 2 * 1e18);
        stETHVault.depositAssetToMint(1e18, 1000 * 1e18);

        uint256 assetPrice = stETHVault.getAssetPrice();
        uint256 overallRatio = (stETHVault.totalDepositedAsset() * assetPrice * 100) / stETHVault.poolTotalEUSDCirculation();

        // At this point, overall ratio > 150 * 1e18 (150%)
        assertGt(overallRatio, 150 * 1e18);

        vm.warp(1690678800);
        assetPrice = stETHVault.getAssetPrice();

        overallRatio = (stETHVault.totalDepositedAsset() * assetPrice * 100) / stETHVault.poolTotalEUSDCirculation();
        // At this point, overall ratio < 150 * 1e18 (150%)
        assertLt(overallRatio, 150 * 1e18);

        // Try to call liquidation when overall ratio is < 150%
        address provider = address(this);
        address onBehalfOf = address(this);
        uint256 assetAmount = 3 * 1e17;
        uint256 eusdAmount = (assetAmount * assetPrice) / 1e18;

        eUSD.approve(address(stETHVault), eusdAmount);
        stETHVault.liquidation(provider, onBehalfOf, assetAmount);
    }
}

