contract LRTDepositPoolDepositAsset is LRTDepositPoolTest {
    address public rETHAddress;
    MockPriceOracle public priceOracle;

    function setUp() public override {
        super.setUp();

        // initialize LRTDepositPool
        lrtDepositPool.initialize(address(lrtConfig));
        rETHAddress = address(rETH);


        // add manager role within LRTConfig
        vm.startPrank(admin);
        lrtConfig.grantRole(LRTConstants.MANAGER, manager);
        lrtConfig.setContract(LRTConstants.LRT_DEPOSIT_POOL, address(lrtDepositPool));
        vm.stopPrank();


        lrtOracle.initialize(address(lrtConfig));
        priceOracle = new MockPriceOracle();


        vm.startPrank(manager);
        lrtOracle.updatePriceOracleFor(address(rETH), address(priceOracle));
        lrtOracle.updatePriceOracleFor(address(stETH), address(priceOracle));
        lrtOracle.updatePriceOracleFor(address(cbETH), address(priceOracle));
        vm.stopPrank();


        address nodeDelegatorContract = address(new MockNodeDelegator());

        address[] memory nodeDelegatorQueue = new address[](1);
        nodeDelegatorQueue[0] = nodeDelegatorContract;


        vm.prank(admin);
        lrtDepositPool.addNodeDelegatorContractToQueue(nodeDelegatorQueue);

    }


    function test_wrongPrice() external {

        vm.prank(alice);
        rETH.approve(address(lrtDepositPool), 100 ether);
        vm.prank(bob);
        rETH.approve(address(lrtDepositPool), 100 ether);


        vm.prank(alice);
        lrtDepositPool.depositAsset(rETHAddress, 1 ether); //The 1st deposit ignores getRSETHpice computations, as it simply returns 1ETH when totalsupply == 0                       
        uint256 firstDepositTimestamp = block.timestamp;

        vm.prank(bob);
        lrtDepositPool.depositAsset(rETHAddress, 1 ether);
        uint256 secondDepositTimestamp = block.timestamp;

        console.log('rseth received after depositing 1 rETH:');
        console.log(rseth.balanceOf(bob));

        //Even tough alice and bob both deposit at the same time, 
        //Alice receives the right amount of rseth, as the first deposit ignores getRSETHpice computations
        //Bob receives only half of what they deserved, as their asset are deposited before computing the price
        //Meaning that there will be 2 eth worth of asset, and only 1 eth of rseth to balance them, when computing the price
        assertEq(rseth.balanceOf(bob), rseth.balanceOf(alice)/2);
        assertEq(firstDepositTimestamp, secondDepositTimestamp);

