---

```solidity
// Interfaces 
interface LRTDepositPool {
  function getRsETHAmountToMint(address asset, uint amount) external view returns (uint);
  function _mintRsETH(address asset, uint amount) external;
}

interface RSETH {
  function mint(address to, uint amount) external; 
}

// Test contract
contract Test {

  LRTDepositPool pool;
  RSETH rseth;

  // Mock for getRsETHAmountToMint
  function getRSETHAmount(uint totalDeposits, uint depositAmt) external pure returns (uint) {
    return (depositAmt * 1e18) / totalDeposits; 
  }

  function test() public {

    // Set up with 100 total deposits
    uint totalDeposits = 100e18;

    // User deposits 1 ETH 
    uint depositAmt = 1e18;

    // Calculate RSETH amount
    uint rsethAmt = getRSETHAmount(totalDeposits, depositAmt); // 0.01

    // Total deposits increased to 110
    totalDeposits = 110e18;

    // Mint RSETH 
    pool._mintRsETH(address(0), depositAmt);
    rseth.mint(address(0), rsethAmt); 

    // rsethAmt was 0.01 instead of 0.00909 due to stale rate

