## Recommended Mitigation Steps

To mitigate this make use of the defined maxLoopLimit and check if the array length is more then that if so revert.

```js
function updateScores(address[] memory users) external {
        if (pendingScoreUpdates == 0) revert NoScoreUpdatesRequired();
        if (nextScoreUpdateRoundId == 0) revert NoScoreUpdatesRequired();
        //@audit check for max Loop Limit
       + if(users.length > maxLoopLimit) revert MaxLoopLimit();
        for (uint256 i = 0; i < users.length;) {
            address user = users[i];

            if (!tokens[user].exists) revert UserHasNoPrimeToken();
            if (isScoreUpdated[nextScoreUpdateRoundId][user]) continue;

            address[] storage _allMarkets = allMarkets;
	        + if(_markets.length > maxLoopLimit) revert MaxLoopLimit();

            for (uint256 j = 0; j < _allMarkets.length;) {
                address market = _allMarkets[j];
                _executeBoost(user, market);
                _updateScore(user, market);

                unchecked {
                    j++;
                }
            }

            pendingScoreUpdates--;
            isScoreUpdated[nextScoreUpdateRoundId][user] = true;

            unchecked {
                i++;
            }

            emit UserScoreUpdated(user);
        }
