59:         uint256 quoteAmount
60:     ) internal view returns (uint256, uint256) {
61:         uint256 castedRatio;
62:         // An invariant should be that `circuitChainlink.length > 0` otherwise `castedRatio = 0`
63:         for (uint256 i = 0; i < circuitChainlink.length; i++) {
64:             (quoteAmount, castedRatio) = _readChainlinkFeed( // @audit if any feed reverts, the whole tx reverts
65:                 quoteAmount,
66:                 circuitChainlink[i],
67:                 circuitChainIsMultiplied[i],
68:                 chainlinkDecimals[i],
69:                 0
70:             );
71:         }
72:         return (quoteAmount, castedRatio);
73:     }
```
[`ModuleChainlinkMulti#_quoteChainlink`](https://github.com/Tapioca-DAO/tapioca-periph-audit/blob/023751a4e987cf7c203ab25d3abba58f7344f213/contracts/oracle/modules/ModuleChainlinkMulti.sol#L58-L73)

