```
    function addBigBang(
        address mc,
        address _contract
    ) external onlyOwner registeredBigBangMasterContract(mc) {
        isMarketRegistered[_contract] = true;
        clonesOf[mc].push(_contract);
+       masterContractOf[_contract] = mc;    
        emit RegisterBigBang(_contract, mc);
    }
```


