function test_rUSDY_can_burn_amount_less_than_BPS_DENOMINATOR() public dealAndWrapAlice {
    _setOraclePrice(1.05e18);
    vm.prank(alice);
    rUSDYToken.transfer(bob, 1);

    assertEq(rUSDYToken.sharesOf(bob), 9_523);
    assertEq(usdy.balanceOf(guardian), 0);
    vm.prank(guardian);
    rUSDYToken.burn(bob, 1);
