   }

+  function test_unwrap_loss() public dealAlice {
+    _setOraclePrice(1e18);
+    vm.startPrank(alice);
+    usdy.approve(address(rUSDYToken), 100e18);
+    rUSDYToken.wrap(5);
+    assertEq(rUSDYToken.sharesOf(alice), 50_000);
+    vm.stopPrank();
+
+    _setOraclePrice(2e18);
+    vm.startPrank(alice);
+    uint256 USDY_bal_before = usdy.balanceOf(alice);
+    rUSDYToken.unwrap(3);
+    uint256 USDY_bal_get = usdy.balanceOf(alice) - USDY_bal_before;
+    assertEq(rUSDYToken.sharesOf(alice), 35_000);
+    assertEq(USDY_bal_get, 1);
+    vm.stopPrank();
