use(solidity)
const utils = ethers.utils

describe('AuditBytesUtils', () => {
    let AuditBytesUtils

    before(async () => {
        const AuditBytesUtilsFactory = await ethers.getContractFactory('AuditBytesUtils')
        AuditBytesUtils = await AuditBytesUtilsFactory.deploy()
    })

    it('substring - Bug - accepts out of bound offset', async () => {
        const self = toUtf8Bytes('0123456789')
        expect(self.length).to.eq(10)

        const offset = self.length      // out of bound offset
        const result = await AuditBytesUtils.substring(self, offset, 0)
        expect(utils.toUtf8String(result)).to.eq('')
    })
})
```

