    ICurvePool curvePool = ICurvePool(0xa1F8A6807c402E4A15ef4EBa36528A3FED24E577);


    function setUp() public {
        vm.createSelectFork(
            "https://eth.llamarpc.com",
            15889435
        );
    }

    function testPrice() public {
        console.log(curvePool.price_oracle());
    }

