        (uint256 newTotalETHBalance, uint256 newTotalETHXSupply, uint256 reportingBlockNumber) = getPORFeedData();
        updateWithInLimitER(newTotalETHBalance, newTotalETHXSupply, reportingBlockNumber);
    }

    function getPORFeedData()
