            keccak256(
                abi.encodePacked(
                    chain,
                    to_chain,
                    msg.sender,
                    address(this), 
                    to_handler,
                    nonce_manager[msg.sender]
                )
            )
        );

        {
            // Save the cross chain tx
                // struct CreatedCrossChainTx {
                //     uint256 txid;
                //     string from_chain;
                //     string to_chain;
                //     address from;
                //     uint256 to;
                //     address from_token;
