        bool isValid;
        try AggregatorV3Interface(BAL_CHAINLINK_FEED).latestRoundData() returns ( 
            uint80 /*roundId*/,
            int256 answer, /**@audit Returned BAL/USD price
            uint256 /*startedAt*/,
            uint256 /*updatedAt*/,
            uint80 /*answeredInRound*/
        ) {
            price = wdiv(uint256(answer), BAL_CHAINLINK_DECIMALS); //@audit Calculated Price
            isValid = (price > 0); //@audit bool check
        } catch {}

        if (!isValid) revert AuraVault__chainlinkSpot_invalidPrice();
