# Vulnerability details

## Impact
The `increaseLever` function in the `PositionAction4626` contract can cause a complete Denial of Service (DoS) when a user attempts to increase leverage. This issue prevents any further leverage adjustments due to a flawed implementation of the `_onIncreaseLever` hook, leading to transaction reverts.

## Proof of Concept

The `PositionAction` contracts are designed to be invoked via `delegatecall` to ensure that operations occur in the user's context. Both `PositionAction20`, `PositionAction4626`, and `PositionActionPendle` inherit from the base `PositionAction` contract, overriding specific hooks to provide flexibility in their operations.

The increaseLever function, common across these contracts, is used to increase a position's leverage. Here is its implementation:

```solidity
    function increaseLever(
        LeverParams calldata leverParams,
        address upFrontToken,
        uint256 upFrontAmount,
        address collateralizer,
        PermitParams calldata permitParams
    ) external onlyDelegatecall {
        // validate the primary swap
        if (
            leverParams.primarySwap.swapType != SwapType.EXACT_IN ||
            leverParams.primarySwap.assetIn != address(underlyingToken) ||
            leverParams.primarySwap.recipient != self
        ) revert PositionAction__increaseLever_invalidPrimarySwap();

        // validate aux swap if it exists
        if (
            leverParams.auxSwap.assetIn != address(0) &&
            (leverParams.auxSwap.swapType != SwapType.EXACT_IN ||
                leverParams.auxSwap.assetIn != upFrontToken ||
                leverParams.auxSwap.recipient != self)
        ) revert PositionAction__increaseLever_invalidAuxSwap();

        // transfer any up front amount to the LeverAction contract
        if (upFrontAmount > 0) {
            if (collateralizer == address(this)) {
                IERC20(upFrontToken).safeTransfer(self, upFrontAmount); // if tokens are on the proxy then just transfer
            } else {
                _transferFrom(upFrontToken, collateralizer, self, upFrontAmount, permitParams);
            }
        }

        // take out flash loan
        IPermission(leverParams.vault).modifyPermission(leverParams.position, self, true);
        flashlender.flashLoan(
            IERC3156FlashBorrower(self),
            address(underlyingToken),
            leverParams.primarySwap.amount,
            abi.encode(leverParams, upFrontToken, upFrontAmount)
        );
        IPermission(leverParams.vault).modifyPermission(leverParams.position, self, false);
    }

```

This function initiates a flash loan and processes the necessary swaps and collateral transfers. The callback function onFlashLoan then handles the completion of these operations:

```solidity
    function onFlashLoan(
        address /*initiator*/,
        address /*token*/,
        uint256 amount,
        uint256 fee,
        bytes calldata data
    ) external returns (bytes32) {
        if (msg.sender != address(flashlender)) revert PositionAction__onFlashLoan__invalidSender();

        (LeverParams memory leverParams, address upFrontToken, uint256 upFrontAmount) = abi.decode(
            data,
            (LeverParams, address, uint256)
        );

        // perform a pre swap from arbitrary token to collateral token if necessary
        if (leverParams.auxSwap.assetIn != address(0)) {
            bytes memory auxSwapData = _delegateCall(
                address(swapAction),
                abi.encodeWithSelector(swapAction.swap.selector, leverParams.auxSwap)
            );
            upFrontAmount = abi.decode(auxSwapData, (uint256));
        }

        // handle the flash loan swap
        bytes memory swapData = _delegateCall(
            address(swapAction),
            abi.encodeWithSelector(swapAction.swap.selector, leverParams.primarySwap)
        );
        uint256 swapAmountOut = abi.decode(swapData, (uint256));

        // deposit collateral and handle any CDP specific actions
        uint256 collateral = _onIncreaseLever(leverParams, upFrontToken, upFrontAmount, swapAmountOut);

        // derive the amount of normal debt from the swap amount out
        uint256 addDebt = amount + fee;

        // add collateral and debt
        ICDPVault(leverParams.vault).modifyCollateralAndDebt(
            leverParams.position,
            address(this),
            address(this),
            toInt256(collateral),
            toInt256(addDebt)
        );

        underlyingToken.forceApprove(address(flashlender), addDebt);

        return CALLBACK_SUCCESS;
    }
```


The `PositionAction::onFlashLoan` function is the callback for the flash loan, it yet again perform checks for the swap data and if needed performs a swap, then the `_onIncreaseLever` hook is called which per the comments is supposed to deposit collateral, and then `CDPVault::modifyCollateralAndDebt` is called with positive debtDelta and positive collateralDelta.

```solidity
    function modifyCollateralAndDebt(
        address owner,
        address collateralizer,
        address creditor,
        int256 deltaCollateral,
        int256 deltaDebt
    ) public {
 ...
        if (deltaCollateral > 0) {
            uint256 amount = wmul(deltaCollateral.toUint256(), tokenScale);
            token.safeTransferFrom(collateralizer, address(this), amount);
        } else if (deltaCollateral < 0) {
            uint256 amount = wmul(abs(deltaCollateral), tokenScale);
            token.safeTransfer(collateralizer, amount);
        }
...
```

From the snippet we can see that if the delta collateral is a positive number we will take collateral from the collateralizer.

Now the [PositionAction20::_onIncreaseLever](https://github.com/code-423n4/2024-07-loopfi/blob/57871f64bdea450c1f04c9a53dc1a78223719164/src/proxy/PositionAction20.sol#L59-L71) and the [PositionActionPendle::_onIncreaseLever](https://github.com/code-423n4/2024-07-loopfi/blob/57871f64bdea450c1f04c9a53dc1a78223719164/src/proxy/PositionActionPendle.sol#L55-L70) at the end only approve the vault of spending this collateral, due to the fact that calling `CDPVault::modifyCollateralAndDebt` with positive collateralDelta, the contract will try to get the approved amount from the proxy.

However, this is not the case with `PositionAction4626::_onIncreaseLever`:

```solidity
    function _onIncreaseLever(
        LeverParams memory leverParams,
        address upFrontToken,
        uint256 upFrontAmount,
        uint256 swapAmountOut
    ) internal override returns (uint256) {
        uint256 upFrontCollateral;
        uint256 addCollateralAmount = swapAmountOut;
        if (leverParams.collateralToken == upFrontToken && leverParams.auxSwap.assetIn == address(0)) {
            // if there was no aux swap then treat this amount as the ERC4626 token
            upFrontCollateral = upFrontAmount;
        } else {
            // otherwise treat as the ERC4626 underlying
            addCollateralAmount += upFrontAmount;
        }

        address underlyingToken = IERC4626(leverParams.collateralToken).asset();
        // join into the pool if needed
        if (leverParams.auxAction.args.length != 0) {
            address joinToken = swapAction.getSwapToken(leverParams.primarySwap);
            address joinUpfrontToken = upFrontToken;

            if (leverParams.auxSwap.assetIn != address(0)) {
                joinUpfrontToken = swapAction.getSwapToken(leverParams.auxSwap);
            }

            // update the join parameters with the new amounts
            PoolActionParams memory poolActionParams = poolAction.updateLeverJoin(
                leverParams.auxAction,
                joinToken,
                joinUpfrontToken,
                swapAmountOut,
                upFrontAmount,
                underlyingToken
            );

            _delegateCall(address(poolAction), abi.encodeWithSelector(poolAction.join.selector, poolActionParams));

            // retrieve the total amount of collateral after the join
            addCollateralAmount = IERC20(underlyingToken).balanceOf(address(this));
        }

        // deposit into the ERC4626 vault
        IERC20(underlyingToken).forceApprove(leverParams.collateralToken, addCollateralAmount);
        addCollateralAmount =
            IERC4626(leverParams.collateralToken).deposit(addCollateralAmount, address(this)) +
            upFrontCollateral;

        // deposit into the CDP vault
        IERC20(leverParams.collateralToken).forceApprove(leverParams.vault, addCollateralAmount);
//@review - The collateral will already be deposited which means that modifyCollateralAndDebt will revert due to insufficient approval
@>      return ICDPVault(leverParams.vault).deposit(address(this), addCollateralAmount); 
    }
``` 

There is no extra amount added during the hook, which means that all of the collateral meant to be added will be added during the hook's execution making `CDPVault::modifyCollateralAndDebt` revert due to insufficient approval or insufficient balance of the proxy contract.

