# Lines of code

https://github.com/code-423n4/2024-07-loopfi/blob/main/src/proxy/PositionAction.sol#L489


# Vulnerability details

## Impact
`PositionAction#decreaseLever()` fails to work due to insufficient assets and allowance for the flash loan repayment. As a result, anyone who increases the leverage of their position has no way to decrease it by calling `PositionAction#decreaseLever()`, putting them at high risk of being liquidated.

## Proof of Concept
A user who increased the leverage of their position should be able to decrease their leverage  by calling `PositionAction#decreaseLever()`. a specific amount of `WETH` will be borrowed from `flashlender` to repay user's position, then the collateral can be withdrawn from the position and swap to `WETH` to repay the flash loan.
The amount of flash loan repayment is calculated in `Flashlender#creditFlashLoan()`:
```solidity
    function creditFlashLoan(
        ICreditFlashBorrower receiver,
        uint256 amount,
        bytes calldata data
    ) external override nonReentrant returns (bool) {
        uint256 fee = wmul(amount, protocolFee);
@>      uint256 total = amount + fee; //@audit-info total flash loan repayment

        pool.lendCreditAccount(amount, address(receiver));

        emit CreditFlashLoan(address(receiver), amount, fee);

        if (receiver.onCreditFlashLoan(msg.sender, amount, fee, data) != CALLBACK_SUCCESS_CREDIT)
            revert Flash__creditFlashLoan_callbackFailed();

        // reverts if not enough Stablecoin have been send back
@>      underlyingToken.transferFrom(address(receiver), address(pool), total);//@audit-info force receiver to repay flash loan
        pool.repayCreditAccount(total - fee, fee, 0);

        return true;
    }
```
However, the receiver doesn't provide sufficient asset for flash loan repayment, the flash loan fee was not accounted in `subDebt`:
```solidity
    function onCreditFlashLoan(
        address /*initiator*/,
        uint256 /*amount*/,
        uint256 /*fee*/,
        bytes calldata data
    ) external returns (bytes32) {
        if (msg.sender != address(flashlender)) revert PositionAction__onCreditFlashLoan__invalidSender();
        (
            LeverParams memory leverParams,
            uint256 subCollateral,
            address residualRecipient
        ) = abi.decode(data,(LeverParams, uint256, address));

@>      uint256 subDebt = leverParams.primarySwap.amount;//@audit-info subDebt is the amount of asset borrowed from flashlender

        underlyingToken.forceApprove(address(leverParams.vault), subDebt);
        // sub collateral and debt
        ICDPVault(leverParams.vault).modifyCollateralAndDebt(
            leverParams.position,
            address(this),
            address(this),
            0,
            -toInt256(subDebt)
        );

        // withdraw collateral and handle any CDP specific actions
        uint256 withdrawnCollateral = _onDecreaseLever(leverParams, subCollateral);

@>      bytes memory swapData = _delegateCall(
@>          address(swapAction),
@>          abi.encodeWithSelector(
@>              swapAction.swap.selector,
@>              leverParams.primarySwap
@>          )
@>      );//@audit-info the amount of asset swapped out is no above than subDebt 
        uint256 swapAmountIn = abi.decode(swapData, (uint256));

        // swap collateral to stablecoin and calculate the amount leftover
        uint256 residualAmount = withdrawnCollateral - swapAmountIn;

        // send left over collateral that was not needed to payback the flash loan to `residualRecipient`
        if (residualAmount > 0) {

            // perform swap from collateral to arbitrary token if necessary
            if (leverParams.auxSwap.assetIn != address(0)) {
                _delegateCall(
                    address(swapAction),
                    abi.encodeWithSelector(
                        swapAction.swap.selector,
                        leverParams.auxSwap
                    )
                );
            } else {
                // otherwise just send the collateral to `residualRecipient`
                IERC20(leverParams.primarySwap.assetIn).safeTransfer(residualRecipient, residualAmount);
            }
        }

@>      underlyingToken.forceApprove(address(flashlender), subDebt);//@audit-info approved allowance didn't account flash loan fee

        return CALLBACK_SUCCESS_CREDIT;
    }
```
As we can see, `creditFlashLoan()` always revert because the `receiver` doesn't provide sufficient asset and allowance for flash loan repayment.
