        vm.startPrank(BOB);
        console.log("@> BOB deposits 80 ETH to PoolV3");
        mockWETH.approve(address(liquidityPool), type(uint).max);
        liquidityPool.deposit(80 ether, BOB);
        vm.stopPrank();

        console.log("@> BOB shares: %e", liquidityPool.balanceOf(BOB));
        console.log("@> address(this) shares: %e", liquidityPool.balanceOf(address(this)));
        console.log("@> Treasury shares: %e", liquidityPool.balanceOf(liquidityPool.treasury()));

        /**
            Create a loan position, borrowing the same amount as BOB deposits
        */
        console.log("@> Create a loan position, borrowing 80 ETH");
        _modifyCollateralAndDebt(vault, 100 ether, 80 ether);

        /**
            Manipulate the price, forced create bad debt position
        */
        console.log("@> Manipulate spot price down to simulate bad debt position");
        _updateSpot(0.5 ether);


        /**
            Liquidate bad debt position, bad debt incurred to the pool
        */
        address position = address(this);
        uint256 repayAmount = 80 ether;
        mockWETH.mint(EVE, repayAmount);
        vm.startPrank(EVE);
        mockWETH.approve(address(vault), repayAmount);
        console.log("@> Liquidate bad debt position, (repay as much as possible)");

        (uint256 collateral, uint256 debt, , , , ) = vault.positions(position);
        console.log("@> Vault position before:  collateral=%e | debt=%e", collateral, debt);

        vault.liquidatePositionBadDebt(position, repayAmount);

        (collateral, debt, , , , ) = vault.positions(position);
        console.log("@> Vault position after:  collateral=%e | debt=%e", collateral, debt);

        console.log("@> Debt repaid: %e", 80e18 - IERC20(mockWETH).balanceOf(EVE));
        vm.stopPrank();

        /**
