        /**
            BOB attempts to withdraw but fail
        **/

        console.log("@> ETH left in PoolV3: %e", mockWETH.balanceOf(address(liquidityPool)));
        console.log("@> BOB attempts to withdraw 80 ETH but fail");
        vm.startPrank(BOB);
        liquidityPool.redeem(
            liquidityPool.balanceOf(BOB),
            BOB,
            BOB
        );
        vm.stopPrank();
    }
}
