contract TestGearBox is testStarter, MainnetAddresses {
    ...

   function test_audit_GearBoxV3ConnectorDirectKeeper() public {
        (, address _baseToken) = registry.getVaultAddresses(0); // USDC
        console2.log("basetoken : %s" , _baseToken);
