        console.log("Valid Positions amount: ", positions.length-1);
        console.log("now, only connector2 and connector3 are holding USDC positions");

        connector1holdingPositionIndex1 = registry.getHoldingPositionIndex(0, positionId, address(connector1), abi.encode(address(connector1)));
