        );

        addTokenToNoyaOracle(address(USDC), address(chainlinkOracle));
        addTokenToNoyaOracle(address(STETH), address(chainlinkOracle));
        addTokenToNoyaOracle(address(0), address(chainlinkOracle));
        addTokenToNoyaOracle(address(840), address(chainlinkOracle));
        console.log(
            "----------- Test getValue ETH using route with 2 Sources-----------"
        );
        vm.expectRevert(
            abi.encodeWithSelector(
                ChainlinkOracleConnector
                    .NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE
                    .selector,
                address(USDC),
                address(1),
                address(0) // primary source (non-existent)
            )
        ); 
        noyaOracle.getValue(address(USDC), address(STETH), 1_000_000);
    }
```

