# Lines of code

https://github.com/code-423n4/2024-04-noya/blob/main/contracts/helpers/valueOracle/oracles/ChainlinkOracleConnector.sol#L99-L101


# Vulnerability details

## Impact
If the ETH/USD price feed is used with ChainlinkOracleConnector.sol, the returned price will have an incorrect decimals amount.

## Proof of Concept
`ChainlinkOracleConnector.sol` uses hardcoded addresses for `ETH` (address(0)) and `USD` (address(840)).

```solidity
    function getValue(address asset, address baseToken, uint256 amount) public view returns (uint256) {
        if (asset == baseToken) {
            return amount;
        }

        (address primarySource, bool isPrimaryInverse) = getSourceOfAsset(asset, baseToken);
        if (primarySource == address(0)) {
            revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(asset, baseToken, primarySource);
        }
        address decimalsSource = isPrimaryInverse ? baseToken : asset;
>>      decimalsSource = decimalsSource == ETH || decimalsSource == USD ? primarySource : decimalsSource;
        return getValueFromChainlinkFeed(
            AggregatorV3Interface(primarySource), amount, getTokenDecimals(decimalsSource), isPrimaryInverse
        );
    }
```

Oracle configures the `decimalSource` value based on the direction of conversion and the base token, to determine the decimal count of the resulting value.

```solidity
    function getValueFromChainlinkFeed(
        AggregatorV3Interface source,
        uint256 amountIn,
>>      uint256 sourceTokenUnit,
        bool isInverse
    ) public view returns (uint256) {
        ___SNIP---
        if (isInverse) {
            return (amountIn * sourceTokenUnit) / uintprice;
        }
        return (amountIn * uintprice) / (sourceTokenUnit);
    }
```

For example, when converting DAI to ETH, the result should have 18 decimals. However, the issue arises when both the base token and the asset are hardcoded addresses, such as in the case of the ETH/USD feed. When using the `getValue(address(0), address(840), 1e18)` function, the returned value is `2903258418580000000000`, which contains 18 decimals instead of the expected 8 like other USD feeds. In contrast, when using the `getValue(address(DAI), address(840), 1e18)` function, the returned value `99993032` has the correct decimal count of 8.

```solidity
    function testChainlink0() public {
        console.log("\n-----------------\n");
        vm.prank(owner);
        addTokenToChainlinkOracle(address(DAI), address(840), address(DAI_USD_FEED));
        console.log("VAL: ", chainlinkOracle.getValue(address(DAI), address(840), 1e18));
    }

    function testChainlink1() public {
        console.log("\n-----------------\n");
        vm.prank(owner);
        addTokenToChainlinkOracle(address(0), address(840), 0x5f4eC3Df9cbd43714FE2740f5E3616155c5b8419);
        console.log("VAL: ", chainlinkOracle.getValue(address(0), address(840), 1e18));
    }
```

A more complicated example for a DAI to ETH conversion scenario

```solidity
    function testETHUSD() public {
        vm.startPrank(owner);

        address ETH_USD_FEED = 0x5f4eC3Df9cbd43714FE2740f5E3616155c5b8419;

        addTokenToChainlinkOracle(DAI, address(840), DAI_USD_FEED);
        addTokenToChainlinkOracle(address(0), address(840), address(ETH_USD_FEED));

        addTokenToNoyaOracle(DAI, address(chainlinkOracle));
        addTokenToNoyaOracle(address(0), address(chainlinkOracle));
        addTokenToNoyaOracle(address(840), address(chainlinkOracle));

        address[] memory assets = new address[](1);
        assets[0] = address(840);

        noyaOracle.updatePriceRoute(address(DAI), address(0), assets);

        uint256 value = noyaOracle.getValue(address(DAI), address(0), 3000e18);
        console.log("VAL: ", value);
    }
```

The result is 103324972 ETH for 3000e18 DAI which is clearly not enough.
