        require(currentWithdrawGroup.isStarted == true && currentWithdrawGroup.isFullfilled == false);
        uint256 neededAssets = neededAssetsForWithdraw();
+        console.log("neededAssets: ", neededAssets);
+        console.log("Current total CB: ", currentWithdrawGroup.totalCBAmount);
+        console.log("Amount asked for withdraw: ", amountAskedForWithdraw);
        if (neededAssets != 0 && amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount) {
            revert NoyaAccounting_NOT_READY_TO_FULFILL();
        } // @audit when a resetMiddle happens for withdraw, the `currentWithdrawGroup.totalCBAmount` will be almost double what the `amountAskedForWithdraw` variable is and will force a revert
...
}
```

Keep in mind, index being the first element in the withdrawal queue or last or middle is irrelevant for this to occur and will run into the DoS state irrespective of the `newMiddle` argument passed by the manager below:

```solidity
function resetMiddle(uint256 newMiddle, bool depositOrWithdraw) public onlyManager {
...
}
```

