        //     // ------------------------------ calculate shares ------------------------------
        vm.startPrank(owner);
        accountingManager.calculateDepositShares(3);
        vm.warp(block.timestamp + 35 minutes);
        accountingManager.executeDeposit(10, connector, "");
        vm.stopPrank();

        uint256 bobShares = accountingManager.balanceOf(bob);
        console.log("Bob shares: ", bobShares);
