# Lines of code

https://github.com/code-423n4/2024-04-noya/blob/9c79b332eff82011dcfa1e8fd51bad805159d758/contracts/helpers/SwapHandler/GenericSwapAndBridgeHandler.sol#L29-L32


# Vulnerability details

[SwapAndBridgeHandler::onlyExistingRoute](https://github.com/code-423n4/2024-04-noya/blob/9c79b332eff82011dcfa1e8fd51bad805159d758/contracts/helpers/SwapHandler/GenericSwapAndBridgeHandler.sol#L29-L32)

### Description
`SwapAndBridgeHandler` is used to swap and bridge assets. It contains also a list of `routes` which point to the implementation contracts used for the swap/bridge implementations.

The issue is that `onlyExistingRoute` returns true even when route is disabled.
`verifyRoute()` call will always succeed, making it more probable that a disabled route will be used.

### Root Cause
Inaccurate access control checks

### Impact
Possible loss of funds when using a route that's currently disabled.

### PoC

Paste the following code under `testFoundry/RouteDisable.t.sol` and run with `forge test --mt testRouteDisable -vvv`:

```javascript
// SPDX-License-Identifier: Apache-2.0
pragma solidity 0.8.20;

import "./utils/testStarter.sol";
import "contracts/helpers/BaseConnector.sol";
import "./utils/resources/OptimismAddresses.sol";
import { SwapAndBridgeHandler, SwapRequest, ISwapAndBridgeHandler } from "contracts/helpers/SwapHandler/GenericSwapAndBridgeHandler.sol";

contract RouteDisable is testStarter, OptimismAddresses {
    using SafeERC20 for IERC20;

    address connector;

    function setUp() public {
        // --------------------------------- set env --------------------------------
        uint256 fork = vm.createFork(RPC_URL, 117_307_857);
        vm.selectFork(fork);
        console.log("Test timestamp: %s", block.timestamp);

        // --------------------------------- deploy the contracts ---------------------------------
        vm.startPrank(owner);
        deployEverythingNormal(USDC);

        // --------------------------------- init connector ---------------------------------
        connector = address(new BaseConnector(BaseConnectorCP(registry, 0, swapHandler, noyaOracle)));

        // ------------------- add connector to registry -------------------
        addConnectorToRegistry(vaultId, connector);

        addTrustedTokens(vaultId, address(accountingManager), USDC);
        addTrustedTokens(vaultId, address(accountingManager), WETH);

        addTokenToChainlinkOracle(address(USDC), address(840), address(USDC_USD_FEED));
        addTokenToNoyaOracle(address(USDC), address(chainlinkOracle));

        addTokenToChainlinkOracle(address(WETH), address(840), address(ETH_USD_FEED));
        addTokenToNoyaOracle(address(WETH), address(chainlinkOracle));

        addRoutesToNoyaOracle(address(WETH), address(USDC), address(840));

        console.log("Tokens added to registry");
        registry.addTrustedPosition(vaultId, 0, address(accountingManager), false, false, abi.encode(USDC), "");
        registry.addTrustedPosition(vaultId, 0, address(accountingManager), false, false, abi.encode(WETH), "");
        console.log("Positions added to registry");

        accountingManager.updateValueOracle(noyaOracle);
    }

    function testRouteDisable() public {
        // Not reverting here means route is verified successfully
        swapHandler.verifyRoute(0, address(lifiImplementation));

        // Example of failing verification
        vm.expectRevert();
        swapHandler.verifyRoute(0, owner);

        // Now, a route is disabled for some reason
        swapHandler.setEnableRoute(0, false);

        // Verifying route - successful, when it should fail
        swapHandler.verifyRoute(0, address(lifiImplementation));

        // swap USDC for WETH, via disabled route
        uint256 _amount = 10 * 1e6;
        _dealWhale(baseToken, address(connector), USDC_Whale, _amount);
        vm.startPrank(owner);
        assertTrue(IERC20(USDC).balanceOf(address(connector)) == _amount, "E1");
        bytes memory _data =
            hex"";

        address[] memory tokensIn = new address[](1);
        address[] memory tokensOut = new address[](1);
        uint256[] memory amountsIn = new uint256[](1);
        bytes[] memory swapData = new bytes[](1);
        uint256[] memory routeIds = new uint256[](1);

        tokensIn[0] = USDC;
        tokensOut[0] = WETH;
        amountsIn[0] = _amount;
        swapData[0] = _data;
        routeIds[0] = 0;

        BaseConnector(connector).swapHoldings(tokensIn, tokensOut, amountsIn, swapData, routeIds);
        assertTrue(IERC20(WETH).balanceOf(address(connector)) > 0); // Connector obtained WETH via disabled route
    }
}
```

### Suggested Mitigation
Update `SwapAndBridgeHandler::onlyExistingRoute` to the following:
```javascript
modifier onlyExistingRoute(uint256 _routeId) {
    if (routes[_routeId].route == address(0) || !routes[_routeId].isEnabled) revert RouteNotFound();
    _;
}
```

To further simplify the logic, just assume that if a route is added, it is `enabled`.
In this way you just need to add/remove routes and omit having to check `enabled` state.


