                deadline: block.timestamp,
                maxAPR: 1e18,
                exactAmountIn: true
            })
        );
        console.log("--- Buy 5200$ credit back from Alice at much lower APR");
        printBalance(alice);
        printBalance(bob);
        //Result:
        //alice got 5500$ debt. 3 ETH collateral. and no cash from borrowing.
