# Vulnerability details

## Description
The `ILOPool.buy(uint256, address)` function does not check if the whitelisted address has already bought the maximum amount of tokens allowed, in checks the amount of tokens associated to a token ID.

Therefore `maxCapPerUser` can be bypassed by transferring the ERC721 token to another address and then buying more tokens.

## Impact
* Whitelisted addresses can bypass the `maxCapPerUser` by transferring the ERC721 token to another address and buying more tokens.

## POC
1. Bob is whitelisted and buys the maximum amount of tokens allowed, reciving an NFT from ILOPool
2. Bob transfers the NFT to another controlled address
3. Bob buys more tokens from the controlled address.

If Bob has enough funds he can buy all remaining tokens.

<details>
    <summary>
        Coded POC
    </summary>

    ```solidity
        // Add to ILOPool.t.sol 
        function testBypassMaxCapPerUserWithERC721Transfer() public{
            address notWhitelisted = address(uint160(uint256(keccak256(abi.encode("NOT WHITELISTED")))));

            // Get max cap per user
            uint256 maxCapPerUser = _getInitPoolParams().maxCapPerUser;

            // Investor buy for maxCapPerUser
            _prepareBuyFor(INVESTOR);
            (uint256 tokenId,) = _buy(SALE_START+1, maxCapPerUser);

            // Transfer ERC721 to not whitelisted address
            vm.startPrank(INVESTOR);
            IILOPool(iloPool).transferFrom(INVESTOR, notWhitelisted, tokenId);

            // Investor buy more
            // This should revert because investor already reach max cap per user, but it does not    
            (uint256 tokenId2,) = IILOPool(iloPool).buy(0.1 ether, INVESTOR);
            vm.stopPrank();
        }
    ```
</details>

## Recommended mitigation
### Option A
If the protocol wants to avoid the commercialization of these tokens in the secondary market, the ERC721 function can be overridden to prevent the transfer of these tokens, at least until launch time.

### Option B
If the protocol does not care about the commercialization of these tokens in the secondary market, simply create another mapping to track the amount of tokens bought by a whitelisted address.

```diff
contract ILOPool is
    ERC721,
    IILOPool,
    ILOWhitelist,
    ILOVest,
    Initializable,
    Multicall,
    ILOPoolImmutableState,
    LiquidityManagement
{
    // ...
+   mapping(address => uint256) public _whitelistedAmountBought;
    // ...

    function buy(uint256 raiseAmount, address recipient)
        external override 
        returns (
            uint256 tokenId,
            uint128 liquidityDelta
        )
    {
        require(_isWhitelisted(recipient), "UA");
        require(block.timestamp > saleInfo.start && block.timestamp < saleInfo.end, "ST");
        // check if raise amount over capacity
        require(saleInfo.hardCap - totalRaised >= raiseAmount, "HC");
        totalRaised += raiseAmount;

        require(totalSold() <= saleInfo.maxSaleAmount, "SA");

        // if investor already have a position, just increase raise amount and liquidity
        // otherwise, mint new nft for investor and assign vesting schedules

+       if (_whitelistedAmountBought[recipient] + raiseAmount < saleInfo.maxCapPerUser) {
+           _whitelistedAmountBought[recipient] += raiseAmount;
            if (balanceOf(recipient) == 0) {
                _mint(recipient, (tokenId = _nextId++));
                _positionVests[tokenId].schedule = _vestingConfigs[0].schedule;
            } else {
                tokenId = tokenOfOwnerByIndex(recipient, 0);
            }
+       }

        Position storage _position = _positions[tokenId];
-       require(raiseAmount <= saleInfo.maxCapPerUser - _position.raiseAmount, "UC");
-       _position.raiseAmount += raiseAmount;

        // get amount of liquidity associated with raise amount
        if (RAISE_TOKEN == _cachedPoolKey.token0) {
            liquidityDelta = LiquidityAmounts.getLiquidityForAmount0(SQRT_RATIO_X96, SQRT_RATIO_UPPER_X96, raiseAmount);
        } else {
            liquidityDelta = LiquidityAmounts.getLiquidityForAmount1(SQRT_RATIO_LOWER_X96, SQRT_RATIO_X96, raiseAmount);
        }

        require(liquidityDelta > 0, "ZA");

        // calculate amount of share liquidity investor recieve by INVESTOR_SHARES config
        liquidityDelta = uint128(FullMath.mulDiv(liquidityDelta, _vestingConfigs[0].shares, BPS));

        // increase investor's liquidity
        _position.liquidity += liquidityDelta;

        // update total liquidity locked for vest and assiging vesing schedules
        _positionVests[tokenId].totalLiquidity = _position.liquidity;

        // transfer fund into contract
        TransferHelper.safeTransferFrom(RAISE_TOKEN, msg.sender, address(this), raiseAmount);

        emit Buy(recipient, tokenId, raiseAmount, liquidityDelta);
    }
}
```


