        IERC20 _collateralToken,
        uint256 _amount,
        uint256 _referralId
    ) public nonReentrant notPaused {
        SNIP...

        // Calculate how much ezETH to mint
565:    uint256 ezETHToMint = renzoOracle.calculateMintAmount(
566:        totalTVL,
567:        collateralTokenValue,
568:        ezETH.totalSupply()
569:    );

