  Licenser     vaultManagerLicenser;
  Licenser     vaultLicenser;
  Dyad         dyad;
  VaultManager vaultManager;
  VaultManagerV2 vaultManagerV2;
  Vault        vault;
  Vault        vaultv2;
  Payments     payments;
}

contract DeployBase is Script {

  function deploy(
    address _owner, 
    address _dNft,
    address _asset,
    address _oracle, 
    uint    _fee,
    address _feeRecipient
  )
    public 
    payable 
    returns (
      Contracts memory
    ) {
      DNft dNft = DNft(_dNft);

      vm.startBroadcast();  // ----------------------

      Licenser vaultManagerLicenser = new Licenser();
      Licenser vaultLicenser        = new Licenser();

      Dyad dyad                     = new Dyad(
        vaultManagerLicenser
      );

      VaultManager vaultManager     = new VaultManager(
        dNft,
        dyad,
        vaultLicenser
      );

      VaultManagerV2 vaultManagerV2 = new VaultManagerV2(
        dNft,
        dyad,
        vaultLicenser
      );

      Vault vault                   = new Vault(
        vaultManager,
        ERC20(_asset),
        IAggregatorV3(_oracle)
      );

      Vault vaultv2                   = new Vault(
        vaultManagerV2,
        ERC20(_asset),
        IAggregatorV3(_oracle)
      );

      Payments payments             = new Payments(
        vaultManager,
        IWETH(_asset)
      );

      //
      payments.setFee(_fee);
      payments.setFeeRecipient(_feeRecipient);

      // 
      vaultManagerLicenser.add(address(vaultManager));
      vaultManagerLicenser.add(address(vaultManagerV2));
      vaultLicenser       .add(address(vault));

      //
      vaultManagerLicenser.transferOwnership(_owner);
      vaultLicenser       .transferOwnership(_owner);
      payments            .transferOwnership(_owner);

      vm.stopBroadcast();  // ----------------------------

      return Contracts(
        vaultManagerLicenser,
        vaultLicenser,
        dyad,
        vaultManager,
        vaultManagerV2,
        vault, 
        vaultv2,
        payments
      );
  }
}

