60:         Vault vault = Vault(vaults[i]);
61:         tvl += vault.asset().balanceOf(address(vault)) 
62:                 * vault.assetPrice() * 1e18
63:                 / (10**vault.asset().decimals()) 
64:                 / (10**vault.oracle().decimals());
