    );

    unboundedKerosineVault.setDenominator(kerosineDenominator);

+    kerosineManager.add(address(unboundedKerosineVault));
+    // kerosineManager.add(address(boundedKerosineVault));

+   kerosineManager.transferOwnership(MAINNET_OWNER);

    unboundedKerosineVault.transferOwnership(MAINNET_OWNER);
    boundedKerosineVault.  transferOwnership(MAINNET_OWNER);

    vaultLicenser.add(address(ethVault));
    vaultLicenser.add(address(wstEth));
-   vaultLicenser.add(address(unboundedKerosineVault));
-   // vaultLicenser.add(address(boundedKerosineVault));
```

This implementation however introduces problem with calculating correct `assetPrice` inside `Vault.kerosine.unbounded.sol`.

```solidity
function assetPrice() 
    public 
    view 
    override
    returns (uint) {
      uint tvl;
      address[] memory vaults = kerosineManager.getVaults(); // in current implementation this line of code is wstEth and wEth
      uint numberOfVaults = vaults.length;
      for (uint i = 0; i < numberOfVaults; i++) {
        Vault vault = Vault(vaults[i]);
        tvl += vault.asset().balanceOf(address(vault)) 
                * vault.assetPrice() * 1e18
                / (10**vault.asset().decimals()) 
                / (10**vault.oracle().decimals());
      uint numerator   = tvl - dyad.totalSupply();
      uint denominator = kerosineDenominator.denominator();
      return numerator * 1e8 / denominator;
  }
```

Probably there's need to rewrite functionality of `vaultLicenser` and `kerosineManager` and I'm leaving it blank, because I have no idea how devs would like their contracts to look like.


