# Vulnerability details

**Impact**
For a user to be liquidated in the protocol it requires the liquidator to own a DNft (which receives the liquidation reward), and burn the same amount of DYAD that the DNft to be liquidated has minted. However if a user attempts to mint DYAD in order to liquidiate a DNft that is under `MIN_COLLATERIZATION_RATIO` this action can inadvertently improve the DNft's collateral ratio, thus making them impossible to liquidiate.

This issue combined with the fact that the liquidator has to be a DNft holder to profit from liquidating the position contribute to making it more difficult for users to liquidate positions increasing the possibility that bad debt is built up in the protocol.

**Proof Of Concept**
Add the following test + helpers to `v2.t.sol` to show this:

```solidity
  function testLiqMovesKeroPrice() public {
    licenseVaultManager();
    // Create a dummy weth vault & dummy oracle to simplify testing ETH collateral price changes, add it to kerosene manager
    (Vault dummyWeth, DummyOracle dummyOracle) = addDummyWethVault();
    vm.prank(MAINNET_OWNER);
    contracts.kerosineManager.add(address(dummyWeth));

    // Add to the vault tvl to avoid tvl - dyad.totalSupply underflow revert
    boostTVL(address(dummyWeth), 1000 ether);

    // Set up alice with a DNft, WETH & Kerosene
    address alice = makeAddr("alice");
    uint aliceTokenId = sendNote(alice);
    getWETH(alice, 10 ether);
    uint keroseneAmount = 360_000 ether;
    sendKerosene(alice, keroseneAmount); 

    // Alice deposits both Weth & Kerosene
    vm.startPrank(alice);
    contracts.vaultManager.add(aliceTokenId, address(dummyWeth));
    contracts.vaultManager.addKerosene(aliceTokenId, address(contracts.unboundedKerosineVault));

    WETH(payable(MAINNET_WETH)).approve(address(contracts.vaultManager), 10 ether);
    contracts.vaultManager.deposit(aliceTokenId, address(dummyWeth), 10 ether);

    Kerosine(MAINNET_KEROSENE).approve(address(contracts.vaultManager), keroseneAmount);
    contracts.vaultManager.deposit(aliceTokenId, address(contracts.unboundedKerosineVault), keroseneAmount);

    // Alice mints dyad
    contracts.vaultManager.mintDyad(aliceTokenId, 30000 ether, alice);

    // Confirm Alice's DNft has a healthy position 
    uint aliceCollatRatio = contracts.vaultManager.collatRatio(aliceTokenId);
    assert(aliceCollatRatio >= contracts.vaultManager.MIN_COLLATERIZATION_RATIO());

    // Simulate ETH price dropping 5% (to lower Alice's collateral value)
    dummyOracle.setAnswer(285000);

    // Confirm Alice's DNft can now be liquidated
    uint aliceCollatRatioNow = contracts.vaultManager.collatRatio(aliceTokenId);
    assert(aliceCollatRatioNow < contracts.vaultManager.MIN_COLLATERIZATION_RATIO());

    // Bob attempts to liquidate Alice
    address bob = makeAddr("bob");
    uint bobTokenId = sendNote(bob);
    getWETH(bob, 30 ether);

    vm.startPrank(bob);
    contracts.vaultManager.add(bobTokenId, address(contracts.ethVault));
    WETH(payable(MAINNET_WETH)).approve(address(contracts.vaultManager), 30 ether);
    contracts.vaultManager.deposit(bobTokenId, address(contracts.ethVault), 30 ether);
    contracts.vaultManager.mintDyad(bobTokenId, 30000 ether, bob);

    // Liquidation Fails because Bob's deposit/mint changed determinsitic Kerosene value 
    ERC20(MAINNET_DYAD).approve(address(contracts.vaultManager), 30000 ether);
    vm.expectRevert(IVaultManager.CrTooHigh.selector);
    contracts.vaultManager.liquidate(aliceTokenId, bobTokenId);
  }

  function sendNote(address _to) internal returns(uint) {
    vm.startPrank(MAINNET_OWNER);
    uint tokenId = DNft(MAINNET_DNFT).mintInsiderNft(_to);    
    vm.stopPrank();
    return tokenId;
  }

  function sendKerosene(address _to, uint _amount) internal {
    vm.startPrank(MAINNET_OWNER);
    Kerosine(MAINNET_KEROSENE).transfer(_to, _amount);
    vm.stopPrank();
  }

  function licenseVaultManager() internal {
    Licenser licenser = Licenser(MAINNET_VAULT_MANAGER_LICENSER);
    vm.prank(MAINNET_OWNER);
    licenser.add(address(contracts.vaultManager));
  }

  function addDummyWethVault() internal returns(Vault, DummyOracle) {
    // Set up a dummy weth vault to help simulate price movement
    DummyOracle dummyOracle = new DummyOracle();
    Vault dummyWeth = new Vault(contracts.vaultManager,ERC20(MAINNET_WETH), IAggregatorV3(address(dummyOracle))); 
    vm.prank(MAINNET_OWNER);
    contracts.vaultLicenser.add(address(dummyWeth));
    return (dummyWeth, dummyOracle);
  }

  function getWETH(address _to, uint _amount) internal {
    vm.deal(_to, _amount);
    vm.startPrank(_to);
    WETH(payable(MAINNET_WETH)).deposit{value: _amount}();
    vm.stopPrank();
  }

  function boostTVL(address _vault, uint _amount) internal {
    getWETH(_vault, _amount);
  }
```

**Recommended Mitigation**
The issue stems from requiring the user to deposit collateral, mint dyad and then liquidate the at risk DNft in 3 separate transactions, each of which changes the value of Kerosene meaning `collatRatio` of the DNft in question changes after each step in the attempted liquidation. Providing one function which allows a user to do all 3 would allow users to liquidate at risk DNfts without the risk of depositing collateral, minting dyad and then finding out that their transactions have made it so the DNft in question can no longer be liquidated.


