# Vulnerability details

## Impact
The assetPrice function in the UnboundedKerosineVault contract performs arithmetic operations without proper overflow/underflow checks. This can lead to potential integer overflows or underflows, resulting in incorrect calculations and unexpected behavior.

## Proof of Concept
Here's a proof of concept demonstrating how the assetPrice function can be exploited due to the lack of overflow/underflow checks:

   pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract MockVault {
    ERC20 public asset;
    uint256 public assetPrice;

    constructor(ERC20 _asset, uint256 _assetPrice) {
        asset = _asset;
        assetPrice = _assetPrice;
    }
}

contract MockDyad {
    uint256 public totalSupply;

    constructor(uint256 _totalSupply) {
        totalSupply = _totalSupply;
    }
}

contract MockKerosineDenominator {
    uint256 public denominator;

    constructor(uint256 _denominator) {
        denominator = _denominator;
    }
}

contract ExploitUnboundedKerosineVault {
    UnboundedKerosineVault public unboundedKerosineVault;
    MockVault[] public mockVaults;
    MockDyad public mockDyad;
    MockKerosineDenominator public mockKerosineDenominator;

    constructor(
        address _unboundedKerosineVault,
        ERC20[] memory _assets,
        uint256[] memory _assetPrices,
        uint256 _totalSupply,
        uint256 _denominator
    ) {
        unboundedKerosineVault = UnboundedKerosineVault(_unboundedKerosineVault);

        for (uint256 i = 0; i < _assets.length; i++) {
            mockVaults.push(new MockVault(_assets[i], _assetPrices[i]));
        }

        mockDyad = new MockDyad(_totalSupply);
        mockKerosineDenominator = new MockKerosineDenominator(_denominator);

        // Set the mock contracts in the UnboundedKerosineVault
        unboundedKerosineVault.setDenominator(mockKerosineDenominator);
        // Assume the attacker has the necessary permissions to set the mock contracts
    }

    function exploitAssetPrice() external view returns (uint256) {
        return unboundedKerosineVault.assetPrice();
    }
}



## Tools Used
Remix  and manual review
## Recommended Mitigation Steps
1. Use safe math libraries or OpenZeppelin's SafeMath library for arithmetic operations to prevent integer overflows and underflows.
2. Implement proper input validation and bounds checking for all input parameters involved in the assetPrice calculation to ensure they are within the expected range.
3. Implement error handling and revert conditions to gracefully handle cases where an overflow or underflow is detected.

Here's an example of how the assetPrice function can be modified to use OpenZeppelin's SafeMath library for arithmetic operations:

    import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract UnboundedKerosineVault is KerosineVault {
    using SafeMath for uint256;

    // ...

    function assetPrice() public view override returns (uint256) {
        uint256 tvl;
        address[] memory vaults = kerosineManager.getVaults();
        uint256 numberOfVaults = vaults.length;

        for (uint256 i = 0; i < numberOfVaults; i++) {
            Vault vault = Vault(vaults[i]);
            tvl = tvl.add(
                vault.asset().balanceOf(address(vault))
                    .mul(vault.assetPrice())
                    .mul(1e18)
                    .div(10 ** vault.asset().decimals())
                    .div(10 ** vault.oracle().decimals())
            );
        }

        uint256 numerator = tvl.sub(dyad.totalSupply());
        uint256 denominator = kerosineDenominator.denominator();
        return numerator.mul(1e8).div(denominator);
    }

    // ...
}

In this modified version, the SafeMath library is used for all arithmetic operations involving addition, subtraction, multiplication, and division, ensuring that potential overflows and underflows are prevented.


