      for (uint i = 0; i < numberOfVaults; i++) {
          Vault vault      = Vault(vaults[id].at(i));
          uint  collateral = vault.id2asset(id).mulWadUp(liquidationAssetShare);
@>          vault.move(id, to, collateral); // @audit rolls over the backing collateral inside the liquidated NOTE into the other NOTE
      }
      emit Liquidate(id, msg.sender, to);
  }
```

```solidity
function move(
    uint from,
    uint to,
    uint amount
  )
    external
      onlyVaultManager
  {
@>    id2asset[from] -= amount; // @note removes asset from NOTE being liquidated
@>    id2asset[to]   += amount; // @note adds the asset to this other NOTE
    emit Move(from, to, amount);
  }
```

```solidity
function withdraw(
    uint    id,
    address vault,
    uint    amount,
    address to
  ) 
    public
@>      isDNftOwner(id) // @note must be the owner of NOTE NFT to withdraw
  {
    ...
    _vault.withdraw(id, to, amount); // @audit what if note owner is not the same person who liquidated the previous NOTE and rolled over collateral into this other NOTE? cannot withdraw!
    ...
  }
```

Suppose the following series of transactions occur:
- Bob has an under-backed `NOTE` that needs to be liquidated and no longer participates as a user in the DYAD protocol
- George decides to take on the liquidation, mints DYAD (with any `NOTE` id), and runs Bob `NOTE` liquidations (burning DYAD from his (George) account). Specifying ID 1 as the ID of Bob, and ID 2 as the ID of Alice's `NOTE` aka `to`
- George cannot withdraw the rolled-over assets tied to the underlying `NOTE`

Since anyone can run another user's liquidation, this issue will happen because naturally similar to the lending world, loan takers generally do not liquidate their positions; someone else does it for the health of the protocol. In this case where Alice can choose to hold on to the rolled over asset, George would be forced to forgo the collateral since Alice can withdraw just as much as the vault tied to her NOTE has recorded as assets in her NOTE token:

```solidity
function move(
    uint from,
    uint to,
    uint amount
  )
    external
      onlyVaultManager
  {
    id2asset[from] -= amount;
    id2asset[to]   += amount; // @roll over assets
    emit Move(from, to, amount);
  }

function withdraw(
    uint    id,
    address to,
    uint    amount
  ) 
    external 
      onlyVaultManager
  {
    id2asset[id] -= amount; // @note can withdraw as much
    asset.safeTransfer(to, amount); 
    emit Withdraw(id, to, amount);
  }
```

Follow the setup guide and run the test with `forge test --mt test_cannot_pull_coll --via-ir -vvv`

