        );

        // there is still debt
        (debt,,,,) = vault.loanInfo(TEST_NFT);
        console.log("Debt: %s", debt);

        // NFT was NOT returned to owner
        assertEq(NPM.ownerOf(TEST_NFT), address(vault));
    }
```

