## Proof of Concept

when upd(chainlink last round timestamp) == block.timestamp，it will update `upd =  block.timestamp`，and return `upd > heartBeat[_tokenAddress]`，it will return ture:

```solidity
function _chainLinkIsDead(
        address _tokenAddress
    )
        internal
        view
        returns (bool)
    {
        // @TODO: Add a check for TWAP comparison on 2.5%
        // if TWAP exists for the token.
    if (heartBeat[_tokenAddress] == 0) {
        revert HeartBeatNotSet();
    }

    uint80 latestRoundId = getLatestRoundId(
        _tokenAddress
    );

    uint256 upd = _getRoundTimestamp(
        _tokenAddress,
        latestRoundId
    );

    unchecked {
        upd = block.timestamp < upd
            ? block.timestamp
            : block.timestamp - upd;

        return upd > heartBeat[_tokenAddress];
    }
}
```

