-480     (price, ) = oracle.getPriceData();
+        uint256 timestamp;
+        (price, timestamp) = oracle.getPriceData();
481      require(
482        price > MINIMUM_OUSG_PRICE,
483        "OUSGInstantManager::getOUSGPrice: Price unexpectedly low"
484      );
+        require(
+          block.timestamp < timestamp + 48 hours,
+          "OUSGInstantManager::getOUSGPrice: Price unexpectedly old"
+        );
485    }
```

[rOUSG.getOUSGPrice()](https://github.com/code-423n4/2024-03-ondo-finance/blob/main/contracts/ousg/rOUSG.sol#L378-L380)

