    function initializeContracts(address _owner) internal {
        reserveAsset = new MockERC20("reserveMock", "mkTkn");

        rToken = new RToken("rMock", "mkTkn", _owner, address(reserveAsset));

        debtToken = new DebtToken("debtMock", "mkTkn", _owner);

