    ...........
    ...........
    ...........

// Test unfair reward distribution
describe("reward distribution", function () {
    const [numGenerations, numValidations] = [1, 5];
    const scores = [
        parseEther("100"), // high score
        parseEther("0.8"),
        parseEther("120"), // high score
        parseEther("0.4"),
